function postprocess_state = cerupp_section6a_postprocess(postprocess_inputs, varargin)
%CERUPP_SECTION6A_POSTPROCESS Own the end-of-run plots, CSVs, and warnings.
% Consume the post-run state groups and emit the standard plots, CSVs, and warning updates.
% Call this only when run_postprocessing_flag=true; the returned postprocess_state carries the updated run_warn_state.

    if nargin == 1 && isstruct(postprocess_inputs)
        cfg = postprocess_inputs;
        grid_state = struct_utils.req_struct_field( ...
            cfg, 'grid_state', 'cerupp_section6a_postprocess.postprocess_inputs');
        medium_state = struct_utils.req_struct_field( ...
            cfg, 'medium_state', 'cerupp_section6a_postprocess.postprocess_inputs');
        output_state = struct_utils.req_struct_field( ...
            cfg, 'output_state', 'cerupp_section6a_postprocess.postprocess_inputs');
        diag_state = struct_utils.req_struct_field( ...
            cfg, 'diag_state', 'cerupp_section6a_postprocess.postprocess_inputs');
        final_state = struct_utils.req_struct_field( ...
            cfg, 'final_state', 'cerupp_section6a_postprocess.postprocess_inputs');
    elseif nargin == 5
        grid_state = postprocess_inputs;
        medium_state = varargin{1};
        output_state = varargin{2};
        diag_state = varargin{3};
        final_state = varargin{4};
    else
        error('CerUPP:InvalidPostprocessPhaseInputs', ...
            ['cerupp_section6a_postprocess requires either one grouped ', ...
             'postprocess_inputs struct or the five grouped state inputs.']);
    end
    run_warn_state = struct();
    section6_output_io_failure_count_before = 0;
    requested_outputs_complete = true;
    requested_outputs_skipped_reason = '';
    family_ledger = struct();
    postprocess_phase_ok = true;
    error_id = '';
    error_message = '';

    try
        runtime_state = struct_utils.req_struct_field( ...
            final_state, 'runtime', 'cerupp_section6a_postprocess.final_state');
        summary_state = struct_utils.req_struct_field( ...
            final_state, 'summary', 'cerupp_section6a_postprocess.final_state');
        postprocess_band_support = require_postprocess_band_contract_local(medium_state);
        % Alias the repeated grid, medium, and threshold values reused
        % throughout this postprocess pass.

    x = grid_state.x;
    y = grid_state.y;
    t = grid_state.t;
    kx = grid_state.kx;
    ky = grid_state.ky;
    lambda_window = grid_state.lambda_window;
    omega_fund = grid_state.omega_fund;
    ix_axis0 = grid_state.ix_axis0;
    iy_axis0 = grid_state.iy_axis0;
    x_cut = grid_state.x_cut;
    eps_safe = grid_state.eps_safe;
    n = grid_state.n;
    delta_t = grid_state.delta_t;

    plasma_flag = medium_state.plasma_flag;
    c = medium_state.c;
    i_laser_peak = medium_state.i_laser_peak;
    rho_nt = medium_state.rho_nt;
    lambda_visible_band_min = medium_state.lambda_visible_band_min;
    lambda_visible_band_max = medium_state.lambda_visible_band_max;
    chromatic_onset_bin_width = medium_state.chromatic_onset_bin_width;
    lambda_fund_nm = medium_state.lambda_fund_nm;
    fundamental_band_half_width = medium_state.fundamental_band_half_width;
    mask_f = struct_utils.opt_struct_field(medium_state, 'mask_f', []);
    mask_f_w = struct_utils.opt_struct_field(medium_state, 'mask_f_w', []);
    mask = struct_utils.opt_struct_field(medium_state, 'mask', []);

    output_plan = struct_utils.req_struct_field( ...
        output_state, 'output_plan', 'cerupp_section6a_postprocess.output_state');
    plot_settings = struct_utils.req_struct_field( ...
        output_state, 'plot_settings', 'cerupp_section6a_postprocess.output_state');
    perf_cfg = struct_utils.req_struct_field( ...
        output_state, 'perf_cfg', 'cerupp_section6a_postprocess.output_state');
    diagnostics_flag = struct_utils.req_struct_field( ...
        output_state, 'diagnostics_flag', 'cerupp_section6a_postprocess.output_state');
    phase_diagnostic_flag = struct_utils.req_struct_field( ...
        output_state, 'phase_diagnostic_flag', 'cerupp_section6a_postprocess.output_state');
    fluence_use_parseval = struct_utils.req_struct_field( ...
        output_state, 'fluence_use_parseval', ...
        'cerupp_section6a_postprocess.output_state');
    time_grid_supports_parseval_fluence = struct_utils.req_struct_field( ...
        output_state, 'time_grid_supports_parseval_fluence', ...
        'cerupp_section6a_postprocess.output_state');
    run_id = struct_utils.req_struct_field( ...
        output_state, 'run_id', 'cerupp_section6a_postprocess.output_state');
    csv_path_for_run = struct_utils.req_struct_field( ...
        output_state, 'csv_path_for_run', 'cerupp_section6a_postprocess.output_state');
    store_diag_plan = output_plan.store;
    store_band_plan = output_plan.bands;
    output_cfg = output_plan.request;
    resolved_output_policy = output_plan.resolved;
    output_dev_cfg = struct_utils.req_struct_field( ...
        output_cfg, 'dev', 'cerupp_section6a_postprocess.output_plan.request');
    emit_dev_only_plots = output_dev_cfg.show_additional_dev_plots;
    effective_store_spectral_fluence_flag = logical( ...
        struct_utils.req_struct_field(resolved_output_policy, 'effective', ...
        'cerupp_section6a_postprocess.output_plan.resolved').store_spectral_fluence_flag);
    store_plan_families = struct_utils.req_struct_field( ...
        store_diag_plan, 'families', 'cerupp_section6a_postprocess.output_plan.store');
    need_store_reduced_spectral_histories = logical( ...
        struct_utils.req_struct_field(store_plan_families, 'spectra', ...
        'cerupp_section6a_postprocess.output_plan.store.families').need_reduced_histories);

        peak_naninfo = struct_utils.req_struct_field( ...
            runtime_state, 'peak_naninfo', 'cerupp_section6a_postprocess.runtime_state');
        run_warn_state = struct_utils.req_struct_field( ...
            runtime_state, 'run_warn_state', 'cerupp_section6a_postprocess.runtime_state');
        section6_output_io_failure_count_before = ...
            count_section6_output_io_failures_local(run_warn_state);
        requested_outputs_complete = true;
        requested_outputs_skipped_reason = '';
        family_ledger = struct();
        A_F = struct_utils.req_struct_field( ...
            runtime_state, 'A_F', 'cerupp_section6a_postprocess.runtime_state');
        rho = struct_utils.req_struct_field( ...
            runtime_state, 'rho', 'cerupp_section6a_postprocess.runtime_state');
        energy = struct_utils.req_struct_field( ...
            runtime_state, 'energy', 'cerupp_section6a_postprocess.runtime_state');
        energy_launch = struct_utils.req_struct_field( ...
            runtime_state, 'energy_launch', 'cerupp_section6a_postprocess.runtime_state');
        nla_runtime_cfg = struct_utils.req_struct_field( ...
            runtime_state, 'nla_runtime_cfg', 'cerupp_section6a_postprocess.runtime_state');
        plasma_runtime_cfg = struct_utils.req_struct_field( ...
            runtime_state, 'plasma_runtime_cfg', 'cerupp_section6a_postprocess.runtime_state');
        plasma_stiffness_diagnostic = struct_utils.req_struct_field( ...
            runtime_state, 'plasma_stiffness_diagnostic', ...
            'cerupp_section6a_postprocess.runtime_state');
        run_meta = struct_utils.req_struct_field( ...
            runtime_state, 'run_meta', 'cerupp_section6a_postprocess.runtime_state');
        resolved_setup_contract = struct_utils.opt_struct_field( ...
            run_meta, 'resolved_setup_contract', struct());
        resolved_physics_policy = struct_utils.opt_struct_field( ...
            resolved_setup_contract, 'resolved_physics_policy', struct());
        kerr_model_effective = char(struct_utils.opt_struct_field( ...
            resolved_physics_policy, 'kerr_model_effective', ''));
        kerr_active_effective = logical(struct_utils.opt_struct_field( ...
            resolved_physics_policy, 'kerr_active_effective', true));
        z_dependent_medium_effective = struct_utils.req_struct_field( ...
            runtime_state, 'z_dependent_medium_effective', ...
            'cerupp_section6a_postprocess.runtime_state');

    D = struct_utils.req_struct_field( ...
        diag_state, 'diagnostic_store', 'cerupp_section6a_postprocess.diag_state');
    have_store_spectral_intens = struct_utils.req_struct_field( ...
        diag_state, 'have_store_spectral_intens', 'cerupp_section6a_postprocess.diag_state');
    have_store_spectral_line_oa = struct_utils.req_struct_field( ...
        diag_state, 'have_store_spectral_line_oa', 'cerupp_section6a_postprocess.diag_state');
    have_store_spectral_line_bc = struct_utils.req_struct_field( ...
        diag_state, 'have_store_spectral_line_bc', 'cerupp_section6a_postprocess.diag_state');
    have_store_spectral_max_xy = struct_utils.req_struct_field( ...
        diag_state, 'have_store_spectral_max_xy', 'cerupp_section6a_postprocess.diag_state');
    have_store_spectral_y0_xomega_final = logical(struct_utils.opt_struct_field( ...
        diag_state, 'have_store_spectral_y0_xomega_final', false)) && ...
        isfield(D, 'store_spectral_y0_xomega_final') && ...
        ~isempty(D.store_spectral_y0_xomega_final);
    have_store_spectral_fund_xy = logical(struct_utils.opt_struct_field( ...
        diag_state, 'have_store_spectral_fund_xy', false)) && ...
        isfield(D, 'store_spectral_fund_xy') && ~isempty(D.store_spectral_fund_xy);
    spectral_lambda_ctx = struct_utils.req_struct_field( ...
        diag_state, 'spectral_lambda_ctx', 'cerupp_section6a_postprocess.diag_state');
    beamcenter_state_total = struct_utils.opt_struct_field( ...
        diag_state, 'beamcenter_state_total', struct_utils.req_struct_field( ...
        diag_state, 'beamcenter_state', 'cerupp_section6a_postprocess.diag_state'));
    beamcenter_state_visible = struct_utils.opt_struct_field( ...
        diag_state, 'beamcenter_state_visible', beamcenter_state_total);
    beamcenter_state_fund = struct_utils.opt_struct_field( ...
        diag_state, 'beamcenter_state_fund', beamcenter_state_total);
    beam_center_offaxis_any = struct_utils.opt_struct_field( ...
        diag_state, 'beam_center_offaxis_any', false);
    beam_center_visible_offaxis_any = struct_utils.opt_struct_field( ...
        diag_state, 'beam_center_visible_offaxis_any', beam_center_offaxis_any);
    beam_center_fund_offaxis_any = struct_utils.opt_struct_field( ...
        diag_state, 'beam_center_fund_offaxis_any', beam_center_offaxis_any);
    store_ofi_aval_diag_failed = struct_utils.req_struct_field( ...
        diag_state, 'store_ofi_aval_diag_failed', 'cerupp_section6a_postprocess.diag_state');
    num_storage_steps = struct_utils.req_struct_field( ...
        diag_state, 'num_storage_steps', 'cerupp_section6a_postprocess.diag_state');
    n_store_actual = struct_utils.opt_struct_field( ...
        diag_state, 'n_store_actual', num_storage_steps);
    have_keldysh_effective_nla_diag_storage = ...
        ~isempty(D.store_sigma_k_eff_keldysh_oa) || ...
        ~isempty(D.store_sigma_k_eff_keldysh_maxperp) || ...
        ~isempty(D.store_beta_eff_full_keldysh_oa) || ...
        ~isempty(D.store_beta_eff_full_keldysh_maxperp) || ...
        ~isempty(D.store_beta_eff_applied_keldysh_oa) || ...
        ~isempty(D.store_beta_eff_applied_keldysh_maxperp) || ...
        ~isempty(D.store_keldysh_diag_i_core) || ...
        ~isempty(D.store_keldysh_diag_rho_core);
    rho_peak_over_rho_crit_ref_all_steps = struct_utils.req_struct_field( ...
        summary_state, 'rho_peak_over_rho_crit_ref_all_steps', ...
        'cerupp_section6a_postprocess.summary_state');
    rho_peak_over_rho_crit_ref_z = struct_utils.req_struct_field( ...
        summary_state, 'rho_peak_over_rho_crit_ref_z', 'cerupp_section6a_postprocess.summary_state');
    rho_at_peak_over_rho_crit_ref = struct_utils.req_struct_field( ...
        summary_state, 'rho_at_peak_over_rho_crit_ref', 'cerupp_section6a_postprocess.summary_state');
    rho_crit_ref_at_peak = struct_utils.req_struct_field( ...
        summary_state, 'rho_crit_ref_at_peak', 'cerupp_section6a_postprocess.summary_state');
    rho_peak_over_rho_nt_all_steps = struct_utils.req_struct_field( ...
        summary_state, 'rho_peak_over_rho_nt_all_steps', 'cerupp_section6a_postprocess.summary_state');
    rho_peak_over_rho_nt_z = struct_utils.req_struct_field( ...
        summary_state, 'rho_peak_over_rho_nt_z', 'cerupp_section6a_postprocess.summary_state');
    rho_at_peak_over_rho_nt = struct_utils.req_struct_field( ...
        summary_state, 'rho_at_peak_over_rho_nt', 'cerupp_section6a_postprocess.summary_state');

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
diag_cap_hi = 1e120;
naninfo = peak_naninfo;
plot_session = plot_settings.session;
plot_settings_public = plot_session;
store_z = D.store_z;
mask_f_w_sorted = [];
if ~isempty(mask_f_w)
    mask_f_w_vec = reshape(double(mask_f_w), [], 1);
    if numel(mask_f_w_vec) == numel(spectral_lambda_ctx.idx_lam)
        mask_f_w_sorted = mask_f_w_vec(spectral_lambda_ctx.idx_lam);
    end
end
% plot_settings_public is the public Section 6 plot/export settings.
% Warning/export state stays explicit on each plot call.
% Use D as a short alias for the packed diagnostic store.

shared_detected_onset_state = [];
y_mid_idx = iy_axis0;
beamcenter_state_total = normalize_beamcenter_state_local( ...
    beamcenter_state_total, beam_center_offaxis_any);
beamcenter_state_visible = normalize_beamcenter_state_local( ...
    beamcenter_state_visible, beam_center_visible_offaxis_any);
beamcenter_state_fund = normalize_beamcenter_state_local( ...
    beamcenter_state_fund, beam_center_fund_offaxis_any);
beam_center_offaxis_any = logical(beamcenter_state_total.offaxis_any);
beam_center_visible_offaxis_any = logical(beamcenter_state_visible.offaxis_any);
beam_center_fund_offaxis_any = logical(beamcenter_state_fund.offaxis_any);
store_beamcenter_ix = beamcenter_state_total.store_ix;
store_beamcenter_iy = beamcenter_state_total.store_iy;
store_beamcenter_x = beamcenter_state_total.store_x;
store_beamcenter_y = beamcenter_state_total.store_y;
store_beamcenter_method_code = beamcenter_state_total.store_method_code;
store_beamcenter_ix_fund = beamcenter_state_fund.store_ix;
store_beamcenter_iy_fund = beamcenter_state_fund.store_iy;
beamcenter_spectral_plane_count = min(numel(store_beamcenter_ix), numel(store_beamcenter_iy));
beamcenter_fund_spectral_plane_count = min( ...
    numel(store_beamcenter_ix_fund), numel(store_beamcenter_iy_fund));
[beamcenter_ytrack_total, beamcenter_ytrack_total_enabled, run_warn_state] = ...
    resolve_beamcenter_ytrack_local( ...
        store_beamcenter_iy, numel(store_z), size(D.store_fluence_xy, 2), ...
        beam_center_offaxis_any, ...
        'total x-z companion maps', run_warn_state);
[beamcenter_ytrack_visible, beamcenter_ytrack_visible_enabled, run_warn_state] = ...
    resolve_beamcenter_ytrack_local( ...
        struct_utils.opt_struct_field( ...
            beamcenter_state_visible, 'store_iy', zeros(0, 1)), ...
        numel(store_z), size(D.store_fluence_xy_visible, 2), ...
        beam_center_visible_offaxis_any, ...
        'visible-band x-z companion maps', run_warn_state);
[beamcenter_ytrack_fund, beamcenter_ytrack_fund_enabled, run_warn_state] = ...
    resolve_beamcenter_ytrack_local( ...
        store_beamcenter_iy_fund, numel(store_z), ...
        spectral_fund_y_count_local(D, have_store_spectral_intens, have_store_spectral_fund_xy), ...
        beam_center_fund_offaxis_any && ...
            (have_store_spectral_intens || have_store_spectral_fund_xy), ...
        'fundamental-spectrum x-z companion maps', run_warn_state);
store_fluence_xy_visible_r = [];
store_fluence_vis_onaxis = [];

if ~resolved_output_policy.effective.run_postprocessing_flag
    error('CerUPP:InactivePostprocessCall', ...
        'cerupp_section6a_postprocess assumes run_postprocessing_flag=true; cerupp.m should skip this helper otherwise.');
end
if isempty(D.store_z) || (double(n_store_actual) < 1)
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'section6a_no_stored_planes', ...
        'CerUPP:Postprocess:Section6NoStoredPlanes', ...
        ['Skipping Section 6A post-run plots and CSV outputs because no stored z planes are available. ', ...
         'The empty diagnostic-store end state will be preserved instead of failing inside postprocessing.']);
    postprocess_state = struct( ...
        'run_warn_state', run_warn_state, ...
        'postprocess_phase_ok', true, ...
        'requested_outputs_complete', false, ...
        'requested_outputs_skipped_reason', 'no_stored_planes', ...
        'new_output_io_failure_count', 0, ...
        'family_failure_count', 0, ...
        'family_skip_count', 0, ...
        'family_blocking_skip_count', 0, ...
        'family_ledger', struct());
    return;
end

timedom_power = [];
if ~isempty(D.store_intens_td)
    timedom_power = D.store_intens_td(end, :);
end
rho_int = [];
if ~isempty(D.store_rho_int)
    rho_int = D.store_rho_int(:, :, end);
end
red_fluence = resolve_final_rgb_fluence_plane_local(D, 'r');
green_fluence = resolve_final_rgb_fluence_plane_local(D, 'g');
blue_fluence = resolve_final_rgb_fluence_plane_local(D, 'b');

final_store_z_m = D.store_z(end);

% Final output-plane overview plots: nearfield fluence, integrated final
% spectrum, and the point-spectrum views used for quick sanity checks.
try
    % Final transverse fluence plot at z = L.
    fxy = D.store_fluence_xy(:, :, end); %[J/m^2] from stored final slice
    e_from_fxy = trapz(x, trapz(y, fxy, 2), 1); %[J]
    if isfinite(e_from_fxy) && (e_from_fxy > 0)
        fluence_title = sprintf('Fluence at z= %.2f mm [J/m^2] (E= %.3g J)', ...
            1e3 * final_store_z_m, e_from_fxy);
    else
        fluence_title = sprintf('Fluence at z= %.2f mm [J/m^2]', ...
            1e3 * final_store_z_m);
    end
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(x/1e-6, y/1e-6, fxy.', [], ...
        fluence_title, ...
        'x [um]', 'y [um]', ...
        'fluence_nearfield_transverse_final', ...
        plot_session, ...
        'cbar_label', 'Fluence [J/m^2]', ...
        'run_warn_state', run_warn_state);
    family_ledger = mark_postprocess_family_ok_local( ...
        family_ledger, 'final_plane_fluence');
catch me_family_final_fluence
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'final_plane_fluence', me_family_final_fluence);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'final_plane_fluence', me_family_final_fluence);
end

try
    % Final stored mixed-space output spectrum integrated over x and y.
    [s_hz_final, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
        D.store_spectrum(end, :), ...
        'Final stored mixed-space output spectrum history', ...
        'final_spectrum_complex_leakage', ...
        'CerUPP:Plot:StoredSpectralComplexLeakage', ...
        run_warn_state); %[J/Hz]
    [s_hz_final, s_hz_final_nonfinite_n, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
        s_hz_final, 'S_Hz_final (final spectrum)', naninfo, diag_cap_hi, false, run_warn_state);
    if s_hz_final_nonfinite_n > 0
        s_hz_final(~isfinite(s_hz_final)) = NaN;
    end
    [s_hz_final, ~, run_warn_state] = plot_support_utils.clamp_nonnegative_diagnostic_leakage( ...
        s_hz_final, 'S_Hz_final (final spectrum)', run_warn_state, 'end', ...
        'final_spectrum_nonnegative_clamped', ...
        'CerUPP:Plot:FinalSpectrumNonnegativeClamped');

    e_spec_final = trapz(grid_state.nu_sorted, s_hz_final(grid_state.idx_nu));
    e_near_final = NaN;
    if (exist('fxy', 'var') == 1) && ~isempty(fxy)
        e_near_final = trapz(x, trapz(y, fxy, 2), 1); %[J]
    end
    if isfinite(e_spec_final) && (e_spec_final > 0) && ...
            isfinite(e_near_final) && (e_near_final > 0)
        rel_final_energy_mismatch = abs(e_spec_final - e_near_final) / ...
            max(e_near_final, eps_safe);
        if rel_final_energy_mismatch > 5e-3
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_final_spectrum_energy_mismatch_soft', ...
                'CerUPP:Plot:FinalSpectrumEnergyMismatchSoft', ...
                ['Final stored output-spectrum energy mismatch: E_spec_final=%.6e J, E_near_final=%.6e J ', ...
                 '(rel err=%.3e).'], ...
                e_spec_final, e_near_final, rel_final_energy_mismatch);
        end
    elseif ~isfinite(e_spec_final) || (e_spec_final <= 0)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plot_final_spectrum_energy_mismatch_unavailable', ...
            'CerUPP:Plot:FinalSpectrumEnergyMismatchSoft', ...
            'Final stored output-spectrum energy check unavailable: invalid E_spec_final=%.6e.', e_spec_final);
    end
    s_per_nm_final = s_hz_final .* spectral_lambda_ctx.hz_to_nm_factor; %[J/nm]
    s_final_sorted = s_per_nm_final(spectral_lambda_ctx.idx_lam);

    [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
        spectral_lambda_ctx.lambda_nm_sorted, [], ...
        log10(s_final_sorted + eps_safe), [], ...
        'Stored mixed-space output spectrum (x,y integrated; log10)', ...
        'Vacuum wavelength [nm]', ...
        'log10(Stored mixed-space output spectrum [J/nm])', ...
        'spectrum_log', plot_session, ...
        'run_warn_state', run_warn_state);

    if store_diag_plan.need_store_spectral_intens_cube && ...
            ~have_store_spectral_intens
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plot_spectral_intensity_cube_unavailable', ...
            'CerUPP:Plot:SpectralIntensityCubeUnavailable', ...
            ['Full-spectrum storage requested store_spectral_intens, but the cube is empty. ', ...
             'Cube-owned near-field spectral plots will be skipped and the spectral-output family should be treated as partial. ', ...
             'The final Fourier-plane kx-lambda map uses the final A_F field.']);
    end
    run_warn_state = emit_stored_high_angle_review_local( ...
        run_warn_state, D.store_spectral_intens, D.store_z, ...
        grid_state.kperp, medium_state.n_sell, lambda_window);
    family_ledger = mark_postprocess_family_ok_local( ...
        family_ledger, 'final_output_spectrum');
catch me_family_final_spectrum
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'final_output_spectrum', me_family_final_spectrum);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'final_output_spectrum', me_family_final_spectrum);
end

try

ix_oa = ix_axis0;
iy_oa = iy_axis0;
point_spectrum_ctx = struct( ...
    'D', D, ...
    'spectral_lambda_ctx', spectral_lambda_ctx, ...
    'ix_oa', ix_oa, ...
    'iy_oa', iy_oa, ...
    'store_fluence_vis_onaxis', [], ...
    'have_store_spectral_line_bc', have_store_spectral_line_bc, ...
    'num_storage_steps', num_storage_steps, ...
    'diag_cap_hi', diag_cap_hi, ...
    'eps_safe', eps_safe, ...
    'emit_dev_only_plots', emit_dev_only_plots, ...
    'plot_session', plot_session);

point_spectrum_family_base_cfg = struct( ...
    'mask_plot', false(size(spectral_lambda_ctx.lambda_nm_sorted)), ...
    'lambda_nm_plot', zeros(0, 1), ...
    'oa_curve_label_fmt', '', ...
    'oa_scale_warn_key_fmt', '', ...
    'oa_scale_warn_message', '', ...
    'oa_plot_title_fmt', '', ...
    'oa_dev_plot_title_fmt', '', ...
    'oa_save_stem', '', ...
    'bc_curve_label_fmt', '', ...
    'bc_plot_title_fmt', '', ...
    'bc_dev_plot_title_fmt', '', ...
    'bc_save_stem', '', ...
    'store_spectral_line_bc_field', 'store_spectral_line_bc', ...
    'beam_center_offaxis_any', false, ...
    'store_beamcenter_ix', zeros(0, 1), ...
    'store_beamcenter_iy', zeros(0, 1), ...
    'beamcenter_spectral_plane_count', 0, ...
    'emit_onset_failure_warn', false, ...
    'onset_failure_warn_key', '', ...
    'onset_failure_warn_id', '', ...
    'onset_failure_warn_message', '', ...
    'use_first_valid_onset_note', false, ...
    'warn_on_empty_lambda_per_tag', false, ...
    'empty_lambda_warn_key_fmt', '', ...
    'empty_lambda_warn_id', '', ...
    'empty_lambda_warn_message', '', ...
    'warn_on_missing_oa_line', false, ...
    'missing_oa_line_warn_key_fmt', '', ...
    'missing_oa_line_warn_id', '', ...
    'missing_oa_line_warn_message', '', ...
    'catch_each_tag', false, ...
    'tag_failure_warn_key_fmt', '', ...
    'tag_failure_warn_id', '', ...
    'tag_failure_warn_message', '');

family_emit_state = struct( ...
    'requested_tag_count', 0, ...
    'emitted_tag_count', 0, ...
    'skipped_tag_count', 0);
try
    if have_store_spectral_line_oa || have_store_spectral_intens
        fullrange_family_cfg = point_spectrum_family_base_cfg;
        fullrange_family_cfg.mask_plot = true(size(spectral_lambda_ctx.lambda_nm_sorted));
        fullrange_family_cfg.lambda_nm_plot = spectral_lambda_ctx.lambda_nm_sorted;
        fullrange_family_cfg.oa_curve_label_fmt = 'On-axis point spectrum full range (%s)';
        fullrange_family_cfg.oa_scale_warn_key_fmt = 'plot_nonfinite_scale_s_fullrange_%d';
        fullrange_family_cfg.oa_scale_warn_message = ...
            'Smax invalid/empty in the full-range point-spectrum curve; using 1';
        fullrange_family_cfg.oa_plot_title_fmt = ...
            'On-axis relative point spectral fluence density dF/dlambda (peak-normalized dB), full range [%s] (peak = 0 dB)';
        fullrange_family_cfg.oa_dev_plot_title_fmt = ...
            'On-axis relative point spectral fluence density dF/dlambda (peak-normalized dB), full range [%s] (peak approx -40 dB) [dev]';
        fullrange_family_cfg.oa_save_stem = 'oa_spectrum_fullrange';
        fullrange_family_cfg.bc_curve_label_fmt = ...
            'Beam-center point spectrum full range (%s)';
        fullrange_family_cfg.bc_plot_title_fmt = ...
            'Beam-center centroid-sampled relative point spectral fluence density dF/dlambda (peak-normalized dB), full range [%s] (peak = 0 dB)';
        fullrange_family_cfg.bc_dev_plot_title_fmt = ...
            'Beam-center centroid-sampled relative point spectral fluence density dF/dlambda (peak-normalized dB), full range [%s] (peak approx -40 dB) [dev]';
        fullrange_family_cfg.bc_save_stem = 'beamcenter_spectrum_fullrange';
        fullrange_family_cfg.beam_center_offaxis_any = beam_center_offaxis_any;
        fullrange_family_cfg.store_beamcenter_ix = store_beamcenter_ix;
        fullrange_family_cfg.store_beamcenter_iy = store_beamcenter_iy;
        fullrange_family_cfg.beamcenter_spectral_plane_count = beamcenter_spectral_plane_count;
        fullrange_family_cfg.catch_each_tag = true;
        fullrange_family_cfg.tag_failure_warn_key_fmt = ...
            'oa_spectrum_debug_block_failed_%s';
        fullrange_family_cfg.tag_failure_warn_id = ...
            'CerUPP:Plot:OASpectrumDebugTagFailed';
        fullrange_family_cfg.tag_failure_warn_message = ...
            'Full-range OA spectrum subgroup [%s] failed: %s';
        [shared_detected_onset_state, naninfo, run_warn_state, family_emit_state] = ...
            emit_point_spectrum_family_local( ...
                fullrange_family_cfg, point_spectrum_ctx, ...
                shared_detected_onset_state, naninfo, run_warn_state);
    end
catch me_oa_full
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'oa_spectrum_debug_block_failed', ...
        'CerUPP:Plot:OASpectrumDebugBlockFailed', ...
        'Full-range OA spectrum plot block failed: %s', me_oa_full.message);
end
if (double(family_emit_state.emitted_tag_count) < ...
        double(family_emit_state.requested_tag_count)) || ...
        (double(family_emit_state.emitted_tag_count) == 0)
    family_ledger = mark_postprocess_family_skipped_local( ...
        family_ledger, 'final_point_spectra', ...
        'requested_point_spectrum_tags_not_emitted', ...
        build_point_spectrum_family_skip_message_local( ...
            family_emit_state.emitted_tag_count, ...
            family_emit_state.requested_tag_count));
else
    family_ledger = mark_postprocess_family_ok_local( ...
        family_ledger, 'final_point_spectra');
end
catch me_family_final_point_spectra
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'final_point_spectra', me_family_final_point_spectra);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'final_point_spectra', me_family_final_point_spectra);
end

family_emit_state = struct( ...
    'requested_tag_count', 0, ...
    'emitted_tag_count', 0, ...
    'skipped_tag_count', 0);
try

%--- Time-domain power (integrated over x,y) ---
%Diagnostic: P(t)= integral_x integral_y I(x,y,t) dx dy, where code t is
%pulse-frame time.
%I = |A_S|^2 [W/m^2], so P is in watts.
% Display sanitation policy (shared across 1D/2D/3D power plots):
% non-finite -> NaN, negative -> 0 (display only).
p_t_raw = real(timedom_power);
p_t_nonfinite_n = nnz(~isfinite(p_t_raw(:)));
p_t_negative_n = nnz(isfinite(p_t_raw(:)) & (p_t_raw(:) < 0));
p_t = p_t_raw;
p_t(~isfinite(p_t)) = NaN;
p_t(p_t < 0) = 0;

store_intens_td_plot = real(D.store_intens_td);
p_tz_nonfinite_n = nnz(~isfinite(store_intens_td_plot(:)));
p_tz_negative_n = nnz(isfinite(store_intens_td_plot(:)) & (store_intens_td_plot(:) < 0));
store_intens_td_plot(~isfinite(store_intens_td_plot)) = NaN;
store_intens_td_plot(store_intens_td_plot < 0) = 0;

if (p_t_nonfinite_n + p_t_negative_n + p_tz_nonfinite_n + p_tz_negative_n) > 0
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'power_display_clipped', ...
        'CerUPP:Plot:PowerDisplayClipped', ...
        ['Display-only sanitation applied to power diagnostics: ', ...
         'P_t had %d non-finite and %d negative samples; ', ...
         'P(t,z) had %d non-finite and %d negative samples. ', ...
         'All non-finite values mapped to NaN and negatives clipped to 0 [W].'], ...
        p_t_nonfinite_n, p_t_negative_n, p_tz_nonfinite_n, p_tz_negative_n);
    naninfo(end+1) = struct( ...
        'label', 'P_t_raw (time-domain power 1D plot)', ...
        'n_nan', p_t_nonfinite_n, ...
        'n_cap', p_t_negative_n, ...
        'cap_hi', 0);
    naninfo(end+1) = struct( ...
        'label', 'store_Intens_td (power-vs-z,t plots)', ...
        'n_nan', p_tz_nonfinite_n, ...
        'n_cap', p_tz_negative_n, ...
        'cap_hi', 0);
end

[~, ~, ~, run_warn_state] = plot_utils.make_plot(t/1e-12, [], p_t, [], ...
    'Final-plane time-domain power', ...
    't [ps] (pulse-frame)', 'P(t) [W]', ...
    'td_power_transverse_final', ...
    plot_session, ...
    'run_warn_state', run_warn_state);

display_floor_note = 'display floor near zero; invalid/negative masked blank';

%--- electron-density time integral ---
%Quantity: int rho dt [m^-3 s], plotted in log10 scale.
if plasma_flag
    [rho_int_log_final, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        rho_int, eps_safe, 'rho_int final-plane map', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(x/1e-6, y/1e-6, rho_int_log_final.', [], ...
              ['log10(int rho dt [m^-3 s]) (electron-density time integral; ' display_floor_note ')'], ...
              'x [um]', 'y [um]', ...
              'rho_int_transverse_final', ...
              plot_session, ...
              'cbar_label', ['log10(int rho dt [m^-3 s]) [' display_floor_note ']'], ...
              'run_warn_state', run_warn_state);

    %--- free-electron density (maximum over t) ---
    max_rho_final = D.store_max_rho(:,:,end); %[m^-3]
    [max_rho_final_log, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        max_rho_final, eps_safe, 'rho_max final-plane map', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(x/1e-6, y/1e-6, max_rho_final_log.', [], ...
              ['log10(max_t rho [m^-3]) (maximum free-electron density; ' display_floor_note ')'], ...
              'x [um]', 'y [um]', ...
              'rho_max_transverse_final', ...
              plot_session, ...
              'cbar_label', ['log10(max_t rho [m^-3]) [' display_floor_note ']'], ...
              'run_warn_state', run_warn_state);

    %--- free-electron density vs. time (on axis) ---
    % In the core-only rho representation this plot is only available when
    % the current axis sample is present in the current core_idx support.
    if ismatrix(rho) % core-only [Nc x Nt]
        axis_linear_idx = sub2ind([grid_state.num_x_pts, grid_state.num_y_pts], ix_axis0, iy_axis0);
        axis_core_row = find(grid_state.core_idx(:) == axis_linear_idx, 1, 'first');
        if isempty(axis_core_row)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'axis_not_in_core_idx', ...
                'CerUPP:Diagnostics:AxisNotInCoreIdx', ...
                ['Skipping final on-axis rho(t) pulse-frame plot: the current axis sample is not present ', ...
                 'in the current core_idx plasma support.']);
            family_ledger = mark_postprocess_family_skipped_local( ...
                family_ledger, 'final_rho_t_on_axis', ...
                'axis_not_in_core_idx', ...
                ['Skipping final on-axis rho(t) pulse-frame plot because the current ', ...
                 'axis sample is not present in the current core_idx plasma support.']);
        else
            rho_axis_t = reshape(rho(axis_core_row, :), 1, []);
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(t/1e-12, [], rho_axis_t, [], ...
                      'On-axis free-electron density vs pulse-frame time', ...
                      't [ps] (pulse-frame)', 'rho(t) [m^-3]', ...
                      'td_rho_oa_final', ...
                      plot_session, ...
                      'run_warn_state', run_warn_state);
            family_ledger = mark_postprocess_family_ok_local( ...
                family_ledger, 'final_rho_t_on_axis');
        end
    else
        rho_axis_t = reshape(squeeze(rho(ix_axis0, iy_axis0, :)), 1, []);
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(t/1e-12, [], rho_axis_t, [], ...
                  'On-axis free-electron density vs pulse-frame time', ...
                  't [ps] (pulse-frame)', 'rho(t) [m^-3]', ...
                  'td_rho_oa_final', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);
        family_ledger = mark_postprocess_family_ok_local( ...
            family_ledger, 'final_rho_t_on_axis');
    end
end

rgb_final_specs = { ...
    struct( ...
        'band_name', 'green', ...
        'fluence', green_fluence, ...
        'lambda_min_nm', medium_state.lambda_green_band_min, ...
        'lambda_max_nm', medium_state.lambda_green_band_max, ...
        'save_stem', 'g_transverse_final', ...
        'cbar_label', 'Final-plane green-band fluence [J/m^2]'), ...
    struct( ...
        'band_name', 'red', ...
        'fluence', red_fluence, ...
        'lambda_min_nm', medium_state.lambda_red_band_min, ...
        'lambda_max_nm', medium_state.lambda_red_band_max, ...
        'save_stem', 'r_transverse_final', ...
        'cbar_label', 'Final-plane red-band fluence [J/m^2]'), ...
    struct( ...
        'band_name', 'blue', ...
        'fluence', blue_fluence, ...
        'lambda_min_nm', medium_state.lambda_blue_band_min, ...
        'lambda_max_nm', medium_state.lambda_blue_band_max, ...
        'save_stem', 'b_transverse_final', ...
        'cbar_label', 'Final-plane blue-band fluence [J/m^2]') ...
};
missing_rgb_bands = {};
for ii = 1:numel(rgb_final_specs)
    spec = rgb_final_specs{ii};
    if isempty(spec.fluence)
        missing_rgb_bands{end+1} = spec.band_name; %#ok<AGROW>
        continue;
    end
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(x/1e-6, y/1e-6, spec.fluence.', [], ...
        sprintf('Final-plane %s-band fluence (%.3g-%.3g nm) [J/m^2]', ...
            spec.band_name, spec.lambda_min_nm, spec.lambda_max_nm), ...
        'x [um]', 'y [um]', ...
        spec.save_stem, ...
        plot_session, ...
        'cbar_label', spec.cbar_label, ...
        'run_warn_state', run_warn_state);
end
if ~isempty(missing_rgb_bands)
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, ...
        'end', ...
        'final_rgb_fluence_band_missing', ...
        'CerUPP:Plot:FinalRgbBandFluenceMissing', ...
        'Skipping final-plane RGB fluence plot(s) for missing band data: %s.', ...
        strjoin(missing_rgb_bands, ', '));
    family_ledger = mark_postprocess_family_skipped_local( ...
        family_ledger, 'final_rgb_fluence_bands', ...
        'missing_band_data', ...
        sprintf('Skipping final-plane RGB fluence plot(s) for missing band data: %s.', ...
            strjoin(missing_rgb_bands, ', ')));
else
    family_ledger = mark_postprocess_family_ok_local( ...
        family_ledger, 'final_rgb_fluence_bands');
end

%--- z vs. time-domain power (integrated over x,y) ---
%Quantity: P(t,z)= integral_x integral_y I(x,y,t;z) dx dy.
if numel(D.store_z) <= 1
    [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
        t/1e-12, [], reshape(store_intens_td_plot, [], 1), [], ...
        'Time-domain power at the stored z plane (integrated I over x,y)', ...
        't [ps] (pulse-frame)', 'P(t) [W]', ...
        'td_power_z', ...
        plot_session, ...
        'run_warn_state', run_warn_state);
else
    [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
        D.store_z, t/1e-12, store_intens_td_plot', [], ...
        'Time-domain power vs z and pulse-frame t (integrated I over x,y)', ...
        'z [m]', 't [ps] (pulse-frame)', ...
        'td_power_z', ...
        plot_session, ...
        'cbar_label', 'P(t,z) [W]', ...
        'run_warn_state', run_warn_state);
end

%--- z vs. lab-frame time-domain power (3D) ---
%Pulse-frame variable t is mapped to lab time by
%t_lab(z) = t + integral [1 / v_g(z')] dz' referenced to the plotted valid segment start.
f_lab = [];
try
    inv_vg_cols = D.store_inv_vg(:);                        %[s/m]
    valid_inv_vg_mask = isfinite(inv_vg_cols) & (inv_vg_cols > 0);
    if ~any(valid_inv_vg_mask)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'invalid_inv_vg_labframe_plot', ...
            'CerUPP:Plot:InvalidInvVgLabFramePlot', ...
            ['Skipping lab-frame time-domain power 3D plot because store_inv_vg ', ...
             'has no finite positive support on any stored plane.']);
    else
        idx_z_lab_valid = extract_longest_true_segment_local(valid_inv_vg_mask);
        if numel(idx_z_lab_valid) < numel(D.store_z)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'partial_inv_vg_labframe_plot', ...
                'CerUPP:Plot:PartialInvVgLabFramePlot', ...
                ['Lab-frame time-domain power 3D plot is retimed only on the longest contiguous ', ...
                 'stored-z segment with finite positive store_inv_vg values. Invalid planes are omitted ', ...
                 'from this optional 3D view (%d/%d stored planes kept).'], ...
                numel(idx_z_lab_valid), numel(D.store_z));
        end
        tau_g_cols = cumtrapz(D.store_z(idx_z_lab_valid), inv_vg_cols(idx_z_lab_valid)); %[s]
        max_labframe_time_samples = 400;
        max_labframe_z_samples = 300;
        if numel(t) > max_labframe_time_samples
            idx_t_lab_plot = unique(round(linspace(1, numel(t), max_labframe_time_samples)));
        else
            idx_t_lab_plot = 1:numel(t);
        end
        if numel(idx_z_lab_valid) > max_labframe_z_samples
            idx_z_lab_local_plot = unique(round(linspace(1, numel(idx_z_lab_valid), max_labframe_z_samples)));
        else
            idx_z_lab_local_plot = 1:numel(idx_z_lab_valid);
        end
        idx_z_lab_plot = idx_z_lab_valid(idx_z_lab_local_plot);
        t_lab_ps = bsxfun(@plus, reshape(t(idx_t_lab_plot), [], 1), ...
            reshape(tau_g_cols(idx_z_lab_local_plot), 1, [])) / 1e-12; %[ps]
        % Reuse the same display-sanitized power map used by the 2D P(t,z) plot.

        p_lab = store_intens_td_plot(idx_z_lab_plot, idx_t_lab_plot).'; %power map, size Nt_plot x Nz_plot
        z_lab_plot = reshape(D.store_z(idx_z_lab_plot), 1, []);
        z_lab_grid = repmat(z_lab_plot, size(t_lab_ps, 1), 1);

        [f_lab, lab_plot_session, run_warn_state, ok_lab_plot_session] = ...
            plot_support_utils.begin_figure_session( ...
                plot_session.outdir, 'td_power_z_labframe_3d', ...
                run_warn_state, plot_session, ...
                'create_figure', true);
        if ok_lab_plot_session
            surf(z_lab_grid, t_lab_ps, p_lab, 'EdgeColor', 'none');
            shading(gca, get_plot_surface_shading_mode_local(plot_session));
            xlabel('z [m]');
            ylabel('t_{lab} = t + tau_g(z) [ps] (code t is pulse-frame time; tau_g referenced to plotted-segment start)');
            zlabel('P(t_lab,z) [W]');
            title(sprintf(['Time-domain power with scalar group-delay retiming estimate ', ...
                           '(3D; valid retiming segment starts at z=%.3g m; Nt_{plot}=%d/%d, ', ...
                           'Nz_{plot}=%d/%d valid, %d/%d stored)'], ...
                D.store_z(idx_z_lab_valid(1)), numel(idx_t_lab_plot), numel(t), ...
                numel(idx_z_lab_plot), numel(idx_z_lab_valid), numel(idx_z_lab_valid), numel(D.store_z)));
            colormap(parula);
            cb = colorbar;
            ylabel(cb, 'P(t_lab,z) [W]');
            view(40, 30);
            grid on;
            axis tight;

            run_warn_state = plot_support_utils.finalize_figure_session( ...
                f_lab, lab_plot_session, run_warn_state);
            f_lab = [];
        end
    end
catch me_2
    plot_support_utils.close_figure_if_valid(f_lab);
    run_warn_state = run_warn_state_utils.emit_softwarn_each_time_with_phase( ...
        run_warn_state, 'end', 'CerUPP:Plot:LabFramePower3DPlotFailed', ...
        'Lab-frame time-domain power 3D plot failed: %s', me_2.message);
end
family_ledger = mark_postprocess_family_ok_local( ...
    family_ledger, 'final_overview_and_power');
catch me_family_final_overview
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'final_overview_and_power', me_family_final_overview);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'final_overview_and_power', me_family_final_overview);
end

%--- z vs. on-axis fixed-point maximum intensity ---
%Quantity: max_t I_diag(x~0,y~0,t;z) [W/m^2]; this is not centroid-tracked.
try
i_oa_max_trace = reduce_stored_time_max_local(D.store_intens_td_oa);
[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], i_oa_max_trace, [], ...
          'On-axis fixed-point maximum weighted diagnostic intensity vs z', ...
          'z [m]', 'I_diag,oa,max [W/m^2]', ...
          'peak_intensity_oa_vs_z', ...
          plot_session, ...
          'run_warn_state', run_warn_state);
if beam_center_offaxis_any
    i_bc_max_trace = reduce_stored_time_max_local(D.store_intens_td_bc);
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], i_bc_max_trace, [], ...
              'Beam-center centroid-sampled maximum weighted diagnostic intensity vs z', ...
              'z [m]', 'I_diag,beam-center-pixel,max_t [W/m^2]', ...
              'peak_intensity_beamcenter_vs_z', ...
              plot_session, ...
              'run_warn_state', run_warn_state);
end

%--- Build fluence traces ---
%Axis/beam-center band fluence traces are integrated from stored time traces.
%Peak transverse fluence uses max_{x,y} of per-pixel fluence maps stored per z.
visible_band_label = 'stored visible band';
if postprocess_band_support.has_visible_band_contract
    visible_band_label = sprintf('%.0f-%.0f nm', ...
        lambda_visible_band_min, lambda_visible_band_max);
end
fundamental_band_support = struct_utils.req_struct_field( ...
    store_band_plan, 'fundamental_band_support', 'output_plan.bands');
fundamental_band_support_status = char(struct_utils.req_struct_field( ...
    fundamental_band_support, 'status', 'output_plan.bands.fundamental_band_support'));
fundamental_band_has_any_support = ~strcmpi(fundamental_band_support_status, 'none');
fundamental_band_has_full_support = strcmpi(fundamental_band_support_status, 'full');
fundamental_band_has_partial_support = strcmpi(fundamental_band_support_status, 'partial');
fundamental_band_label = 'stored fundamental band';
if postprocess_band_support.has_fundamental_band_contract
    fundamental_band_label = sprintf('center %.1f nm +/- %.0f nm', ...
        lambda_fund_nm, fundamental_band_half_width);
end
fundamental_band_requested_range_label = sprintf('%.1f-%.1f nm', ...
    fundamental_band_support.requested_lambda_min_nm, ...
    fundamental_band_support.requested_lambda_max_nm);
if isfinite(fundamental_band_support.sampled_lambda_min_nm) && ...
        isfinite(fundamental_band_support.sampled_lambda_max_nm)
    fundamental_band_sampled_support_label = sprintf( ...
        'sampled support %.1f-%.1f nm, %d bins, %.1f%% omega-cell coverage', ...
        fundamental_band_support.sampled_lambda_min_nm, ...
        fundamental_band_support.sampled_lambda_max_nm, ...
        fundamental_band_support.sampled_num_bins, ...
        100 * fundamental_band_support.omega_cell_coverage_fraction);
else
    fundamental_band_sampled_support_label = sprintf( ...
        'no sampled support (%d bins)', ...
        fundamental_band_support.sampled_num_bins);
end
fundamental_band_plot_label = fundamental_band_label;
if fundamental_band_has_partial_support
    fundamental_band_plot_label = sprintf( ...
        '%s; partial support (%s)', ...
        fundamental_band_label, fundamental_band_sampled_support_label);
end
keldysh_report_meta = plasma_setup_support.resolve_ofi_report_meta_local(plasma_runtime_cfg);
plot_keldysh_ctx = struct_utils.opt_struct_field( ...
    struct_utils.opt_struct_field(plasma_runtime_cfg, 'ofi_setup', struct()), ...
    'keldysh_ctx', struct());
use_scalar_k_display_titles = logical(struct_utils.opt_struct_field( ...
    plot_keldysh_ctx, 'enabled', false));
k_display_plot_label = 'n/a';
k_display_numeric = NaN;
k_display_source = char(struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_source', 'auto_reference_threshold'));
k_display_gap_ratio = double(struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_gap_ratio', struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_nu_cont', NaN)));
k_display_threshold_order = double(struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_threshold_order', struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_nu_int', struct_utils.opt_struct_field( ...
    keldysh_report_meta, 'K_display_auto', NaN))));
k_display_source_label = 'setup threshold diagnostic exponent';
if isfield(keldysh_report_meta, 'K_display') && ...
        isfinite(keldysh_report_meta.K_display) && ...
        (keldysh_report_meta.K_display > 0)
    k_display_numeric = double(keldysh_report_meta.K_display);
    k_display_plot_label = sprintf('%.3g', k_display_numeric);
elseif isfield(keldysh_report_meta, 'K_eff_single_bookkeeping') && ...
        isfinite(keldysh_report_meta.K_eff_single_bookkeeping) && ...
        (keldysh_report_meta.K_eff_single_bookkeeping > 0)
    k_display_numeric = double(keldysh_report_meta.K_eff_single_bookkeeping);
    k_display_plot_label = sprintf('%.3g', k_display_numeric);
elseif isfield(keldysh_report_meta, 'K_eff_single') && ...
        isfinite(keldysh_report_meta.K_eff_single) && ...
        (keldysh_report_meta.K_eff_single > 0)
    k_display_numeric = double(keldysh_report_meta.K_eff_single);
    k_display_plot_label = sprintf('%.3g', k_display_numeric);
end
if strcmpi(k_display_source, 'user_override')
    k_display_source_label = 'user override';
elseif strcmpi(k_display_source, 'postrun_peak_threshold')
    if isfinite(k_display_threshold_order) && isfinite(k_display_gap_ratio)
        k_display_source_label = sprintf( ...
            'post-run peak threshold K=%.3g from Eg_eff(I_ref)/(hbar*omega_fund)=%.3g', ...
            k_display_threshold_order, k_display_gap_ratio);
    else
        k_display_source_label = 'post-run peak threshold';
    end
elseif strcmpi(k_display_source, 'postrun_peak_clamped_lookup_threshold')
    if isfinite(k_display_threshold_order) && isfinite(k_display_gap_ratio)
        k_display_source_label = sprintf( ...
            ['post-run peak threshold K=%.3g from Eg_eff(I_ref)/(hbar*omega_fund)=%.3g ' ...
             '(I_ref clamped to lookup window)'], ...
            k_display_threshold_order, k_display_gap_ratio);
    else
        k_display_source_label = 'post-run peak threshold with lookup-window clamp';
    end
elseif isfinite(k_display_threshold_order) && isfinite(k_display_gap_ratio)
    k_display_source_label = sprintf( ...
        'setup threshold K=%.3g from Eg_eff(I_ref)/(hbar*omega_fund)=%.3g', ...
        k_display_threshold_order, k_display_gap_ratio);
elseif strcmpi(k_display_source, 'auto_reference_threshold')
    k_display_source_label = 'setup threshold from Eg_eff(I_ref)/(hbar*omega_fund)';
end
if ~use_scalar_k_display_titles
    sigma_keff_title_suffix = 'Static W_ion(I) diagnostic translation uses local K_eff(I)';
    sigma_keff_oa_ylabel = 'sigmaK_eff,oa,max_t(z) [local K_eff(I) diagnostic unit; see title]';
    sigma_keff_maxperp_ylabel = 'sigmaK_eff,maxperp(z) [local K_eff(I) diagnostic unit; see title]';
    beta_keff_title_suffix = 'Static W_ion(I) diagnostic translation uses local K_eff(I)';
    beta_keff_oa_ylabel = 'beta_eff_full,oa,max_t(z) [local K_eff(I) diagnostic view; see title]';
    beta_keff_maxperp_ylabel = 'beta_eff_full,maxperp(z) [local K_eff(I) diagnostic view; see title]';
    beta_applied_keff_title_suffix = 'Static W_ion(I) diagnostic translation uses local K_eff(I)';
    beta_applied_keff_oa_ylabel = 'beta_eff_applied,oa,max_t(z) [local K_eff(I) diagnostic view; see title]';
    beta_applied_keff_maxperp_ylabel = 'beta_eff_applied,maxperp(z) [local K_eff(I) diagnostic view; see title]';
elseif isfinite(k_display_numeric) && (k_display_numeric > 0)
    sigma_keff_title_suffix = sprintf( ...
        'K_display diagnostic exponent (%s) = %s', k_display_source_label, k_display_plot_label);
    beta_keff_title_suffix = sprintf( ...
        'K_display diagnostic exponent (%s) = %s', k_display_source_label, k_display_plot_label);
    if isfinite(k_display_numeric) && (k_display_numeric > 0)
        sigma_keff_oa_ylabel = sprintf( ...
            'sigmaK_eff,oa,max_t(z) [1/(s*(W/m^2)^{%s})]', ...
            k_display_plot_label);
        sigma_keff_maxperp_ylabel = sprintf( ...
            'sigmaK_eff,maxperp(z) [1/(s*(W/m^2)^{%s})]', ...
            k_display_plot_label);
        beta_keff_oa_ylabel = sprintf( ...
            'beta_eff_full,oa,max_t(z) [m^{%.3g}/W^{%.3g}; full-neutral reference, not applied]', ...
            2*k_display_numeric - 3, k_display_numeric - 1);
        beta_keff_maxperp_ylabel = sprintf( ...
            'beta_eff_full,maxperp(z) [m^{%.3g}/W^{%.3g}; full-neutral reference, not applied]', ...
            2*k_display_numeric - 3, k_display_numeric - 1);
        beta_applied_keff_oa_ylabel = sprintf( ...
            'beta_eff_applied,oa,max_t(z) [m^{%.3g}/W^{%.3g}; applied matched-loss counterpart]', ...
            2*k_display_numeric - 3, k_display_numeric - 1);
        beta_applied_keff_maxperp_ylabel = sprintf( ...
            'beta_eff_applied,maxperp(z) [m^{%.3g}/W^{%.3g}; applied matched-loss counterpart]', ...
            2*k_display_numeric - 3, k_display_numeric - 1);
    else
        sigma_keff_oa_ylabel = 'sigmaK_eff,oa,max_t(z) [scalar-keff diagnostic unit; see title]';
        sigma_keff_maxperp_ylabel = 'sigmaK_eff,maxperp(z) [scalar-keff diagnostic unit; see title]';
        beta_keff_oa_ylabel = 'beta_eff_full,oa,max_t(z) [full-neutral scalar-keff reference, not applied; see title]';
        beta_keff_maxperp_ylabel = 'beta_eff_full,maxperp(z) [full-neutral scalar-keff reference, not applied; see title]';
        beta_applied_keff_oa_ylabel = 'beta_eff_applied,oa,max_t(z) [applied matched-loss scalar-keff view; see title]';
        beta_applied_keff_maxperp_ylabel = 'beta_eff_applied,maxperp(z) [applied matched-loss scalar-keff view; see title]';
    end
    beta_applied_keff_title_suffix = sprintf( ...
        'K_display diagnostic exponent (%s) = %s', k_display_source_label, k_display_plot_label);
else
    sigma_keff_title_suffix = 'K_display diagnostic exponent unavailable';
    sigma_keff_oa_ylabel = 'sigmaK_eff,oa,max_t(z) [display exponent unavailable; see title]';
    sigma_keff_maxperp_ylabel = 'sigmaK_eff,maxperp(z) [display exponent unavailable; see title]';
    beta_keff_title_suffix = 'K_display diagnostic exponent unavailable';
    beta_keff_oa_ylabel = 'beta_eff_full,oa,max_t(z) [display exponent unavailable; see title]';
    beta_keff_maxperp_ylabel = 'beta_eff_full,maxperp(z) [display exponent unavailable; see title]';
    beta_applied_keff_title_suffix = 'K_display diagnostic exponent unavailable';
    beta_applied_keff_oa_ylabel = 'beta_eff_applied,oa,max_t(z) [display exponent unavailable; see title]';
    beta_applied_keff_maxperp_ylabel = 'beta_eff_applied,maxperp(z) [display exponent unavailable; see title]';
end
f_oa_vis         = squeeze(band_diagnostics_utils.integrate_time_trace_fluence( ...
    D.store_intens_td_oa_vis, t, delta_t, fluence_use_parseval, ...
    time_grid_supports_parseval_fluence, 2));                              %[J/m^2]
f_oa_fund        = squeeze(band_diagnostics_utils.integrate_time_trace_fluence( ...
    D.store_intens_td_oa_fund, t, delta_t, fluence_use_parseval, ...
    time_grid_supports_parseval_fluence, 2));                              %[J/m^2]
f_peak_vis       = D.store_fpeak_vis(:);                                  %[J/m^2] = max_{x,y} int_t I_vis dt
f_peak_fund      = D.store_fpeak_fund(:);                                 %[J/m^2] = max_{x,y} int_t I_fund dt
f_bc_vis         = squeeze(band_diagnostics_utils.integrate_time_trace_fluence( ...
    D.store_intens_td_bc_vis, t, delta_t, fluence_use_parseval, ...
    time_grid_supports_parseval_fluence, 2));                              %[J/m^2]
f_bc_fund        = squeeze(band_diagnostics_utils.integrate_time_trace_fluence( ...
    D.store_intens_td_bc_fund, t, delta_t, fluence_use_parseval, ...
    time_grid_supports_parseval_fluence, 2));                              %[J/m^2]

%--- z vs. on-axis fixed-point visible-band fluence ---
%Quantity: int_t I_vis(x~0,y~0,t) dt [J/m^2], integrated with the same
%stored-band fluence quadrature used during the stored-plane reductions.
[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_oa_vis, [], ...
          sprintf('On-axis fixed-point visible-band fluence vs z (%s)', visible_band_label), ...
          'z [m]', 'F_oa_vis [J/m^2]', ...
          'fluence_oa_vis_vs_z', ...
          plot_session, ...
          'run_warn_state', run_warn_state);
if beam_center_visible_offaxis_any
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_bc_vis, [], ...
              sprintf('Beam-center centroid-sampled visible-band fluence vs z (%s)', visible_band_label), ...
              'z [m]', 'F_vis @ beam-center pixel [J/m^2]', ...
              'fluence_beamcenter_vis_vs_z', ...
              plot_session, ...
              'run_warn_state', run_warn_state);
end

%--- z vs. on-axis fixed-point fundamental-band fluence ---
%Quantity: int_t I_fundamental-band(x~0,y~0,t) dt [J/m^2]; use maxperp for moving/off-center structures.
if ~fundamental_band_has_any_support
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'pump_band_family_unavailable_empty_mask', ...
        'CerUPP:Diagnostics:PumpBandFamilyUnavailableEmptyMask', ...
        ['Skipping fundamental-band fluence-vs-z plots: no sampled wavelength bins fall inside ', ...
         'the requested band (%s).'], ...
        fundamental_band_label);
else
    if fundamental_band_has_partial_support
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'pump_band_family_partial_support', ...
            'CerUPP:Diagnostics:PumpBandFamilyPartialSupport', ...
            ['Fundamental-band fluence-vs-z plots are using partial support: ', ...
             'requested %s; %s.'], ...
            fundamental_band_requested_range_label, ...
            fundamental_band_sampled_support_label);
    end
    if any(isfinite(f_oa_fund))
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_oa_fund, [], ...
                  sprintf('On-axis fixed-point fundamental-band fluence vs z (%s)', fundamental_band_plot_label), ...
                  'z [m]', 'On-axis fundamental-band fluence [J/m^2]', ...
                  'fluence_oa_fund_vs_z', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'pump_band_trace_skipped', ...
            'CerUPP:Plot:PumpBandTraceSkipped', ...
            'Skipping on-axis fundamental-band fluence trace: no finite stored fundamental-band samples.');
    end
    if any(isfinite(f_bc_fund))
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_bc_fund, [], ...
                  sprintf('Fundamental-band center-sampled fluence vs z (%s)', fundamental_band_plot_label), ...
                  'z [m]', 'Fundamental-band fluence @ fundamental-band center pixel [J/m^2]', ...
                  'fluence_beamcenter_fund_vs_z', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'beam_center_pump_trace_skipped', ...
            'CerUPP:Plot:BeamCenterPumpTraceSkipped', ...
            'Skipping stored fundamental-band center trace: no finite stored fundamental-band samples.');
    end
    if any(isfinite(f_peak_fund))
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_peak_fund, [], ...
                  sprintf('Peak transverse fundamental-band fluence vs z (%s)', fundamental_band_plot_label), ...
                  'z [m]', 'Peak fundamental-band fluence [J/m^2]', ...
                  'fluence_maxperp_fund_vs_z', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'pump_band_peak_history_skipped', ...
            'CerUPP:Diagnostics:PumpBandPeakHistorySkipped', ...
            'Skipping peak fundamental-band fluence-vs-z trace: no finite stored fundamental-band samples.');
    end
end

%--- z vs. Keldysh diagnostic maps ---
% These plots share one stored matched-OFI diagnostic family.
% Individual traces are emitted only where stored planes carry finite samples.
if have_keldysh_effective_nla_diag_storage
    keldysh_coeff_plot_specs = struct( ...
        'trace', {D.store_sigma_k_eff_keldysh_oa, D.store_sigma_k_eff_keldysh_maxperp, ...
                  D.store_beta_eff_full_keldysh_oa, D.store_beta_eff_full_keldysh_maxperp, ...
                  D.store_beta_eff_applied_keldysh_oa, D.store_beta_eff_applied_keldysh_maxperp}, ...
        'title_fmt', { ...
            'On-axis fixed-point sigmaK_eff(I) diagnostic map vs z (%s)', ...
            'Peak transverse sigmaK_eff(I) diagnostic map vs z (%s)', ...
            'On-axis fixed-point beta_eff_full(I) diagnostic map vs z (full-neutral reference, not the applied coefficient; %s)', ...
            'Peak transverse beta_eff_full(I) diagnostic map vs z (full-neutral reference, not the applied coefficient; %s)', ...
            'On-axis fixed-point beta_eff_applied(I) diagnostic map vs z (applied matched-OFI view; %s)', ...
            'Peak transverse beta_eff_applied(I) diagnostic map vs z (applied matched-OFI view; %s)'}, ...
        'title_suffix', {sigma_keff_title_suffix, sigma_keff_title_suffix, ...
                         beta_keff_title_suffix, beta_keff_title_suffix, ...
                         beta_applied_keff_title_suffix, beta_applied_keff_title_suffix}, ...
        'ylabel_text', {sigma_keff_oa_ylabel, sigma_keff_maxperp_ylabel, ...
                        beta_keff_oa_ylabel, beta_keff_maxperp_ylabel, ...
                        beta_applied_keff_oa_ylabel, beta_applied_keff_maxperp_ylabel}, ...
        'save_name', {'keldysh_sigmaK_eff_oa_vs_z', 'keldysh_sigmaK_eff_maxperp_vs_z', ...
                      'keldysh_beta_eff_full_oa_vs_z', 'keldysh_beta_eff_full_maxperp_vs_z', ...
                      'keldysh_beta_eff_applied_oa_vs_z', 'keldysh_beta_eff_applied_maxperp_vs_z'});
    for spec_idx = 1:numel(keldysh_coeff_plot_specs)
        trace_now = keldysh_coeff_plot_specs(spec_idx).trace;
        if any(isfinite(trace_now))
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], trace_now, [], ...
                sprintf(keldysh_coeff_plot_specs(spec_idx).title_fmt, ...
                    keldysh_coeff_plot_specs(spec_idx).title_suffix), ...
                'z [m]', keldysh_coeff_plot_specs(spec_idx).ylabel_text, ...
                keldysh_coeff_plot_specs(spec_idx).save_name, ...
                plot_session, ...
                'run_warn_state', run_warn_state);
        end
    end
end

if isfield(plasma_runtime_cfg, 'ofi_setup') && isstruct(plasma_runtime_cfg.ofi_setup) && ...
        isfield(plasma_runtime_cfg.ofi_setup, 'keldysh_ctx') && isstruct(plasma_runtime_cfg.ofi_setup.keldysh_ctx) && ...
        logical(struct_utils.opt_struct_field(plasma_runtime_cfg.ofi_setup.keldysh_ctx, 'enabled', false))
    keldysh_ctx_plot = plasma_runtime_cfg.ofi_setup.keldysh_ctx;
    k_eff_plot_peak_intensity_wm2 = NaN;
    postrun_i_min_wm2 = Inf;
    postrun_i_max_wm2 = 0;
    intensity_trace_cells = {D.store_intens_td_oa, D.store_intens_td_maxperp};
    if beam_center_offaxis_any
        intensity_trace_cells{end + 1} = D.store_intens_td_bc;
    end
    for intensity_cell_idx = 1:numel(intensity_trace_cells)
        intensity_now = intensity_trace_cells{intensity_cell_idx};
        if isempty(intensity_now)
            continue;
        end
        finite_positive = intensity_now(isfinite(intensity_now) & (intensity_now > 0));
        if isempty(finite_positive)
            continue;
        end
        postrun_i_min_wm2 = min(postrun_i_min_wm2, min(finite_positive(:)));
        postrun_i_max_wm2 = max(postrun_i_max_wm2, max(finite_positive(:)));
    end
    if isfinite(k_eff_plot_peak_intensity_wm2) && (k_eff_plot_peak_intensity_wm2 > 0)
        postrun_i_max_wm2 = max(postrun_i_max_wm2, k_eff_plot_peak_intensity_wm2);
    end
    if isfinite(struct_utils.opt_struct_field(keldysh_ctx_plot, 'I_min', NaN)) && ...
            (postrun_i_min_wm2 == Inf)
        postrun_i_min_wm2 = max(double(keldysh_ctx_plot.I_min) * 0.5, realmin('double'));
    end
    if isfinite(struct_utils.opt_struct_field(keldysh_ctx_plot, 'I_max', NaN))
        postrun_i_max_wm2 = max(postrun_i_max_wm2, double(keldysh_ctx_plot.I_max));
    end
    rho_nt_keldysh_norm_plot = struct_utils.opt_struct_field( ...
        keldysh_ctx_plot, 'rho_nt_keldysh_norm_m3', NaN);
    if ~(isfinite(rho_nt_keldysh_norm_plot) && (rho_nt_keldysh_norm_plot > 0))
        rho_nt_keldysh_norm_plot = medium_state.rho_nt_m3;
    end
    if ~(isfinite(rho_nt_keldysh_norm_plot) && (rho_nt_keldysh_norm_plot > 0))
        rho_nt_keldysh_norm_plot = rho_nt;
    end
    if isfinite(postrun_i_min_wm2) && isfinite(postrun_i_max_wm2) && ...
            (postrun_i_min_wm2 > 0) && (postrun_i_max_wm2 > postrun_i_min_wm2) && ...
            isfield(plasma_runtime_cfg, 'keldysh_cfg') && isstruct(plasma_runtime_cfg.keldysh_cfg) && ...
            isfield(plasma_runtime_cfg.keldysh_cfg, 'I_lookup_Wm2') && ...
            isfield(plasma_runtime_cfg.keldysh_cfg, 'W_lookup_sinv')
        keldysh_postrun_plot_policy = struct( ...
            'outdir', plot_session.outdir, ...
            'save_outputs_as_fig', plot_session.save_outputs_as_fig, ...
            'save_outputs_as_png', plot_session.save_outputs_as_png, ...
            'visible', plot_session.visible, ...
            'fig_name_base', 'keldysh_ofi_rate_diagnostic_postrun_clamped', ...
            'emit_fixed_window_debug', false, ...
            'display_i_min_wm2', postrun_i_min_wm2, ...
            'display_i_max_wm2', postrun_i_max_wm2, ...
            'display_range_label', 'post-run stored intensity span with runtime zero/clamp policy', ...
            'show_clamp_markers', true, ...
            'zero_rate_below_wm2', struct_utils.opt_struct_field( ...
                keldysh_ctx_plot, 'keldysh_zero_rate_below_wm2', ...
                struct_utils.opt_struct_field(keldysh_ctx_plot, 'I_min', NaN)), ...
            'lut_i_min_wm2', struct_utils.opt_struct_field(keldysh_ctx_plot, 'I_min', NaN), ...
            'lut_i_max_wm2', struct_utils.opt_struct_field(keldysh_ctx_plot, 'I_max', NaN), ...
            'clamp_w_interp', true, ...
            'w_min_clamp_value', struct_utils.opt_struct_field( ...
                keldysh_ctx_plot, 'W_min_clamp_value', 0, 'treat_empty_as_missing', true), ...
            'w_max_clamp_value', struct_utils.opt_struct_field( ...
                keldysh_ctx_plot, 'W_max_clamp_value', 0, 'treat_empty_as_missing', true));
        run_warn_state = plot_support_utils.plot_keldysh_rate_diagnostic( ...
            plasma_runtime_cfg.keldysh_cfg.I_lookup_Wm2, plasma_runtime_cfg.keldysh_cfg.W_lookup_sinv, ...
            medium_state.ofi_k_orders, medium_state.sigma_k_vec, k_display_numeric, ...
            rho_nt_keldysh_norm_plot, medium_state.rho_nt_m3, ...
            keldysh_postrun_plot_policy, run_warn_state, ...
            'phase_tag', 'end');
    end
end

%--- z vs. maximum transverse intensity ---
%Quantity: max_{x,y,t} I_diag(x,y,t;z) [W/m^2]
i_maxperp_trace = reduce_stored_time_max_local(D.store_intens_td_maxperp);
[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], i_maxperp_trace, [], ...
          'Maximum transverse weighted diagnostic intensity vs z', ...
          'z [m]', 'I_diag,max(x,y,t) [W/m^2]', ...
          'peak_intensity_maxperp_vs_z', ...
          plot_session, ...
          'run_warn_state', run_warn_state);




try
    f_custom_vis = [];
    if plasma_flag && ~isempty(D.store_peak_drho_over_rho_nt_ofi) && ...
       ~isempty(D.store_peak_drho_over_rho_nt_aval)
        if any(isfinite(D.store_peak_drho_over_rho_nt_ofi(:)))
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], D.store_peak_drho_over_rho_nt_ofi, [], ...
                'OFI peak normalized source-rate indicator on the y~0 slice: max_x(drho_OFI/dt)/rho_nt vs z', ...
                'z [m]', 'peak max_x on y~0 slice (drho_OFI/dt)/rho_nt [1/s]', ...
                'peak_drho_over_rho_nt_ofi', ...
                plot_session, ...
                'run_warn_state', run_warn_state);
        end

        if any(isfinite(D.store_peak_drho_over_rho_nt_aval(:)))
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], D.store_peak_drho_over_rho_nt_aval, [], ...
                'Avalanche peak normalized source-rate indicator on the y~0 slice: max_x(drho_aval/dt)/rho_nt vs z', ...
                'z [m]', 'peak max_x on y~0 slice (drho_aval/dt)/rho_nt [1/s]', ...
                'peak_drho_over_rho_nt_aval', ...
                plot_session, ...
                'run_warn_state', run_warn_state);
        end

        [ratio_ofi_aval, n_undefined_ratio_ofi_aval] = ratio_with_nan_on_small_den( ...
            D.store_peak_drho_over_rho_nt_ofi, D.store_peak_drho_over_rho_nt_aval, eps_safe);
        if n_undefined_ratio_ofi_aval > 0
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_ratio_undefined_low_signal_soft', ...
                'CerUPP:Diagnostics:RatioUndefinedLowSignalSoft', ...
                ['OFI/Aval ratio undefined for %d/%d samples (non-finite inputs or |den|<=%.3e); ', ...
                 'storing NaN.'], ...
                n_undefined_ratio_ofi_aval, numel(ratio_ofi_aval), eps_safe);
        end
        valid_ratio_ofi_aval = isfinite(ratio_ofi_aval);
        if any(valid_ratio_ofi_aval(:))
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], ratio_ofi_aval, [], ...
                'Signed ratio of peak normalized OFI to avalanche source-rate indicators vs z', ...
                'z [m]', 'signed peak normalized source-rate ratio OFI/Aval [-]', ...
                'peak_drho_over_rho_nt_ratio_ofi_to_aval', ...
                plot_session, ...
                'run_warn_state', run_warn_state);
        else
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'ofi_aval_ratio_plot_skipped', ...
                'CerUPP:Plot:OFIAvalRatioPlotSkipped', ...
                'Skipping OFI/Aval ratio plot: no finite samples in ratio trace.');
        end
    end

    if plasma_flag && ~isempty(D.store_drho_ofi_xz) && ...
       ~isempty(D.store_drho_aval_xz)
        have_drho_ofi = any(isfinite(D.store_drho_ofi_xz(:)));
        have_drho_aval = any(isfinite(D.store_drho_aval_xz(:)));
        if ~(have_drho_ofi || have_drho_aval)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'drho_diagnostics_unavailable', ...
                'CerUPP:Diagnostics:DrhoDiagnosticsUnavailable', ...
                ['Skipping drho_OFI/dt and drho_aval/dt side-view plots: ', ...
                 'store_drho_* contains no finite samples (drho_* not emitted by plasma model in this build).']);
        end
        if have_drho_ofi
            drho_ofi_plot = D.store_drho_ofi_xz;
            if numel(D.store_z) <= 1 || isvector(drho_ofi_plot)
                [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                    x, [], reshape(drho_ofi_plot, [], 1), [], ...
                    'Signed max_t drho_OFI/dt(x, y~0) at the stored z plane', ...
                    'x [m]', 'max_t drho_OFI/dt [m^-3/s]', ...
                    'drho_ofi_xz', ...
                    plot_session, ...
                    'run_warn_state', run_warn_state);
            else
                [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                    D.store_z, x, drho_ofi_plot, [], ...
                    'Signed max_t drho_OFI/dt(x, y~0, z)', ...
                    'z [m]', 'x [m]', ...
                    'drho_ofi_xz', ...
                    plot_session, ...
                    'cbar_label', 'max_t drho_OFI/dt [m^-3/s]', ...
                    'run_warn_state', run_warn_state);
            end
        end

        if have_drho_aval
            drho_aval_plot = D.store_drho_aval_xz;
            if numel(D.store_z) <= 1 || isvector(drho_aval_plot)
                [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                    x, [], reshape(drho_aval_plot, [], 1), [], ...
                    'Signed max_t drho_aval/dt(x, y~0) at the stored z plane', ...
                    'x [m]', 'max_t drho_aval/dt [m^-3/s]', ...
                    'drho_aval_xz', ...
                    plot_session, ...
                    'run_warn_state', run_warn_state);
            else
                [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                    D.store_z, x, drho_aval_plot, [], ...
                    'Signed max_t drho_aval/dt(x, y~0, z)', ...
                    'z [m]', 'x [m]', ...
                    'drho_aval_xz', ...
                    plot_session, ...
                    'cbar_label', 'max_t drho_aval/dt [m^-3/s]', ...
                    'run_warn_state', run_warn_state);
            end
        end
    end

    if ~isempty(D.store_fluence_xy_visible) && ...
       ~isempty(x_cut)
        f_custom = squeeze(real(D.store_fluence_xy_visible(:, iy_axis0, :)));
        [log_f_custom, f_custom_plot, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            f_custom, eps_safe, 'F_vis(x at y~0, z)', run_warn_state, 'end');

        [f_custom_vis, custom_vis_session, run_warn_state, ok_custom_vis_session] = ...
            plot_support_utils.begin_figure_session( ...
                plot_session.outdir, 'visible_fluence_log_customcolormap', ...
                run_warn_state, plot_session, ...
                'create_figure', true);
        if ok_custom_vis_session
            h_custom = surf(D.store_z, x_cut, log_f_custom, 'EdgeColor', 'none');
            shading(gca, get_plot_surface_shading_mode_local(plot_session));
            set(h_custom, 'FaceAlpha', 'flat', 'AlphaData', isfinite(f_custom_plot), ...
                'AlphaDataMapping', 'none');
            view(0,90);
            set(gca,'YDir','normal'); axis tight;
            xlabel('z [m]'); ylabel('x (y~0 cut) [m]');
            title('log10(F_vis(x at y~0, z) [J/m^2]) [custom colormap]', 'Interpreter', 'none');

            n_2 = 256;
            cmap_custom = zeros(n_2,3);
            cmap_low_frac = 0.35;
            cmap_high_frac = 0.70;
            n1 = floor(cmap_low_frac*n_2);
            n2 = floor(cmap_high_frac*n_2);
            for k = 1:n1
                tcol = (k-1)/max(n1-1,1); cmap_custom(k,:) = [0, 0, tcol];
            end
            for k = n1+1:n2
                tcol = (k-n1)/max(n2-n1,1); cmap_custom(k,:) = [0, tcol, 1];
            end
            for k = n2+1:n_2
                tcol = (k-n2)/max(n_2-n2,1); cmap_custom(k,:) = [tcol, 1, 1-tcol/2];
            end
            colormap(cmap_custom);
            cb = colorbar;
            ylabel(cb, 'log10(F_vis [J/m^2]); invalid/negative masked blank', 'Interpreter', 'none');

            run_warn_state = plot_support_utils.finalize_figure_session( ...
                f_custom_vis, custom_vis_session, run_warn_state);
            f_custom_vis = [];
        end
    end
catch me_ofi_plot
    plot_support_utils.close_figure_if_valid(f_custom_vis);
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', 'ofi_aval_visible_plot_block_failed', ...
        'CerUPP:Plot:OFIAvalVisiblePlotBlockFailed', ...
        'OFI/Aval/custom visible plotting block failed: %s', me_ofi_plot.message);
end


%======================================================================
%B-integral diagnostic: accumulated Kerr nonlinear phase vs z
%======================================================================
%Use definition-stable intensity peaks (I = |A_S|^2), independent of diagnostics_flag.
z_vec      = D.store_z(:);                    %[Nz 1]
i_oa_vec   = D.store_imax_code_oa(:);         %[Nz 1]
i_bc_vec   = D.store_imax_code_bc(:);         %[Nz 1]
i_max_vec  = D.store_imax_code_maxperp_kerr(:); % [Nz 1] Kerr-region max intensity metric

%Cumulative B-integrals:
% Build the scalar k0_vac*n2*int(I dz) diagnostic family here. In FEE-Kerr
% runs
% it remains an NLSE-style proxy rather than the exact applied FEE phase.
k_vac_b = medium_state.k0_vac;                    %[1/m]
b_scale_oa = resolve_b_integral_scale_trace_local(D, 'store_k0n2_oa', ...
    k_vac_b * medium_state.n2_kerr, z_vec);
[b_oa, b_oa_ref_z] = build_finite_aware_b_integral_trace_local(z_vec, i_oa_vec, b_scale_oa);
%on-axis B(z)

b_scale_bc = resolve_b_integral_scale_trace_local(D, 'store_k0n2_bc', ...
    k_vac_b * medium_state.n2_kerr, z_vec);
[b_bc, b_bc_ref_z] = build_finite_aware_b_integral_trace_local(z_vec, i_bc_vec, b_scale_bc);
%beam-center sampled B(z)

b_scale_max = resolve_b_integral_scale_trace_local(D, 'store_k0n2_maxperp_kerr', ...
    k_vac_b * medium_state.n2_kerr, z_vec);
[b_max, b_max_ref_z] = build_finite_aware_b_integral_trace_local(z_vec, i_max_vec, b_scale_max);
%max-Kerr-region-intensity B(z)

if ~kerr_active_effective
    b_family_label = 'No-Kerr B proxy';
    b_family_metric_text = 'k_0 n_2 int(I dz) proxy (Kerr inactive)';
elseif strcmpi(kerr_model_effective, 'fee_source')
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'postprocess_b_integral_fee_proxy', ...
        'CerUPP:Postprocess:BIntegralFEEProxy', ...
        ['The B-integral family remains the scalar k0_vac*n2*int(I dz) diagnostic proxy even when the active Kerr path ', ...
         'uses the FEE source form. Read these curves as NLSE-style phase proxies rather than exact FEE-side phase diagnostics.']);
    b_family_label = 'NLSE-style B proxy';
    b_family_metric_text = 'NLSE-style k_0 n_2 int(I dz) proxy';
else
    b_family_label = 'B-integral';
    b_family_metric_text = 'k_0 n_2 int(I dz)';
end
if isfinite(b_oa_ref_z)
    fprintf('On-axis %s reference sample: z0 = %.6e m (first finite stored sample)\n', ...
        lower(b_family_label), b_oa_ref_z);
end
fprintf('B-integral intensity metric: I = |A_S|^2 (diagnostics_flag-invariant)\n');
fprintf('Final on-axis B-integral  B_oa(L)   = %.2f rad\n', b_oa(end));
fprintf('Final max-intensity B-int B_max(L) [Kerr region] = %.2f rad\n', b_max(end));
b_integral_specs = { ...
    struct( ...
        'enabled', true, ...
        'trace', b_oa, ...
        'title_text', sprintf('On-axis %s B_oa(z) [per-z peak-in-time intensity; %s; %s]', ...
            b_family_label, b_family_metric_text, ...
            format_b_integral_reference_text_local(b_oa_ref_z)), ...
        'y_label', 'B_oa(z)-B_oa(z0) [rad]', ...
        'save_stem', 'B_integral_onaxis'), ...
    struct( ...
        'enabled', beam_center_offaxis_any, ...
        'trace', b_bc, ...
        'title_text', sprintf(['Beam-center centroid-sampled %s B_bc(z) ' ...
            '[per-z peak-in-time intensity; %s; %s]'], ...
            b_family_label, b_family_metric_text, ...
            format_b_integral_reference_text_local(b_bc_ref_z)), ...
        'y_label', 'B_bc(z)-B_bc(z0) [rad]', ...
        'save_stem', 'B_integral_beamcenter'), ...
    struct( ...
        'enabled', true, ...
        'trace', b_max, ...
        'title_text', sprintf(['Kerr-phase upper-bound estimate: integrates per-z max_{x,y in Kerr} I_{peak}(z) ' ...
                       '(not a single-path B-integral) [%s; %s]'], ...
                       b_family_metric_text, format_b_integral_reference_text_local(b_max_ref_z)), ...
        'y_label', 'B_max(z)-B_max(z0) [rad]', ...
        'save_stem', 'B_kerr_peak_upperbound') ...
};
for b_integral_idx = 1:numel(b_integral_specs)
    b_integral_spec = b_integral_specs{b_integral_idx};
    if ~b_integral_spec.enabled
        continue;
    end
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], b_integral_spec.trace, [], ...
              b_integral_spec.title_text, ...
              'z [m]', b_integral_spec.y_label, ...
              b_integral_spec.save_stem, ...
              plot_session, ...
              'run_warn_state', run_warn_state);
end
%--- z vs. peak transverse visible-band fluence ---
%Quantity: max_{x,y} int_t I_vis(x,y,t) dt [J/m^2].

[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], f_peak_vis, [], ...
          sprintf('Peak transverse visible-band fluence vs z (%s)', visible_band_label), ...
          'z [m]', 'F_vis,peak [J/m^2]', ...
          'fluence_maxperp_vis_vs_z', ...
          plot_session, ...
          'run_warn_state', run_warn_state);

%--- z vs. peak transverse fundamental-band fluence ---
%Quantity: max_{x,y} int_t I_fundamental-band(x,y,t) dt [J/m^2].
if plasma_flag
    if isfield(D, 'store_rho_int_maxperp') && ~isempty(D.store_rho_int_maxperp)
        rho_int_maxperp_trace = D.store_rho_int_maxperp(:).';
    else
        rho_int_maxperp_trace = squeeze(max(max(D.store_rho_int, [], 1), [], 2));
    end
    rho_int_bc = nan(size(z_vec));
    beamcenter_rho_int_valid = beam_center_offaxis_any;
    if beam_center_offaxis_any
        num_rho_planes = size(D.store_rho_int, 3);
        beamcenter_count_match = ...
            (num_rho_planes == numel(z_vec)) && ...
            (numel(store_beamcenter_ix) == num_rho_planes) && ...
            (numel(store_beamcenter_iy) == num_rho_planes);
        if ~beamcenter_count_match
            beamcenter_rho_int_valid = false;
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'postprocess_beamcenter_rho_int_count_mismatch', ...
                'CerUPP:Postprocess:BeamCenterRhoIntSkipped', ...
                ['Skipping the beam-center rho_int(z) trace because the stored-plane counts disagree: ', ...
                 'size(store_rho_int,3)=%d, numel(store_z)=%d, numel(store_beamcenter_ix)=%d, ', ...
                 'numel(store_beamcenter_iy)=%d.'], ...
                num_rho_planes, numel(z_vec), numel(store_beamcenter_ix), numel(store_beamcenter_iy));
        else
            iz_vec = (1:num_rho_planes).';
            valid_rho_bc_mask = isfinite(store_beamcenter_ix(:)) & isfinite(store_beamcenter_iy(:)) & ...
                (store_beamcenter_ix(:) >= 1) & (store_beamcenter_ix(:) <= size(D.store_rho_int, 1)) & ...
                (store_beamcenter_iy(:) >= 1) & (store_beamcenter_iy(:) <= size(D.store_rho_int, 2)) & ...
                (store_beamcenter_ix(:) == round(store_beamcenter_ix(:))) & ...
                (store_beamcenter_iy(:) == round(store_beamcenter_iy(:)));
            if any(valid_rho_bc_mask)
                bc_lin_rho = sub2ind(size(D.store_rho_int), ...
                    store_beamcenter_ix(valid_rho_bc_mask), ...
                    store_beamcenter_iy(valid_rho_bc_mask), ...
                    iz_vec(valid_rho_bc_mask));
                rho_int_bc(valid_rho_bc_mask) = D.store_rho_int(bc_lin_rho);
            end
        end
    end

    rho_int_plot_specs = { ...
        struct( ...
            'enabled', true, ...
            'trace', squeeze(D.store_rho_int(ix_axis0, iy_axis0, :)), ...
            'title', 'On-axis electron-density time integral vs z (log scale)', ...
            'save_name', 'rho_int_oa'), ...
        struct( ...
            'enabled', beamcenter_rho_int_valid, ...
            'trace', rho_int_bc, ...
            'title', 'Beam-center centroid-sampled electron-density time integral vs z (log scale)', ...
            'save_name', 'rho_int_beamcenter'), ...
        struct( ...
            'enabled', true, ...
            'trace', rho_int_maxperp_trace, ...
            'title', 'Maximum transverse electron-density time integral vs z (log scale)', ...
            'save_name', 'rho_int_maxperp') ...
    };
    for rho_plot_idx = 1:numel(rho_int_plot_specs)
        rho_plot_spec = rho_int_plot_specs{rho_plot_idx};
        if ~rho_plot_spec.enabled
            continue;
        end
        [rho_trace_log, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            rho_plot_spec.trace(:), eps_safe, ...
            sprintf('%s trace', rho_plot_spec.save_name), run_warn_state, 'end');
        [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
            D.store_z, [], rho_trace_log, [], ...
            rho_plot_spec.title, ...
            'z [m]', 'log10(int rho dt [m^-3 s])', ...
            rho_plot_spec.save_name, ...
            plot_session, ...
            'run_warn_state', run_warn_state);
    end
end

          

%z-dependent plots
%--- x-slices at y~0 across z (x-z cut, not cylindrical radial average) ---
%These slices track how fluence, free-electron density, and spectra evolve along z.
y_mid_idx= iy_axis0;       %index at y~0 (beam axis slice)
idx_fund_spectrum_c = [];
if have_store_spectral_intens
    [~, idx_fund_spectrum_c] = min(abs(grid_state.omega_window - omega_fund));
end

%Retain the visible-band x-z cut because it feeds multiple later plots/exports.
% This slice is resolved once above and reused here plus in onset detection.


%--- Intensity-weighted omega_fund-centered envelope phase vs z and x(y~0 cut) ---
if phase_diagnostic_flag && ~isempty(D.store_a_s_phase)
    store_phase_xy_r = extract_y0_xz_surface_local(D.store_a_s_phase, y_mid_idx);
    store_phase_xy_r = unwrap(store_phase_xy_r, [], 2);
    % storage_support.intensity_weighted_phase_mean uses a fixed relative
    % code-metric intensity floor within each stored z plane and first
    % reconstructs the omega_fund-centered envelope phase from A_S.

    phase_floor_for_label = 1e-12;
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, store_phase_xy_r, [], ...
        sprintf(['Unwrapped intensity-weighted omega_fund-centered envelope phase ' ...
                 '(A_S recentered to A0; unwrap along z, ' ...
                 'masked code-metric |A_S|^2 > %.0e*max_{x,y,t}|A_S|^2 at this z) [rad]'], ...
                phase_floor_for_label), ...
        'z [m]', 'x (y~0 cut) [m]', ...
        'phase', ...
        plot_session, ...
        'cbar_label', 'phase(A0) [rad]', ...
        'run_warn_state', run_warn_state);
    if beamcenter_ytrack_total_enabled
        store_phase_bc_ytrack = extract_ytracked_xz_surface_local( ...
            D.store_a_s_phase, beamcenter_ytrack_total);
        store_phase_bc_ytrack = unwrap(store_phase_bc_ytrack, [], 2);
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
            store_phase_bc_ytrack, [], ...
            sprintf(['Unwrapped intensity-weighted omega_fund-centered envelope phase ' ...
                     '(total-beam-center y-tracked cut; unwrap along z, ' ...
                     'masked code-metric |A_S|^2 > %.0e*max_{x,y,t}|A_S|^2 at this z) [rad]'], ...
                    phase_floor_for_label), ...
            'z [m]', 'x (total beam-center y-tracked cut) [m]', ...
            'phase_beamcenter_ytrack', ...
            plot_session, ...
            'cbar_label', 'phase(A0) [rad]', ...
            'run_warn_state', run_warn_state);
    end
end


%--- Fluence vs z and x(y~0 cut) ---
%Fluence F(x at y~0,z)= integral_t I(x at y~0,t;z) dt [J/m^2] (computed as trapz(t, I, 3)).
fluence_y0_surface = extract_y0_xz_surface_local(D.store_fluence_xy, y_mid_idx);
[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
        fluence_y0_surface, [], ...
        'Fluence F(x at y~0, z): [J/m^2]', ...
        'z [m]', 'x (y~0 cut) [m]', ...
        'fluence', ...
        plot_session, ...
        'cbar_label', 'Fluence [J/m^2]', ...
        'run_warn_state', run_warn_state);
run_warn_state = emit_surface_mask_support_plot_local( ...
    D.store_z, x_cut, fluence_y0_surface, ...
    'Fluence F(x at y~0, z): [J/m^2]', ...
    'z [m]', 'x (y~0 cut) [m]', ...
    'fluence_mask_support', ...
    'Fluence [J/m^2]', ...
    build_ycut_mask_support_overlay_lines_local( ...
        D.store_z, x_cut, mask, y_mid_idx, 'filtered mask edge'), ...
    plot_session, run_warn_state);
if beamcenter_ytrack_total_enabled
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
            extract_ytracked_xz_surface_local(D.store_fluence_xy, beamcenter_ytrack_total), [], ...
            'Fluence F(x at total beam-center y-tracked cut, z): [J/m^2]', ...
            'z [m]', 'x (total beam-center y-tracked cut) [m]', ...
            'fluence_beamcenter_ytrack', ...
            plot_session, ...
            'cbar_label', 'Fluence [J/m^2]', ...
            'run_warn_state', run_warn_state);
end
if plasma_flag
    %--- Plasma source RHS magnitude diagnostic ---

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
            log10(extract_y0_xz_surface_local(D.store_rhs_plasma, y_mid_idx) + eps_safe), [], ...
            ['log10(int_t |rhs_plasma(x at y~0,z,t)| dt [magnitude diagnostic, sqrt(W) s / m^2]; ' display_floor_note ')'], ...
            'z [m]', 'x (y~0 cut) [m]', ...
            'rhs_plasma_magnitude', ...
            plot_session, ...
            'cbar_label', ['log10(int_t |rhs_plasma| dt [sqrt(W) s / m^2]) [' display_floor_note ']'], ...
            'run_warn_state', run_warn_state);
end

if medium_state.nl_absorption_flag
    %--- Exact applied diagnostic NLA fluence-loss rate dF_NLA,applied,diag/dz ---

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
            log10(extract_y0_xz_surface_local(D.store_nla_loss_applied, y_mid_idx) + eps_safe), [], ...
            ['log10(dF_NLA,applied,diag/dz(x at y~0, z) [J/m^3]; ' display_floor_note ')'], ...
            'z [m]', 'x (y~0 cut) [m]', ...
            'nla_applied_dFdz', ...
            plot_session, ...
            'cbar_label', ['log10(dF_NLA,applied,diag/dz [J/m^3]) [' display_floor_note ']'], ...
            'run_warn_state', run_warn_state);
    %--- Weighted pre-NLA model-proxy diagnostic from J_mpa_model ---

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
            log10(extract_y0_xz_surface_local(D.store_j_mpa, y_mid_idx) + eps_safe), [], ...
            ['log10(weighted pre-NLA model-proxy dF/dz from J_mpa_model and I_preNLA [J/m^3]; ' display_floor_note ')'], ...
            'z [m]', 'x (y~0 cut) [m]', ...
            'j_mpa_model_dFdz', ...
            plot_session, ...
            'cbar_label', ['log10(weighted pre-NLA model-proxy dF/dz [J/m^3]) [' display_floor_note ']'], ...
            'run_warn_state', run_warn_state);
end


%--- Visible-band fluence ---
%Visible fluence F_vis(x at y~0,z) : [J/m^2]

%--- Plot-consistent metric (do NOT use colorbar limits):
%Max visible fluence at final z from the same y~0 x-z surface used by visible_fluence.*
fvis_max_end_from_visible_fluence_plot = NaN;
if isempty(store_fluence_xy_visible_r)
    [store_fluence_xy_visible_r, store_fluence_vis_onaxis] = ...
        build_visible_fluence_cuts_local(D.store_fluence_xy_visible, y_mid_idx, ix_axis0);
end
visible_fluence_plot = real(store_fluence_xy_visible_r);
visible_fluence_plot_can_skip_nonfinite_scan = false;
try
    [visible_fluence_plot, tmp_fvis_nonfinite_n, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
        visible_fluence_plot, 'store_fluence_xy_visible_r (plot-consistent metric)', naninfo, diag_cap_hi, false, run_warn_state);
    if (tmp_fvis_nonfinite_n == 0) && ~isempty(visible_fluence_plot)
        visible_fluence_plot_can_skip_nonfinite_scan = true;
        fvis_max_end_from_visible_fluence_plot = max(visible_fluence_plot(:, end));
    else
        fvis_max_end_from_visible_fluence_plot = NaN;
    end
catch me_2
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', 'fvis_max_end_unavailable', ...
        'CerUPP:Diagnostics:FvisMaxEndUnavailable', ...
        'Fvis_max_end_from_visible_fluence_plot unavailable: %s', me_2.message);
    fvis_max_end_from_visible_fluence_plot = NaN;
end

if visible_fluence_plot_can_skip_nonfinite_scan
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, visible_fluence_plot, [], ...
              'Visible-band fluence F_vis(x at y~0, z): [J/m^2]', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'visible_fluence', ...
              plot_session, ...
              'cbar_label', 'Visible-band fluence [J/m^2]', ...
              'skip_nonfinite_scan', true, 'run_warn_state', run_warn_state);
else
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, visible_fluence_plot, [], ...
              'Visible-band fluence F_vis(x at y~0, z): [J/m^2]', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'visible_fluence', ...
              plot_session, ...
              'cbar_label', 'Visible-band fluence [J/m^2]', ...
              'run_warn_state', run_warn_state);
end
if beamcenter_ytrack_visible_enabled
    visible_fluence_bc = real(extract_ytracked_xz_surface_local( ...
        D.store_fluence_xy_visible, beamcenter_ytrack_visible));
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, visible_fluence_bc, [], ...
              'Visible-band fluence F_vis(x at visible-band beam-center y-tracked cut, z): [J/m^2]', ...
              'z [m]', 'x (visible-band beam-center y-tracked cut) [m]', ...
              'visible_fluence_beamcenter_ytrack', ...
              plot_session, ...
              'cbar_label', 'Visible-band fluence [J/m^2]', ...
              'run_warn_state', run_warn_state);
end
%======================================================================
% y-integrated visible-band fluence (z-x image; log10 scale) is emitted once in the
% dedicated block later as 'side_view_visible_xz_log' to avoid duplicate
% near-identical outputs with diverging labels/scales.
%======================================================================


%Optional debug CSV exports
if output_cfg.export_csv_debug_flag
    fluence_xy_y0 = extract_y0_xz_surface_local(D.store_fluence_xy, y_mid_idx);
    debug_csv_specs = struct( ...
        'csv_name', { ...
            'diag_store_z.csv', ...
            'diag_x_y0_cut.csv', ...
            'diag_visible_fluence_y0_xz.csv', ...
            'diag_total_fluence_y0_xz.csv'}, ...
        'matrix_data', { ...
            D.store_z(:), ...
            x_cut(:), ...
            store_fluence_xy_visible_r, ...
            fluence_xy_y0});
    if plasma_flag
        rho_max_y0 = extract_y0_xz_surface_local(D.store_max_rho, y_mid_idx);
        rho_int_y0 = extract_y0_xz_surface_local(D.store_rho_int, y_mid_idx);
        debug_csv_specs(end+1:end+4) = struct( ...
            'csv_name', { ...
                'diag_rho_max_y0_xz.csv', ...
                'diag_rho_max_log10_y0_xz.csv', ...
                'diag_rho_int_y0_xz.csv', ...
                'diag_rho_int_log10_y0_xz.csv'}, ...
            'matrix_data', { ...
                rho_max_y0, ...
                log10(rho_max_y0 + eps_safe), ...
                rho_int_y0, ...
                log10(rho_int_y0 + eps_safe)});
    end
    run_warn_state = emit_postrun_matrix_csv_specs_local( ...
        run_warn_state, debug_csv_specs, csv_path_for_run);
end

%--- Time-integrated plasma (x|y~0,z), log10 scale ---
if plasma_flag
    rho_int_y0_surface = extract_y0_xz_surface_local(D.store_rho_int, y_mid_idx);
    [rho_int_y0_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        rho_int_y0_surface, eps_safe, 'rho_int y0 x-z map', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
              rho_int_y0_log_surface, [], ...
              'log10(int_t rho(x at y~0,z,t) dt [m^-3 s])', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'rho_int_z', ...
              plot_session, ...
              'cbar_label', 'log10(int_t rho dt [m^-3 s])', ...
              'run_warn_state', run_warn_state);
    if beamcenter_ytrack_total_enabled
        rho_int_bc_surface = extract_ytracked_xz_surface_local( ...
            D.store_rho_int, beamcenter_ytrack_total);
        [rho_int_bc_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            rho_int_bc_surface, eps_safe, ...
            'rho_int total beam-center y-tracked x-z map', run_warn_state, 'end');
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
                  rho_int_bc_log_surface, [], ...
                  'log10(int_t rho(x at total beam-center y-tracked cut, z, t) dt [m^-3 s])', ...
                  'z [m]', 'x (total beam-center y-tracked cut) [m]', ...
                  'rho_int_beamcenter_ytrack', ...
                  plot_session, ...
                  'cbar_label', 'log10(int_t rho dt [m^-3 s])', ...
                  'run_warn_state', run_warn_state);
    end
end

if plasma_flag
    rho_late_y0_surface = extract_y0_xz_surface_local(D.store_rho_late, y_mid_idx);
    [rho_late_y0_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        rho_late_y0_surface, eps_safe, 'rho_late y0 x-z map', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
              rho_late_y0_log_surface, [], ...
              'log10(rho(x at y~0,z,t_end) [m^-3])', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'rho_late_z', ...
              plot_session, ...
              'cbar_label', 'log10(rho(t_end) [m^-3])', ...
              'run_warn_state', run_warn_state);
    if beamcenter_ytrack_total_enabled
        rho_late_bc_surface = extract_ytracked_xz_surface_local( ...
            D.store_rho_late, beamcenter_ytrack_total);
        [rho_late_bc_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            rho_late_bc_surface, eps_safe, ...
            'rho_late total beam-center y-tracked x-z map', run_warn_state, 'end');
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, ...
                  rho_late_bc_log_surface, [], ...
                  'log10(rho(x at total beam-center y-tracked cut, z, t_end) [m^-3])', ...
                  'z [m]', 'x (total beam-center y-tracked cut) [m]', ...
                  'rho_late_beamcenter_ytrack', ...
                  plot_session, ...
                  'cbar_label', 'log10(rho(t_end) [m^-3])', ...
                  'run_warn_state', run_warn_state);
    end
end


%--- Central-frequency spectral fluence density ---
%Slice nearest omega_fund (fundamental angular frequency).
%Units: spectral fluence density at omega_fund index [J m^{-2} (rad/s)^{-1}] (diagnostic).
if ~isempty(idx_fund_spectrum_c)
    if have_store_spectral_fund_xy
        spectrum_c_y0 = extract_y0_xz_surface_local(D.store_spectral_fund_xy, y_mid_idx);
    else
        spectrum_c_y0 = extract_spectral_y0_xz_surface_local( ...
            D.store_spectral_intens, y_mid_idx, idx_fund_spectrum_c);
    end
    if ~isempty(spectrum_c_y0)
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, spectrum_c_y0, [], ...
              'Central spectral fluence density at omega_fund [J m^-2 (rad/s)^-1]', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'spectrum_c_x_y0cut', ...
              plot_session, ...
              'cbar_label', 'Central spectral fluence density [J m^-2 (rad/s)^-1]', ...
              'run_warn_state', run_warn_state);
    end
    if beamcenter_ytrack_fund_enabled
        if have_store_spectral_fund_xy
            spectrum_c_bc = extract_ytracked_xz_surface_local( ...
                D.store_spectral_fund_xy, beamcenter_ytrack_fund);
        else
            spectrum_c_bc = extract_spectral_ytracked_xz_surface_local( ...
                D.store_spectral_intens, beamcenter_ytrack_fund, idx_fund_spectrum_c);
        end
        if ~isempty(spectrum_c_bc)
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, spectrum_c_bc, [], ...
                  'Central spectral fluence density at omega_fund (fundamental beam-center y-tracked cut) [J m^-2 (rad/s)^-1]', ...
                  'z [m]', 'x (fundamental beam-center y-tracked cut) [m]', ...
                  'spectrum_c_beamcenter_ytrack', ...
                  plot_session, ...
                  'cbar_label', 'Central spectral fluence density [J m^-2 (rad/s)^-1]', ...
                  'run_warn_state', run_warn_state);
        end
    end
end

%--- free-electron density (max over time) ---
%Units: rho_max(z, x|y~0) [m^-3], plotted in log10 scale.
if plasma_flag
    rho_max_y0_surface = extract_y0_xz_surface_local(D.store_max_rho, y_mid_idx);
    [rho_max_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        rho_max_y0_surface, eps_safe, 'rho_max y0 x-z map', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, rho_max_log_surface, [], ...
              'log10(max_t rho(z, x at y~0) [m^-3])', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'rho_max_t_z', ...
              plot_session, ...
              'cbar_label', 'log10(rho_{max} [m^-3])', ...
              'run_warn_state', run_warn_state);
    if beamcenter_ytrack_total_enabled
        rho_max_bc_surface = extract_ytracked_xz_surface_local( ...
            D.store_max_rho, beamcenter_ytrack_total);
        [rho_max_bc_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            rho_max_bc_surface, eps_safe, ...
            'rho_max total beam-center y-tracked x-z map', run_warn_state, 'end');
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, rho_max_bc_log_surface, [], ...
                  'log10(max_t rho(z, x at total beam-center y-tracked cut) [m^-3])', ...
                  'z [m]', 'x (total beam-center y-tracked cut) [m]', ...
                  'rho_max_t_beamcenter_ytrack', ...
                  plot_session, ...
                  'cbar_label', 'log10(rho_{max} [m^-3])', ...
                  'run_warn_state', run_warn_state);
    end
end

%--- Spectral energy-density evolution (frequency domain) ---
%Spatially integrated spectrum S(z,nu) [J/Hz], plotted in log10 scale.
nu_sorted_plot = grid_state.nu_sorted;
idx_nu_plot = grid_state.idx_nu;
[store_spectrum_log10_plot, store_spectrum_plot, run_warn_state] = ...
    plot_support_utils.make_log10_nonnegative_for_plot( ...
        D.store_spectrum, eps_safe, 'S_nu (z-nu spectrum)', run_warn_state, 'end');
z_nu = store_spectrum_log10_plot(:, idx_nu_plot).';


s_lambda = store_spectrum_plot .* spectral_lambda_ctx.hz_to_nm_factor; %[J/nm]
s_lambda_sorted = s_lambda(:, spectral_lambda_ctx.idx_lam);
[spectral_db, run_warn_state] = build_partially_masked_normalized_db_surface_local( ...
    s_lambda_sorted, ...
    'Stored mixed-space z-lambda spectral-fluence map', ...
    'spectrum_lambda_db_nonfinite_map', ...
    'CerUPP:Plot:SpectrumLambdaDbNonfiniteMap', ...
    eps_safe, ...
    run_warn_state);
spectral_db_60  = max(min(spectral_db,   0), -60);
spectral_db_120 = max(min(spectral_db,   0), -120);

[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, nu_sorted_plot, z_nu, [], ...
    ['Stored mixed-space output spectrum vs z [log10(J/Hz); ' display_floor_note ']'], ...
    'z [m]', 'Frequency [Hz]', 'spectrum_energy_density_hz', ...
    plot_session, ...
    'cbar_label', ['log10(Stored mixed-space output spectrum [J/Hz]) [' display_floor_note ']'], ...
    'run_warn_state', run_warn_state);


[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, spectral_lambda_ctx.lambda_nm_sorted, spectral_db_60.', [], ...
    ['Stored mixed-space output spectrum vs z [dB, clipped [-60,0]; ' display_floor_note '], 0 dB = global max(z,lambda)'], ...
    'z [m]', 'Vacuum wavelength [nm]', 'spectrum_lambda_db60', ...
    plot_session, ...
    'cbar_label', ['normalized level [dB] (clipped [-60,0]; ' display_floor_note ')'], ...
    'run_warn_state', run_warn_state);

[~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, spectral_lambda_ctx.lambda_nm_sorted, spectral_db_120.', [], ...
    ['Stored mixed-space output spectrum vs z [dB, clipped [-120,0]; ' display_floor_note '], 0 dB = global max(z,lambda)'], ...
    'z [m]', 'Vacuum wavelength [nm]', 'spectrum_lambda_db120', ...
    plot_session, ...
    'cbar_label', ['normalized level [dB] (clipped [-120,0]; ' display_floor_note ')'], ...
    'run_warn_state', run_warn_state);

if perf_cfg.track_energy_flag && ~isempty(energy)
    %Energy trace includes all active numerical masks; if ramp regions of the
    %smooth k-space taper are populated, apparent loss can be dz-sensitive.

    energy_z_plot = grid_state.z_domain(:);
    energy_plot = [energy_launch; energy(:)];
    energy_title = ['Pulse energy vs z (launch + per-step trace from the ', ...
                    'shared weighted diagnostic fluence)'];
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(energy_z_plot, [], energy_plot, [], ...
              energy_title, ...
              'z [m]', 'Tracked energy [J]', ...
              'energy_vs_z', ...
              plot_session, ...
              'run_warn_state', run_warn_state);
end


%--- Final spectral x-lambda outputs in lambda-domain ---
%1) Near-field spectral fluence-density slice on the coordinate-nearest y~0 cut.
%2) Fourier-plane ky-integrated spectral-density map from the live final A_F field.
if have_store_spectral_y0_xomega_final || have_store_spectral_intens
    % Here H_e is the coordinate-nearest y~0 near-field diagnostic cut in lambda-space [J/m^2/nm].
    % H_spectral below denotes the stored or surrogate spectral fluence-density map.
    % (stored per angular frequency, [J/m^2/(rad/s)], before any omega->lambda scale conversion).
    % Definition (area-resolved): H_spectral(x,y,z,omega) =
    % d/domega [integral_t (Re(n_lin(x,y,omega))/Re(n_sell(omega_fund)))
    % |A_S|^2 dt] [J m^-2 (rad/s)^-1].
    % Definition (y~0 cut): H_e(y~0,lambda) = d/dlambda [integral_t (Re(n_lin(x,y,omega))/Re(n_sell(omega_fund))) |A_S|^2 dt] [J/m^2/nm].
    % Start from the per-omega spectral fluence density slice on the coordinate-nearest y~0 cut.

    if have_store_spectral_y0_xomega_final
        s_om_xy = real(D.store_spectral_y0_xomega_final); %[Nx x n], [J m^-2 (rad/s)^-1]
    else
        s_om_xy = real(reshape( ...
            D.store_spectral_intens(:, y_mid_idx, :, end), ...
            size(D.store_spectral_intens, 1), size(D.store_spectral_intens, 3)));
    end
    s_lambda_transverse = s_om_xy .* spectral_lambda_ctx.radps_to_nm_factor;     %[Nx x n], [J/m^2/nm]
    [s_lambda_transverse, ~, run_warn_state] = plot_support_utils.clamp_nonnegative_diagnostic_leakage( ...
        s_lambda_transverse, 'S_lambda_transverse (final x-lambda map)', ...
        run_warn_state, 'end', 'final_x_lambda_nonnegative_clamped', ...
        'CerUPP:Plot:FinalXLambdaNonnegativeClamped');
    s_lambda_transverse = s_lambda_transverse(:, spectral_lambda_ctx.idx_lam);    %reorder 

    x_um = x(:) / 1e-6;
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(x_um, spectral_lambda_ctx.lambda_nm_sorted, s_lambda_transverse.', [], ...
        'Final spectral fluence density on the coordinate-nearest y~0 cut (x-lambda) [J/m^2/nm]', ...
        'x [um]', 'Vacuum wavelength [nm]', ...
        'spectrum_transverse_final_lambda', plot_session, ...
        'cbar_label', 'Spectral fluence density [J/m^2/nm]', ...
        'run_warn_state', run_warn_state);
end

if ~isempty(A_F)
    % The Fourier-plane companion map is owned by the live final A_F field,
    % not by the stored near-field spectral fluence-density cube.

    af_spec = A_F;                                                    %[DFT units], already (kx,ky,omega)
    % Build an FFT-absolute ky-integrated spectrum density vs kx.
    % Keep this as a per-unit-kx density so the normalized display does
    % not drift just because the sampled delta_kx bin width changes.

    fft_scale_to_atilde = grid_state.delta_x * grid_state.delta_y * delta_t;
    s_omega_kx = zeros(size(af_spec, 1), size(af_spec, 3), 'like', real(af_spec(1)));
    omega_block_size = 32;
    for omega_block_start = 1:omega_block_size:size(af_spec, 3)
        omega_idx = omega_block_start:min(omega_block_start + omega_block_size - 1, size(af_spec, 3));
        af_block = af_spec(:, :, omega_idx);
        af_block_power = real(af_block .* conj(af_block));
        s_omega_kx(:, omega_idx) = reshape( ...
            grid_state.delta_ky * sum(af_block_power, 2), size(af_spec, 1), []);
    end
    s_hz_per_kx = s_omega_kx * ((fft_scale_to_atilde^2) / ((2*pi)^2)); %[J/Hz/(rad/m)]
    s_lambda_per_kx = s_hz_per_kx .* spectral_lambda_ctx.hz_to_nm_factor; %[J/nm/(rad/m)]
    [s_lambda_per_kx, ~, run_warn_state] = plot_support_utils.clamp_nonnegative_diagnostic_leakage( ...
        s_lambda_per_kx, 'S_lambda_per_kx (final ky-integrated spectral-density map)', ...
        run_warn_state, 'end', 'final_kx_lambda_nonnegative_clamped', ...
        'CerUPP:Plot:FinalKxLambdaNonnegativeClamped');
    den_kx = max(s_lambda_per_kx(:), [], 'omitnan');
    if ~isfinite(den_kx) || (den_kx <= 0)
        den_kx = eps_safe;
    end
    s_lambda_kx_db = 10*log10(s_lambda_per_kx ./ den_kx + eps_safe);
    s_lambda_kx_db = s_lambda_kx_db(:, spectral_lambda_ctx.idx_lam); %reorder

    [kx_rad_per_um_sorted, idx_kx] = sort(kx(:) / 1e6, 'ascend');
    s_lambda_kx_sorted = s_lambda_kx_db(idx_kx, :);
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(kx_rad_per_um_sorted, spectral_lambda_ctx.lambda_nm_sorted, s_lambda_kx_sorted.', [], ...
        ['Final Fourier-plane ky-integrated spectral-density map from A_F ' ...
         '(kx-lambda) [dB; 0 dB = map max]'], ...
        'kx [rad/um]', 'Vacuum wavelength [nm]', ...
        'spectrum_transverse_final_kx_lambda_db', plot_session, ...
        'cbar_label', ['normalized ky-integrated spectral density per unit kx [dB] ', ...
                       '(not directly comparable to the near-field fluence-density map)'], ...
        'run_warn_state', run_warn_state);
    kx_support_abs_sorted = compute_kx_mask_support_abs_sorted_local( ...
        kx, mask_f, mask_f_w, spectral_lambda_ctx.idx_lam);
    kx_exact_cone_abs_sorted = compute_kx_exact_forward_cone_abs_sorted_local( ...
        medium_state.n_sell, grid_state.omega_window, ...
        spectral_lambda_ctx.idx_lam, c);
    overlay_lines = [ ...
        build_kx_lambda_mask_support_overlay_lines_local( ...
            spectral_lambda_ctx.lambda_nm_sorted, ...
            kx_support_abs_sorted / 1e6, ...
            'filtered mask edge'), ...
        build_kx_lambda_exact_forward_cone_overlay_lines_local( ...
            spectral_lambda_ctx.lambda_nm_sorted, ...
            kx_exact_cone_abs_sorted / 1e6, ...
            'exact forward cone')];
    run_warn_state = emit_surface_mask_support_plot_local( ...
        kx_rad_per_um_sorted, spectral_lambda_ctx.lambda_nm_sorted, ...
        s_lambda_kx_sorted.', ...
        ['Final Fourier-plane ky-integrated spectral-density map from A_F ' ...
         '(kx-lambda) [dB; 0 dB = map max]'], ...
        'kx [rad/um]', 'Vacuum wavelength [nm]', ...
        'spectrum_transverse_final_kx_lambda_db_mask_support', ...
        ['normalized ky-integrated spectral density per unit kx [dB] ', ...
         '(not directly comparable to the near-field fluence-density map)'], ...
        overlay_lines, ...
        plot_session, run_warn_state);
end


%Detect filament onset and write information about "notches"
%OPTIONAL diagnostic section
%For literature context (YAG and air filamentation), see the curated
%bibliography in the manual sources (CerUPP manual TeX plus sample.bib).

%========================================================================
%Filament onset detection: visible-band peak intensity, free-electron density,
%and weighted diagnostic intensity
%========================================================================

%Each descriptor entry:
%- Holds a diagnostic trace vs z plus its reference threshold metadata
%- Preserves the explicit onset-detection method name
%- Drives one shared CSV/notch-export loop
%
% Onset-method naming conventions used in this driver:
% - 'threshold_crossing': first z where trace exceeds amplitude threshold.
% - 'first_decrease_after_threshold': first turning point after threshold crossing.
% - 'slope_to_peak': growth-slope-to-peak method (no amplitude threshold).
% - For notch accounting, always interpret det.threshold as an amplitude
%   cutoff in the trace's native units (never a slope/decrease threshold).


%======================================================================
%Filament onset detection diagnostics
%======================================================================
% Visible-band CSV outputs emitted here are:
%   filament_info_I_oa_vis.csv
%   filament_info_I_maxperp_vis.csv
i_max_oa = reduce_stored_time_max_local(D.store_intens_td_oa);
% max_t I_vis,diag(x~0,y~0,t) after visible-band reconstruction [W/m^2].

i_max_oa_vis = reduce_stored_time_max_local(D.store_intens_td_oa_vis);
% I_diag,max(z): max_{x,y,t} weighted diagnostic intensity [W/m^2].

i_max_maxperp = reduce_stored_time_max_local(D.store_intens_td_maxperp);
% max_{x,y,t} I_vis,diag(x,y,t) after visible-band reconstruction [W/m^2].

i_max_maxperp_vis = reduce_stored_time_max_local(D.store_intens_td_maxperp_vis);

% Table-driven CSV export keeps literal labels/methods/filenames centralized.
filament_diag_specs = struct( ...
    'trace', {}, ...
    'method', {}, ...
    'reference_scalar_name', {}, ...
    'reference_scalar_value', {}, ...
    'threshold_frac', {}, ...
    'threshold_abs', {}, ...
    'label', {}, ...
    'window_samples', {}, ...
    'csv_name', {});

filament_diag_specs(end+1) = struct( ...
    'trace', i_max_oa, ...
    'method', 'first_decrease_after_threshold', ...
        'reference_scalar_name', 'i_laser_peak', ...
        'reference_scalar_value', i_laser_peak, ...
        'threshold_frac', medium_state.intensity_onset_frac, ...
    'threshold_abs', NaN, ...
    'label', 'I_{oa}', ...
    'window_samples', 7, ...
    'csv_name', 'filament_info_I_oa.csv');
filament_diag_specs(end+1) = struct( ...
    'trace', i_max_oa_vis, ...
    'method', 'first_decrease_after_threshold', ...
        'reference_scalar_name', 'i_laser_peak', ...
        'reference_scalar_value', i_laser_peak, ...
        'threshold_frac', medium_state.vis_intensity_onset_frac, ...
    'threshold_abs', NaN, ...
    'label', 'I_oa_vis', ...
    'window_samples', 7, ...
    'csv_name', 'filament_info_I_oa_vis.csv');

% rho_{oa}(z): free-electron density at the on-axis fixed point, max_t over t [m^-3].
% For plasma traces, the reference scalar is rho_nt from setup-time validation.
if plasma_flag
    rho_trace_oa = squeeze(D.store_max_rho(ix_axis0, iy_axis0, :));
    filament_diag_specs(end+1) = struct( ...
        'trace', rho_trace_oa, ...
        'method', 'threshold_crossing', ...
        'reference_scalar_name', 'rho_nt', ...
        'reference_scalar_value', rho_nt, ...
        'threshold_frac', medium_state.rho_onset_frac, ...
        'threshold_abs', NaN, ...
        'label', 'rho_{oa}', ...
        'window_samples', [], ...
        'csv_name', 'filament_info_rho_oa.csv');
end

filament_diag_specs(end+1) = struct( ...
    'trace', i_max_maxperp, ...
    'method', 'first_decrease_after_threshold', ...
    'reference_scalar_name', 'i_laser_peak', ...
    'reference_scalar_value', i_laser_peak, ...
    'threshold_frac', medium_state.intensity_onset_frac, ...
    'threshold_abs', NaN, ...
    'label', 'I_{max}', ...
    'window_samples', 7, ...
    'csv_name', 'filament_info_I_maxperp.csv');
filament_diag_specs(end+1) = struct( ...
    'trace', i_max_maxperp_vis, ...
    'method', 'first_decrease_after_threshold', ...
    'reference_scalar_name', 'i_laser_peak', ...
    'reference_scalar_value', i_laser_peak, ...
    'threshold_frac', medium_state.vis_intensity_onset_frac, ...
    'threshold_abs', NaN, ...
    'label', 'I_max_vis', ...
    'window_samples', 7, ...
    'csv_name', 'filament_info_I_maxperp_vis.csv');

% rho_{max}(z): maximum free-electron density across x,y at each z (max_t) [m^-3].
if plasma_flag
    if isfield(D, 'store_max_rho_maxperp') && ~isempty(D.store_max_rho_maxperp)
        rho_trace_maxperp = D.store_max_rho_maxperp(:).';
    else
        rho_trace_maxperp = squeeze(max(max(D.store_max_rho, [], 1), [], 2));
    end
    filament_diag_specs(end+1) = struct( ...
        'trace', rho_trace_maxperp, ...
        'method', 'threshold_crossing', ...
        'reference_scalar_name', 'rho_nt', ...
        'reference_scalar_value', rho_nt, ...
        'threshold_frac', medium_state.rho_onset_frac, ...
        'threshold_abs', NaN, ...
        'label', 'rho_{max}', ...
        'window_samples', [], ...
        'csv_name', 'filament_info_rho_maxperp.csv');
end

run_warn_state = emit_postrun_filament_csv_specs_local( ...
    run_warn_state, filament_diag_specs, D.store_z, ...
    medium_state.distance_to_propagate, csv_path_for_run);
if ~(isstruct(run_warn_state) && isscalar(run_warn_state))
    invalid_run_warn_state_class = class(run_warn_state);
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        struct(), 'end', ...
        'postprocess_filament_csv_warn_state_reset', ...
        'CerUPP:Postprocess:FilamentCsvWarnStateReset', ...
        ['Section 6A filament CSV handling returned an invalid warning-ledger ', ...
         'payload (class=%s). Resetting the local end-phase warning ledger so ', ...
         'the remaining postprocessing plots can finish instead of failing.'], ...
        invalid_run_warn_state_class);
end

%--- End-of-run carrier-reference plasma-loading warnings (all-step peaks) ---
if plasma_flag
        frac_crit = rho_peak_over_rho_crit_ref_all_steps;
        frac_nt = rho_peak_over_rho_nt_all_steps;
        n0_fund_real = real(medium_state.n_sell_fund);
        has_dielectric_loading_ratio = isfinite(n0_fund_real) && (n0_fund_real > 1 + 1e-12);
        frac_crit_dielectric = NaN;
        if has_dielectric_loading_ratio
            frac_crit_dielectric = frac_crit / (n0_fund_real^2);
        end

        if isfinite(frac_crit)
            if frac_crit > 1.0
                if has_dielectric_loading_ratio
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_overdense', ...
                        'CerUPP:Plasma:Overdense', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m, with rho = %.3e m^-3 and ' ...
                         'rho_crit(omega_fund) = %.3e m^-3. For dielectric runs with n0(omega_fund) = %.3f, ' ...
                         'the closer collisionless-opacity guide is rho/(n0^2*rho_crit(omega_fund)) = %.2f. ' ...
                         'This warning tracks carrier-reference loading, not a universal broadband or true ' ...
                         'overdense criterion.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z, rho_at_peak_over_rho_crit_ref, ...
                        rho_crit_ref_at_peak, n0_fund_real, frac_crit_dielectric);
                else
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_overdense', ...
                        'CerUPP:Plasma:Overdense', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m, with rho = %.3e m^-3 and ' ...
                         'rho_crit(omega_fund) = %.3e m^-3. This warning tracks carrier-reference loading, ' ...
                         'not a universal broadband or true overdense criterion.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z, rho_at_peak_over_rho_crit_ref, ...
                        rho_crit_ref_at_peak);
                end
            elseif frac_crit > 0.3
                if has_dielectric_loading_ratio
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_near_critical', ...
                        'CerUPP:Plasma:NearCritical', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m (>0.3). For dielectric runs with ' ...
                         'n0(omega_fund) = %.3f, rho/(n0^2*rho_crit(omega_fund)) = %.2f at that same peak. ' ...
                         'This is a carrier-reference loading indicator, not a universal broadband or true ' ...
                         'near-critical opacity test.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z, n0_fund_real, frac_crit_dielectric);
                else
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_near_critical', ...
                        'CerUPP:Plasma:NearCritical', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m (>0.3). This is a carrier-reference ' ...
                         'loading indicator, not a universal broadband or true near-critical opacity test.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z);
                end
            elseif frac_crit > 0.1
                if has_dielectric_loading_ratio
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_high_plasma_fraction', ...
                        'CerUPP:Plasma:HighPlasmaFraction', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m (>0.1). For dielectric runs with ' ...
                         'n0(omega_fund) = %.3f, rho/(n0^2*rho_crit(omega_fund)) = %.2f at that same peak. ' ...
                         'Treat this as a carrier-reference loading indicator rather than a direct opacity or ' ...
                         'overdense claim.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z, n0_fund_real, frac_crit_dielectric);
                else
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_high_plasma_fraction', ...
                        'CerUPP:Plasma:HighPlasmaFraction', ...
                        ['Maximum over all propagation steps reached carrier-reference plasma loading ' ...
                         'rho/rho_crit(omega_fund) = %.2f at z = %.3e m (>0.1). Treat this as a ' ...
                         'carrier-reference loading indicator rather than a direct opacity or overdense claim.'], ...
                        frac_crit, rho_peak_over_rho_crit_ref_z);
                end
            end
        end

        if isfinite(frac_nt)
            resolved_nla_closure = nla_support.resolve_closure_record(nla_runtime_cfg);
            depletion_aware_nla_active = logical(struct_utils.opt_struct_field( ...
                resolved_nla_closure, 'nla_use_remaining_neutral_factor_flag_effective', ...
                false));
            matched_plasma_ofi_nla_enabled = logical(resolved_nla_closure.keldysh_nla_enabled);
            matched_nla_uses_fixed_density_scale = logical(matched_plasma_ofi_nla_enabled) && ...
                ~logical(depletion_aware_nla_active);
            nla_uses_neutral_fraction = logical(resolved_nla_closure.uses_neutral_fraction);
            if frac_nt > 1.0
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', 'post_rho_above_neutral', ...
                    'CerUPP:Plasma:RhoAboveNeutral', ...
                    ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>1), ' ...
                     'with rho = %.3e m^-3. Free-electron density exceeded the nominal neutral-density scale; ' ...
                     'rho bounds are controlled by rho_plasma_cap (built-in default rho_plasma_cap=rho_nt, so the default run clamps rho at the neutral reservoir).'], ...
                    frac_nt, rho_peak_over_rho_nt_z, rho_at_peak_over_rho_nt);
            elseif frac_nt > 0.5
                if nla_uses_neutral_fraction
	                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
	                        run_warn_state, 'end', 'post_neutral_depletion', ...
	                        'CerUPP:Plasma:NeutralDepletion', ...
                         ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>0.5). ' ...
                         'Neutral supply is strongly depleted; rho bounds are controlled by rho_plasma_cap ' ...
                         '(built-in default rho_plasma_cap=rho_nt, so the default run clamps rho at the neutral reservoir). The active NLA/MPA sink uses remaining-neutral weighting tied to ' ...
                         'the source-side rho_supply=neutral_reservoir_m3: OFI-based NLA runs apply ' ...
                         'loss_rate = max(rho_supply-rho,0)*Udep_matched*W_ion(I), where W_ion(I) denotes the active plasma OFI rate law, while the static remaining-neutral-weighted beta_K sink uses ' ...
                         'the corresponding cap-limited weight (rho_supply-rho)/rho_nt.'], ...
	                        frac_nt, rho_peak_over_rho_nt_z);
                elseif matched_nla_uses_fixed_density_scale
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_neutral_depletion', ...
                        'CerUPP:Plasma:NeutralDepletion', ...
                         ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>0.5). ' ...
                         'Neutral supply is strongly depleted; rho bounds are controlled by rho_plasma_cap ' ...
                         '(built-in default rho_plasma_cap=rho_nt, so the default run clamps rho at the neutral reservoir). The active OFI-based NLA sink uses the fixed-density-scale OFI setup: ' ...
                         'loss_rate = Udep_matched*rho_ofi_scale*W_ion(I), ' ...
                         'where W_ion(I) denotes the active plasma OFI rate law, so this sink is cap-aware through rho_supply but does not self-quench through max(rho_supply-rho,0).'], ...
                        frac_nt, rho_peak_over_rho_nt_z);
                else
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', 'post_neutral_depletion', ...
                        'CerUPP:Plasma:NeutralDepletion', ...
                        ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>0.5). ' ...
                         'Neutral supply is strongly depleted; rho bounds are controlled by rho_plasma_cap ' ...
                         '(built-in default rho_plasma_cap=rho_nt, so the default run clamps rho at the neutral reservoir). The active NLA/MPA sink remains the baseline static beta_K closure with no ' ...
                         'remaining-neutral prefactor; set nla_use_remaining_neutral_factor_flag=true only if you intentionally ' ...
                         'want neutral-weighted static absorption.'], ...
                        frac_nt, rho_peak_over_rho_nt_z);
                end
            elseif frac_nt > 0.1 && nla_uses_neutral_fraction
	                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
	                    run_warn_state, 'end', 'post_mpa_depletion_aware_closure', ...
	                    'CerUPP:Nla:MPADepletionAwareClosure', ...
	                    ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>0.1). ' ...
                     'A remaining-neutral-weighted NLA/MPA closure is active; in static beta_K runs ' ...
                     'this is beta_K,eff = beta_K*clamp((rho_supply-rho)/rho_nt,0,1) with ' ...
                     'rho_supply taken from the active source-side neutral_reservoir_m3, ' ...
                     'while OFI-based NLA runs apply loss_rate = max(rho_supply-rho,0)*Udep_matched*W_ion(I) with that same rho_supply, where W_ion(I) denotes the active plasma OFI rate law. ' ...
                     'interpretation against weak-ionization constant-beta formulas should be done with care.'], ...
	                    frac_nt, rho_peak_over_rho_nt_z);
            elseif frac_nt > 0.1 && matched_nla_uses_fixed_density_scale
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', 'post_mpa_depletion_aware_closure', ...
                    'CerUPP:Nla:MPADepletionAwareClosure', ...
                    ['Maximum over all propagation steps reached rho/rho_nt = %.2f at z = %.3e m (>0.1). ' ...
                     'The OFI-based NLA sink uses the fixed-density-scale OFI setup: ' ...
                     'loss_rate = Udep_matched*rho_ofi_scale*W_ion(I), where W_ion(I) denotes the active plasma OFI rate law. ' ...
                     'Interpretation against weak-ionization constant-beta formulas should be done with care because this branch changes the weighting, not the underlying OFI rate family.'], ...
                    frac_nt, rho_peak_over_rho_nt_z);
            end
        end
end


%======================================================================
%OPTIONAL 3D Visualization (memory intensive)
%======================================================================
if output_cfg.show_3d_diagnostic_plots_flag
    cut_frac = 0.5;                            %fraction of each field maximum for isosurface threshold
    z_idx= 1:output_cfg.z_3d_slice:numel(D.store_z); %downsample in z
    isosurface_plot_session = plot_session;
    isosurface_plot_session.warn = false;

    %Scatter-path memory guard: downsample xyz points when point count is large.
    scatter3_point_budget = 1.5e6; %set Inf to disable point-budget downsampling
    ix_scatter = 1:numel(x);
    iy_scatter = 1:numel(y);
    iz_scatter = 1:numel(z_idx);
    scatter_stride = 1;
    n_scatter_full = double(numel(ix_scatter)) * ...
                     double(numel(iy_scatter)) * ...
                     double(numel(iz_scatter));
    if isfinite(scatter3_point_budget) && (scatter3_point_budget > 0) && ...
            (n_scatter_full > scatter3_point_budget)
        scatter_stride = ceil((n_scatter_full / scatter3_point_budget)^(1/3));
        ix_scatter = 1:scatter_stride:numel(x);
        iy_scatter = 1:scatter_stride:numel(y);
        iz_scatter = 1:scatter_stride:numel(z_idx);
        n_scatter_used = double(numel(ix_scatter)) * ...
                         double(numel(iy_scatter)) * ...
                         double(numel(iz_scatter));
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, ...
            'end', ...
            'show3d_scatter_downsample', ...
            'CerUPP:Plot:Show3DScatterDownsample', ...
            ['show_3d scatter downsample applied (points %.3e -> %.3e, stride=%d). ' ...
             'Set scatter3_point_budget=Inf in cerupp.m to disable.'], ...
            n_scatter_full, n_scatter_used, scatter_stride);
    end
    render_title_suffix = sprintf(' (z render stride=%d stored planes', output_cfg.z_3d_slice);
    if scatter_stride > 1
        render_title_suffix = sprintf('%s; scatter downsample stride=%d', render_title_suffix, scatter_stride);
    end
    render_title_suffix = [render_title_suffix ')'];

    x_scatter_mm = x(ix_scatter) / 1e-3;
    y_scatter_mm = y(iy_scatter) / 1e-3;
    z_scatter_mm = D.store_z(z_idx(iz_scatter)) / 1e-3;

    nx_scatter = numel(x_scatter_mm);
    ny_scatter = numel(y_scatter_mm);
    nz_scatter = numel(z_scatter_mm);
    % Match ndgrid(:) column-major ordering without allocating X/Y/Z cubes.

    x_vals = repmat(x_scatter_mm(:), ny_scatter * nz_scatter, 1);
    y_vals = repmat(repelem(y_scatter_mm(:), nx_scatter), nz_scatter, 1);
    z_vals = repelem(z_scatter_mm(:), nx_scatter * ny_scatter);

    %---------------- Fluence 3D scatter ----------------
    %Fluence F(x,y,z) : [J/m^2]
    fluence_scatter = D.store_fluence_xy(ix_scatter, iy_scatter, z_idx(iz_scatter));

    c_vals_fluence= fluence_scatter(:);

    run_warn_state = plot_utils.make_scatter3_plot(x_vals, y_vals, z_vals, c_vals_fluence, ...
        sprintf('Fluence [J/m^2]%s', render_title_suffix), 'x [mm]', 'y [mm]', 'z [mm]', ...
        'fluence_3d', plot_session, ...
        'cbar_label', 'Fluence [J/m^2]', ...
        'run_warn_state', run_warn_state);

    %---------------- Central spectral fluence-density 3D scatter ----------------
    spectrum_c_sub = [];
    if ~isempty(idx_fund_spectrum_c)
        if have_store_spectral_fund_xy
            spectrum_c_scatter = D.store_spectral_fund_xy( ...
                ix_scatter, iy_scatter, z_idx(iz_scatter));
        else
            spectrum_c_scatter = extract_spectral_xyz_volume_indexed_local( ...
                D.store_spectral_intens, ix_scatter, iy_scatter, ...
                idx_fund_spectrum_c, z_idx(iz_scatter));
        end
    else
        spectrum_c_scatter = [];
    end
    if ~isempty(spectrum_c_scatter)
        c_vals_spec= spectrum_c_scatter(:);

        run_warn_state = plot_utils.make_scatter3_plot(x_vals, y_vals, z_vals, c_vals_spec, ...
            sprintf(['Spectral fluence density at omega approx omega_fund [J m^-2 (rad/s)^-1]%s'], ...
                render_title_suffix), ...
            'x [mm]', 'y [mm]', 'z [mm]', ...
            'spectrum_c_3d', plot_session, ...
            'cbar_label', 'Spectral fluence density [J m^-2 (rad/s)^-1]', ...
            'run_warn_state', run_warn_state);
    end


    if plasma_flag
        %---------------- free-electron density 3D scatter ----------------
        %rho_max(x,y,z) : [m^-3]

        rho_max_scatter = D.store_max_rho(ix_scatter, iy_scatter, z_idx(iz_scatter));
        [c_vals_rho_max, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            rho_max_scatter(:), eps_safe, 'rho_max 3d scatter', run_warn_state, 'end');

        run_warn_state = plot_utils.make_scatter3_plot(x_vals, y_vals, z_vals, c_vals_rho_max, ...
            sprintf('log10(rho_max [m^-3])%s', render_title_suffix), 'x [mm]', 'y [mm]', 'z [mm]', ...
            'rho_max_3d', plot_session, ...
            'cbar_label', 'log10(rho_max [m^-3])', ...
            'run_warn_state', run_warn_state);
    end

    %---------------- Rendered 3D surfaces ----------------
    % Stems use *_surface3d so these rendered surfaces group cleanly with
    % the corresponding *_3d scatter companions in output_plots/.
    %Downsampled coordinate vectors for isosurface plotting
    z_mm = D.store_z(z_idx)/1e-3;  % z in mm, downsampled
    x_mm = x/1e-3;               % x in mm (match z units for 3D geometry)
    y_mm = y/1e-3;               % y in mm (match z units for 3D geometry)
    fluence_sub= D.store_fluence_xy(:, :, z_idx);

    [run_warn_state, naninfo] = plot_support_utils.emit_isosurface_volume( ...
        run_warn_state, naninfo, x_mm, y_mm, z_mm, fluence_sub, cut_frac, ...
        'Fluence isosurface at F = %.3g J/m^2 (%.0f%% of max over plotted z subset; z stride=%d stored planes)', ...
        'fluence_surface3d', ...
        'Fluence isosurface skipped: invalid max value.', ...
        'Fluence isosurface skipped in plotting helper.', ...
        'Fluence isosurface skipped after sanitation (n_nan=%d, n_cap=%d).', ...
        isosurface_plot_session, output_cfg.z_3d_slice);

    if plasma_flag
        rho_max_sub= D.store_max_rho(:, :, z_idx);
        [run_warn_state, naninfo] = plot_support_utils.emit_isosurface_volume( ...
            run_warn_state, naninfo, x_mm, y_mm, z_mm, rho_max_sub, cut_frac, ...
            'rho_max isosurface at %.3g m^-3 (%.0f%% of max over plotted z subset; z stride=%d stored planes)', ...
            'rho_max_surface3d', ...
            'Plasma-density isosurface skipped: invalid max value.', ...
            'Plasma-density isosurface skipped in plotting helper.', ...
            'Plasma-density isosurface skipped after sanitation (n_nan=%d, n_cap=%d).', ...
            isosurface_plot_session, output_cfg.z_3d_slice);
    end

    if ~isempty(idx_fund_spectrum_c)
        if have_store_spectral_fund_xy
            spectrum_c_sub = D.store_spectral_fund_xy(:, :, z_idx);
        else
            spectrum_c_sub = extract_spectral_xyz_volume_local( ...
                D.store_spectral_intens, idx_fund_spectrum_c, z_idx);
        end
    end
    if ~isempty(spectrum_c_sub)
        [run_warn_state, naninfo] = plot_support_utils.emit_isosurface_volume( ...
            run_warn_state, naninfo, x_mm, y_mm, z_mm, spectrum_c_sub, cut_frac, ...
            ['Spectral fluence-density isosurface at \\omega \\approx \\omega_{fund}: %.3g J m^-2 (rad/s)^-1 ' ...
             '(%.0f%% of max over plotted z subset; z stride=%d stored planes)'], ...
            'spectrum_c_surface3d', ...
            'Central-spectrum isosurface skipped: invalid max value.', ...
            'Central-spectrum isosurface skipped in plotting helper.', ...
            'Central-spectrum isosurface skipped after sanitation (n_nan=%d, n_cap=%d).', ...
            isosurface_plot_session, output_cfg.z_3d_slice);
    end


end
family_ledger = mark_postprocess_family_ok_local( ...
    family_ledger, 'longitudinal_diagnostics');
catch me_family_longitudinal
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'longitudinal_diagnostics', me_family_longitudinal);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'longitudinal_diagnostics', me_family_longitudinal);
end
% Runtime summary/timing publication is emitted after Section 6B so the
% reported plotting phase covers the full post-run plot family.

%--- On-axis spectrum vs z (near-field, on-axis fixed point) ---
%Prefers reduced point-spectrum traces and falls back to the stored 4D
%cube only when those reduced traces are unavailable.
try
if have_store_spectral_line_oa || have_store_spectral_intens

    ix = ix_axis0;   %x index at x~0
    iy = iy_axis0;   %y index at y~0

    %S_oa_omega_z(iz,:) : on-axis, pointwise spectral fluence density vs omega at each z
    if have_store_spectral_line_oa
        [s_oa_omega_z, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
            D.store_spectral_line_oa, ...
            'On-axis stored z-omega spectrum history', ...
            'stored_spectral_line_oa_complex_leakage', ...
            'CerUPP:Plot:StoredSpectralComplexLeakage', ...
            run_warn_state); %[num_storage_steps x n], [J m^-2 (rad/s)^-1]
    else
        [s_oa_omega_z, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
            squeeze(D.store_spectral_intens(ix, iy, :, :)).', ...
            'On-axis rebuilt z-omega spectrum history', ...
            'rebuilt_spectral_line_oa_complex_leakage', ...
            'CerUPP:Plot:StoredSpectralComplexLeakage', ...
            run_warn_state); %[num_storage_steps x n], [J m^-2 (rad/s)^-1]
    end
    [~, s_oa_omega_plot, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        s_oa_omega_z, eps_safe, 'S_oa_omega_z (on-axis z-omega spectrum)', run_warn_state, 'end');

    % Convert spectral fluence density from per-(rad/s) to per-nm on the
    % plotted lambda axis. S(omega) domega = S(lambda) dlambda, with
    % |domega/dlambda| = 2*pi*c/lambda^2. The cached factor already reports
    % the per-nm conversion directly.
    s_lambda_oa = s_oa_omega_plot .* spectral_lambda_ctx.radps_to_nm_factor; %[J/m^2/nm]
    s_lambda_oa_sorted = s_lambda_oa(:, spectral_lambda_ctx.idx_lam); %reorder columns to ascending 

    [spectral_db_oa, run_warn_state] = build_partially_masked_normalized_db_surface_local( ...
        s_lambda_oa_sorted, ...
        'On-axis z-lambda spectral-fluence map', ...
        'spectrum_lambda_db_oa_nonfinite_map', ...
        'CerUPP:Plot:SpectrumLambdaDbOnAxisNonfiniteMap', ...
        eps_safe, ...
        run_warn_state);
    run_warn_state = emit_z_lambda_db_products_local( ...
        D.store_z, spectral_lambda_ctx.lambda_nm_sorted, spectral_db_oa, ...
        'On-axis spectral fluence density vs z', ...
        {'spectrum_lambda_db60_oa', 'spectrum_lambda_db120_oa'}, ...
        display_floor_note, plot_session, run_warn_state);
    run_warn_state = emit_z_lambda_db_mask_support_products_local( ...
        D.store_z, spectral_lambda_ctx.lambda_nm_sorted, spectral_db_oa, ...
        mask_f_w_sorted, ...
        'On-axis spectral fluence density vs z', ...
        {'spectrum_lambda_db60_oa_mask_support', ...
         'spectrum_lambda_db120_oa_mask_support'}, ...
        display_floor_note, plot_session, run_warn_state);

    if beam_center_offaxis_any
        if have_store_spectral_line_bc
            [s_bc_omega_z, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
                D.store_spectral_line_bc, ...
                'Beam-center stored z-omega spectrum history', ...
                'stored_spectral_line_bc_complex_leakage', ...
                'CerUPP:Plot:StoredSpectralComplexLeakage', ...
                run_warn_state); %[num_storage_steps x n], [J m^-2 (rad/s)^-1]
        else
            nx_spec = size(D.store_spectral_intens, 1);
            ny_spec = size(D.store_spectral_intens, 2);
            n_spec = size(D.store_spectral_intens, 3);
            nz_spec = size(D.store_spectral_intens, 4);
            spec_line_bc = nan(n_spec, nz_spec, 'like', real(D.store_spectral_intens(1)));
            if beamcenter_spectral_plane_count < nz_spec
                run_warn_state = emit_short_beamcenter_spectral_history_warning_local( ...
                    run_warn_state, nz_spec, beamcenter_spectral_plane_count, ...
                    'the rebuilt beam-center z-omega spectrum');
            end
            beamcenter_spectral_plane_count_spec = min(beamcenter_spectral_plane_count, nz_spec);
            ix_bc_spec = store_beamcenter_ix(1:beamcenter_spectral_plane_count_spec);
            iy_bc_spec = store_beamcenter_iy(1:beamcenter_spectral_plane_count_spec);
            valid_bc_mask = isfinite(ix_bc_spec) & isfinite(iy_bc_spec) & ...
                (ix_bc_spec >= 1) & (ix_bc_spec <= nx_spec) & ...
                (iy_bc_spec >= 1) & (iy_bc_spec <= ny_spec) & ...
                (ix_bc_spec == round(ix_bc_spec)) & (iy_bc_spec == round(iy_bc_spec));
            if any(valid_bc_mask)
                valid_planes = find(valid_bc_mask).';
                ix_bc_valid = double(ix_bc_spec(valid_bc_mask)).';
                iy_bc_valid = double(iy_bc_spec(valid_bc_mask)).';
                % Rebuild one plane at a time so the fallback path does not
                % allocate replicated omega/plane index tables just to read
                % a single beam-center spectrum from each stored plane.
                for iplane = 1:numel(valid_planes)
                    spec_line_bc(:, valid_planes(iplane)) = reshape( ...
                        D.store_spectral_intens( ...
                            ix_bc_valid(iplane), ...
                            iy_bc_valid(iplane), ...
                            :, ...
                            valid_planes(iplane)), ...
                        n_spec, 1);
                end
            end
            [s_bc_omega_z, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
                spec_line_bc.', ...
                'Beam-center rebuilt z-omega spectrum history', ...
                'rebuilt_spectral_line_bc_complex_leakage', ...
                'CerUPP:Plot:StoredSpectralComplexLeakage', ...
                run_warn_state); %[num_storage_steps x n], [J m^-2 (rad/s)^-1]
        end
        [~, s_bc_omega_plot, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
            s_bc_omega_z, eps_safe, 'S_bc_omega_z (beam-center z-omega spectrum)', run_warn_state, 'end');
        s_lambda_bc = s_bc_omega_plot .* spectral_lambda_ctx.radps_to_nm_factor; %[J/m^2/nm]
        s_lambda_bc_sorted = s_lambda_bc(:, spectral_lambda_ctx.idx_lam);
        [spectral_db_bc, run_warn_state] = build_partially_masked_normalized_db_surface_local( ...
            s_lambda_bc_sorted, ...
            'Beam-center z-lambda spectral-fluence map', ...
            'spectrum_lambda_db_beamcenter_nonfinite_map', ...
            'CerUPP:Plot:SpectrumLambdaDbBeamCenterNonfiniteMap', ...
            eps_safe, ...
            run_warn_state);
        run_warn_state = emit_z_lambda_db_products_local( ...
            D.store_z, spectral_lambda_ctx.lambda_nm_sorted, spectral_db_bc, ...
            'Beam-center centroid-sampled spectral fluence density vs z', ...
            {'spectrum_lambda_db60_beamcenter', 'spectrum_lambda_db120_beamcenter'}, ...
            display_floor_note, plot_session, run_warn_state);
    end
end

%--- free-electron density (max over time) ---
%rho_max(z, x at y~0) : [m^-3], log10 scale.
if plasma_flag
    rho_max_y0_surface = extract_y0_xz_surface_local(D.store_max_rho, y_mid_idx);
    [rho_max_log_surface, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        rho_max_y0_surface, eps_safe, 'rho_max y0 x-z map', run_warn_state, 'end');
else
    rho_max_log_surface = [];
end


%---- Beam-center / peak logging ----
current_time= datestr(now,'yyyy-mm-dd_HHMMSS');

if output_cfg.export_csv_debug_flag && ...
   ~isempty(D.store_centroid_r) && ...
   ~isempty(D.store_peak_r)

    beam_center_r_final = D.store_centroid_r(end);  %[m]
    peak_r_final        = D.store_peak_r(end);      %[m]

    snapshot_file = csv_path_for_run(['beam_center_snapshot_' current_time '.csv']);
    beam_metrics_row = table( ...
        {run_id}, grid_state.z_domain(end), beam_center_r_final, peak_r_final, ...
        'VariableNames', {'run_id','z_m','beam_center_r_m','peak_r_m'});
    try
        snapshot_dir = fileparts(snapshot_file);
        if ~isempty(snapshot_dir) && exist(snapshot_dir, 'dir') ~= 7
            mkdir(snapshot_dir);
        end
        writetable(beam_metrics_row, snapshot_file);
        disp(['Data saved to ' snapshot_file]);
    catch me_beam_snapshot
        run_warn_state = emit_postrun_output_io_failure_local( ...
            run_warn_state, 'beam_metrics_snapshot', snapshot_file, me_beam_snapshot, ...
            'beam_metrics_snapshot_failed', 'CerUPP:IO:BeamMetricsSnapshotFailed', ...
            'Could not write %s (%s).');
    end

end

%log10 of visible-band fluence F_vis(x at y~0,z) [J/m^2]
if ~isempty(store_fluence_xy_visible_r)
[visible_fluence_log, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
        store_fluence_xy_visible_r, eps_safe, 'store_fluence_xy_visible_r', run_warn_state, 'end');
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, visible_fluence_log, [], ...
              'log10(F_vis(x at y~0, z) [J/m^2]) [invalid/negative masked blank]', ...
              'z [m]', 'x (y~0 cut) [m]', ...
              'visible_fluence_log', ...
              plot_session, ...
              'cbar_label', 'log10(F_vis [J/m^2]); invalid/negative masked blank', ...
              'skip_nonfinite_scan', true, 'run_warn_state', run_warn_state);
end

%Nonlinear absorption (local sink) energy-loss diagnostics
if ~isempty(D.store_mpa_d_e_dz)
    % Stored post-step diagnostic NLA loss samples are interpreted as
    % uniform span samples over the saved intervals (z_{k-1}, z_k] for
    % display/reconstruction.

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], D.store_mpa_d_e_dz, [], ...
              'Saved-span diagnostic NLA loss sample over (z_{k-1}, z_k], plotted at z_k [J/m]', ...
              'z [m]', 'dE_loss,NLA,diag/dz over (z_{k-1}, z_k] [J/m]', ...
              'NLA_dE_dz', ...
              plot_session, ...
              'run_warn_state', run_warn_state);

    % Reconstruct cumulative diagnostic NLA loss by treating each saved
    % sample as uniform across its saved z span back to the prior saved plane.
    [mpa_e_loss_int, mpa_cumulative_status] = build_launch_anchored_cumulative_loss_local( ...
        grid_state.z_domain(1), D.store_z, D.store_mpa_d_e_dz);
    if mpa_cumulative_status.ok
        z_mpa_plot = [grid_state.z_domain(1); D.store_z(:)];
        e_mpa_plot = [0; mpa_e_loss_int(:)];
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(z_mpa_plot, [], e_mpa_plot, [], ...
                  'Cumulative diagnostic NLA loss reconstructed from saved z-span samples [J]', ...
                  'z [m]', 'E_loss,NLA,diag(z) [J]', ...
                  'NLA_E_loss_int', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);

        %Fraction of tracked launch energy lost to NLA
        if perf_cfg.track_energy_flag && ~isempty(energy) && isfinite(energy_launch)
            e_in    = energy_launch;
            frac_mpa = mpa_e_loss_int / max(e_in, eps_safe);
            frac_mpa_plot = [0; frac_mpa(:)];
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(z_mpa_plot, [], frac_mpa_plot, [], ...
                      'Fraction of tracked launch energy lost to NLA (from saved z-span samples)', ...
                      'z [m]', 'E_NLA,diag(z) / E_launch,tracked', ...
                      'NLA_loss_fraction', ...
                      plot_session, ...
                      'run_warn_state', run_warn_state);
        end
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'nla_cumulative_loss_reconstruction_skipped', ...
            'CerUPP:Plot:CumulativeNlaLossReconstructionSkipped', ...
            'Skipping cumulative NLA-loss outputs because the stored z/loss metadata is invalid: %s', ...
            mpa_cumulative_status.message);
    end
end

if ~isempty(D.store_plasma_field_d_e_dz)
    % Plot the diagnostic-weighted plasma-substep |A|^2 drop stored as
    % saved-z-span samples over (z_{k-1}, z_k].

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], D.store_plasma_field_d_e_dz, [], ...
              'Saved-span diagnostic-weighted plasma-substep field-drop sample over (z_{k-1}, z_k], plotted at z_k [J/m]', ...
              'z [m]', 'dE_field,plasma,solver/dz over (z_{k-1}, z_k] [J/m]', ...
              'plasma_field_dE_dz', ...
              plot_session, ...
              'run_warn_state', run_warn_state);
    [plasma_field_e_loss_int, plasma_cumulative_status] = build_launch_anchored_cumulative_loss_local( ...
        grid_state.z_domain(1), D.store_z, D.store_plasma_field_d_e_dz);
    if plasma_cumulative_status.ok
        z_plasma_loss_plot = [grid_state.z_domain(1); D.store_z(:)];
        plasma_field_loss_plot = [0; plasma_field_e_loss_int(:)];
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(z_plasma_loss_plot, [], plasma_field_loss_plot, [], ...
                  'Cumulative diagnostic-weighted plasma-substep field drop reconstructed from saved z-span samples [J]', ...
                  'z [m]', 'E_field,plasma,solver(z) [J]', ...
                  'plasma_field_E_loss_int', ...
                  plot_session, ...
                  'run_warn_state', run_warn_state);
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plasma_cumulative_loss_reconstruction_skipped', ...
            'CerUPP:Plot:CumulativePlasmaLossReconstructionSkipped', ...
            'Skipping cumulative plasma-loss outputs because the stored z/loss metadata is invalid: %s', ...
            plasma_cumulative_status.message);
    end
end


%---- Total-fluence centroid/peak location vs z (not runtime beam-center tracker) ----
% Stored centroid/beamwidth traces remain in meters; the plotted views are rescaled to microns.
rmean_fluence_trace = [];
if isfield(D, 'store_rmean_fluence')
    rmean_fluence_trace = D.store_rmean_fluence;
end
location_trace_specs = { ...
    struct('trace_um', 1e6 * D.store_centroid_x, 'title_text', 'Total fluence centroid x_center(z)', ...
        'y_label', 'x_center [um]', 'save_stem', 'centroid_x_vs_z'), ...
    struct('trace_um', 1e6 * D.store_centroid_y, 'title_text', 'Total fluence centroid y_center(z)', ...
        'y_label', 'y_center [um]', 'save_stem', 'centroid_y_vs_z'), ...
    struct('trace_um', 1e6 * D.store_centroid_r, 'title_text', 'Total fluence centroid radial distance r_center(z)', ...
        'y_label', 'r_center [um]', 'save_stem', 'centroid_r_vs_z'), ...
    struct('trace_um', 1e6 * rmean_fluence_trace, 'title_text', 'Total-fluence radial first moment r_mean,F(z)', ...
        'y_label', 'r_mean,F [um]', 'save_stem', 'rmean_fluence_vs_z'), ...
    struct('trace_um', 1e6 * D.store_peak_x, 'title_text', 'Peak total-fluence location x_peak(z)', ...
        'y_label', 'x_peak [um]', 'save_stem', 'peak_x_vs_z'), ...
    struct('trace_um', 1e6 * D.store_peak_y, 'title_text', 'Peak total-fluence location y_peak(z)', ...
        'y_label', 'y_peak [um]', 'save_stem', 'peak_y_vs_z'), ...
    struct('trace_um', 1e6 * D.store_peak_r, 'title_text', 'Peak total-fluence radial distance r_peak(z)', ...
        'y_label', 'r_peak [um]', 'save_stem', 'peak_r_vs_z') ...
};
for location_trace_idx = 1:numel(location_trace_specs)
    location_trace_spec = location_trace_specs{location_trace_idx};
    [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, [], location_trace_spec.trace_um, [], ...
        location_trace_spec.title_text, ...
        'z [m]', location_trace_spec.y_label, ...
        location_trace_spec.save_stem, ...
        plot_session, ...
        'run_warn_state', run_warn_state);
end

%-------------------------------------------------------------------------
%-------------------------------------------------------------------------
%Chromatic z-location diagnostics: wavelength-binned first-decrease onset proxies
%Uses the stored area-integrated spectrum plus one reduced max-over-(x,y)
%spectral z-stack. Falls back to the stored 4D cube only when that
%reduced hotspot spectral history is unavailable.
%-------------------------------------------------------------------------
if ~isempty(D.store_spectrum) && ...
        (have_store_spectral_max_xy || ~isempty(D.store_spectral_intens))

    %Axes
    z_axis             = D.store_z(:);         %[num_storage_steps 1], in meters
    lambda_axis_m      = lambda_window(:);   %[n_lambda 1], in meters
    lambda_axis_nm     = lambda_axis_m * 1e9;
    % Use the globally-defined uniform FFT spacing from setup: 2*pi/(n*delta_t).

    delta_omega_bin = double(grid_state.delta_omega);
    if ~(isfinite(delta_omega_bin) && (delta_omega_bin > 0))
        error('CerUPP:InvalidDeltaOmega', ...
            'delta_omega must be finite and > 0 before chromatic diagnostics.');
    end

    num_z_store        = numel(z_axis);

    %---------------------------------------------------------------------
    %Choose wavelength band to analyze before reducing over x-y so the
    %chromatic-onset path scales with the visible subset, not the full grid.
    %---------------------------------------------------------------------
    if ~postprocess_band_support.has_chromatic_contract
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plot_chromatic_focus_band_contract_missing', ...
            'CerUPP:Plot:ChromaticBandContractMissing', ...
            ['Skipping chromatic z-location diagnostics: Section 6A is missing one or more required band-definition fields (%s).'], ...
            strjoin(postprocess_band_support.chromatic_missing_fields, ', '));
    else
        mask_visible_chromatic_band = ...
            (lambda_axis_nm >= lambda_visible_band_min) & ...
            (lambda_axis_nm <= lambda_visible_band_max);
        band_lambda_idx     = find(mask_visible_chromatic_band);
        num_band_lambda     = numel(band_lambda_idx);
        if num_band_lambda <= 0
            lambda_nm_min = NaN;
            lambda_nm_max = NaN;
            if ~isempty(lambda_axis_nm)
                lambda_nm_min = min(lambda_axis_nm);
                lambda_nm_max = max(lambda_axis_nm);
            end
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_chromatic_focus_visible_band_empty', ...
                'CerUPP:Plot:ChromaticFocusVisibleBandEmpty', ...
                ['Skipping chromatic z-location diagnostics: no wavelengths overlap the visible band [%.0f, %.0f] nm. ' ...
                 'lambda_window range is [%.3f, %.3f] nm.'], ...
                lambda_visible_band_min, lambda_visible_band_max, ...
                lambda_nm_min, lambda_nm_max);
        else
        lambda_axis_nm = lambda_axis_nm(band_lambda_idx);

        %Chromatic maps on the visible subset only:
        %spectral_sum_xy(z,omega) = area-integrated stored output spectrum on the omega grid
        %spectral_max_xy(z,omega) = max_{x,y} H_spectral(x,y,omega;z)
        spectral_sum_xy = D.store_spectrum(:, band_lambda_idx) / (2*pi);
        if have_store_spectral_max_xy
            spectral_max_xy = real(D.store_spectral_max_xy(:, band_lambda_idx));
        else
            spectral_max_xy = squeeze(max(max(D.store_spectral_intens(:, :, band_lambda_idx, :), [], 1), [], 2)).';
        end

        %-----------------------------------------------------------------
        %Wavelength-binned chromatic onset-proxy z-location:
        %Proxy is the first z where the binned trace starts decreasing.
        %This binning is diagnostic-only: it does not change propagation,
        %solver spectral resolution, or the visible/RGB filter bandwidths.
        %It is used here only for the chromatic first-decrease proxy plots
        %  chromatic_focus_visible_firstdecrease_*   (integrated-energy proxy)
        %  chromatic_hotspot_visible_firstdecrease_*
        %Implemented by filament_diagnostics_utils.detect_onset_trace(...,'first_decrease_after_threshold',...),
        %which preserves amplitude-threshold semantics in det.threshold.
        %-----------------------------------------------------------------
        lambda_bin_width_nm = double(chromatic_onset_bin_width);
        if ~(isscalar(lambda_bin_width_nm) && isfinite(lambda_bin_width_nm) && (lambda_bin_width_nm > 0))
            error('CerUPP:Plot:ChromaticInvalidBinWidth', ...
                ['chromatic_onset_bin_width must be a scalar finite numeric value > 0 ' ...
                 'for chromatic onset diagnostics (got %s).'], ...
                runtime_control_value_repr_local(chromatic_onset_bin_width));
        end
        lambda_bin_min_nm = lambda_visible_band_min;
        lambda_bin_max_nm = lambda_visible_band_max;

        edges_nm = lambda_bin_min_nm:lambda_bin_width_nm:lambda_bin_max_nm;
        n_bins = numel(edges_nm) - 1;
        bin_center_nm = edges_nm(1:end-1) + 0.5 * lambda_bin_width_nm;
        bin_width_tag = strrep(sprintf('%g', lambda_bin_width_nm), '.', 'p');
        chromatic_file_tag = [bin_width_tag 'nm'];

        z_firstdec_sum_xy = NaN(n_bins, 1);
        z_firstdec_max_xy = NaN(n_bins, 1);
        chromatic_sum_cleaned_bins = 0;
        chromatic_sum_partially_salvaged_bins = 0;
        chromatic_sum_fully_invalid_bins = 0;

        w = 5;
        if num_z_store >= 21
            w = 9;
        elseif num_z_store >= 11
            w = 7;
        end

        for b = 1:n_bins
            lo = edges_nm(b);
            hi = edges_nm(b+1);
            if b == n_bins
                in_bin = (lambda_axis_nm >= lo) & (lambda_axis_nm <= lambda_bin_max_nm);
            else
                in_bin = (lambda_axis_nm >= lo) & (lambda_axis_nm < hi);
            end
            idxs = find(in_bin);
            if isempty(idxs)
                continue;
            end

            tmp_sum = spectral_sum_xy(:, idxs);
            bad_sum = ~isfinite(tmp_sum);
            tmp_sum(bad_sum) = NaN;
            neg_sum = isfinite(tmp_sum) & (tmp_sum < 0);
            tmp_sum(neg_sum) = 0;
            finite_sum_support = any(isfinite(tmp_sum), 2);
            trace_sum = sum(tmp_sum, 2, 'omitnan') * delta_omega_bin;
            trace_sum(~finite_sum_support) = NaN;
            if any(bad_sum(:) | neg_sum(:))
                chromatic_sum_cleaned_bins = chromatic_sum_cleaned_bins + 1;
                if any(finite_sum_support)
                    chromatic_sum_partially_salvaged_bins = chromatic_sum_partially_salvaged_bins + 1;
                end
                if any(~finite_sum_support)
                    chromatic_sum_fully_invalid_bins = chromatic_sum_fully_invalid_bins + 1;
                end
            end

            tmp_hot = spectral_max_xy(:, idxs);
            tmp_hot(~isfinite(tmp_hot)) = NaN;
            neg_hot = isfinite(tmp_hot) & (tmp_hot < 0);
            if any(neg_hot(:))
                neg_count = nnz(neg_hot);
                min_neg = min(tmp_hot(neg_hot));
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    'plot_chromatic_hotspot_negative_clamped', ...
                    'CerUPP:Plot:ChromaticHotspotNegativeClamped', ...
                    ['Chromatic hotspot trace has negative spectral fluence-density samples ' ...
                     'in bin [%.0f, %.0f) nm (count=%d, min=%g); clamping to 0 before onset detection.'], ...
                    lo, hi, neg_count, min_neg);
            end
            tmp_hot = max(tmp_hot, 0);
            trace_hot = max(tmp_hot, [], 2, 'omitnan');

            [det_sum, run_warn_state] = filament_diagnostics_utils.detect_onset_trace( ...
                trace_sum, z_axis, 'first_decrease_after_threshold', ...
                0, 1, sprintf('chromatic_sum_firstdec_[%.0f,%.0f)nm_w%s', lo, hi, chromatic_file_tag), w, run_warn_state);
            [det_hot, run_warn_state] = filament_diagnostics_utils.detect_onset_trace( ...
                trace_hot, z_axis, 'first_decrease_after_threshold', ...
                0, 1, sprintf('chromatic_hot_firstdec_[%.0f,%.0f)nm_w%s', lo, hi, chromatic_file_tag), w, run_warn_state);

            z_firstdec_sum_xy(b) = det_sum.z_onset;
            z_firstdec_max_xy(b) = det_hot.z_onset;
        end

        if chromatic_sum_cleaned_bins > 0
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_chromatic_sum_invalid_samples_cleaned', ...
                'CerUPP:Plot:ChromaticEnergyProxyInvalidSamplesCleaned', ...
                ['Chromatic integrated-energy onset proxy encountered degraded visible-band spectral bins; ' ...
                 'using finite-only, nonnegative wavelength-bin sums before onset detection. ' ...
                 'Affected bins=%d, partially salvaged bins=%d, bins with at least one fully invalid z row=%d.'], ...
                chromatic_sum_cleaned_bins, chromatic_sum_partially_salvaged_bins, ...
                chromatic_sum_fully_invalid_bins);
        end

        ok_sum = isfinite(z_firstdec_sum_xy);
        ok_hot = isfinite(z_firstdec_max_xy);

        chromatic_plot_specs = struct( ...
            'ok_mask', {ok_sum, ok_hot}, ...
            'z_plot_mm', {1e3 * z_firstdec_sum_xy, 1e3 * z_firstdec_max_xy}, ...
            'session_stem', { ...
                ['chromatic_focus_visible_firstdecrease_' chromatic_file_tag], ...
                ['chromatic_hotspot_visible_firstdecrease_' chromatic_file_tag]}, ...
            'title_text', { ...
                [sprintf('Visible-band chromatic onset-proxy z (%g nm bins, %.0f-%.0f nm): proxy = first decrease of ', ...
                    lambda_bin_width_nm, lambda_visible_band_min, lambda_visible_band_max) ...
                 'binned spectral energy (integrated over x,y and omega)'], ...
                [sprintf('Visible-band chromatic hotspot onset-proxy z (%g nm bins, %.0f-%.0f nm): proxy = first decrease of ', ...
                    lambda_bin_width_nm, lambda_visible_band_min, lambda_visible_band_max) ...
                 'max over x,y of spectral fluence density (per-omega sample)']}, ...
            'y_label', { ...
                'First-decrease onset-proxy z [mm]', ...
                'Hotspot first-decrease onset-proxy z [mm]'}, ...
            'render_warn_key', { ...
                'plot_chromatic_focus_sum_firstdecrease_render_failed', ...
                'plot_chromatic_focus_hot_firstdecrease_render_failed'}, ...
            'render_warn_id', { ...
                'CerUPP:Plot:ChromaticFocusSumFirstDecreaseRenderFailed', ...
                'CerUPP:Plot:ChromaticFocusHotFirstDecreaseRenderFailed'}, ...
            'render_warn_msg', { ...
                'Chromatic integrated first-decrease plot generation reported failure; skipping file export.', ...
                'Chromatic hotspot first-decrease plot generation reported failure; skipping file export.'}, ...
            'empty_warn_key', { ...
                'plot_chromatic_focus_sum_firstdecrease_empty', ...
                'plot_chromatic_focus_hot_firstdecrease_empty'}, ...
            'empty_warn_id', { ...
                'CerUPP:Plot:ChromaticFocusSumFirstDecreaseEmpty', ...
                'CerUPP:Plot:ChromaticFocusHotFirstDecreaseEmpty'}, ...
            'empty_warn_msg', { ...
                'No valid %.3g nm bins produced a first-decrease location for the integrated metric; plot skipped.', ...
                'No valid %.3g nm bins produced a first-decrease location for the hotspot metric; plot skipped.'});

        for chromatic_plot_idx = 1:numel(chromatic_plot_specs)
            chromatic_spec = chromatic_plot_specs(chromatic_plot_idx);
            if any(chromatic_spec.ok_mask)
                [~, chromatic_session, run_warn_state, ok_chromatic_session] = ...
                    plot_support_utils.begin_figure_session( ...
                        plot_session.outdir, chromatic_spec.session_stem, ...
                        run_warn_state, plot_session);
                chromatic_plot_settings = plot_session;
                chromatic_plot_settings.outdir = plot_session.outdir;
                chromatic_plot_settings.save_outputs_as_fig = false;
                chromatic_plot_settings.save_outputs_as_png = false;
                chromatic_plot_settings.close_figure = false;
                fig_before = get(groot, 'CurrentFigure');
                [ok_chromatic_plot, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                    bin_center_nm(chromatic_spec.ok_mask), [], ...
                    chromatic_spec.z_plot_mm(chromatic_spec.ok_mask), [], ...
                    chromatic_spec.title_text, ...
                    'Vacuum wavelength bin center [nm]', chromatic_spec.y_label, ...
                    chromatic_spec.session_stem, chromatic_plot_settings, ...
                    'Marker','o','LineStyle','-', 'run_warn_state', run_warn_state);
                fig_after = get(groot, 'CurrentFigure');
                if isgraphics(fig_after) && (isempty(fig_before) || ~isequal(fig_after, fig_before))
                    ax_after = get(fig_after, 'CurrentAxes');
                    if ok_chromatic_plot && ok_chromatic_session
                        if ~isempty(ax_after) && isgraphics(ax_after)
                            grid(ax_after, 'on');
                        end
                        run_warn_state = plot_support_utils.finalize_figure_session( ...
                            fig_after, chromatic_session, run_warn_state);
                    else
                        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                            run_warn_state, 'end', ...
                            chromatic_spec.render_warn_key, ...
                            chromatic_spec.render_warn_id, ...
                            chromatic_spec.render_warn_msg);
                    end
                    plot_support_utils.close_figure_if_valid(fig_after);
                end
            else
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    chromatic_spec.empty_warn_key, ...
                    chromatic_spec.empty_warn_id, ...
                    chromatic_spec.empty_warn_msg, ...
                    lambda_bin_width_nm);
            end
        end
        end
    end
elseif need_store_reduced_spectral_histories
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'plot_chromatic_focus_spectral_cube_missing', ...
        'CerUPP:Plot:ChromaticFocusSpectralCubeMissing', ...
        'Skipping chromatic z-location diagnostics: reduced spectral z traces are missing.');
end


%--- Visible-band fluence CLIPPED display companion [dev] -----------------
% Dev-only clipped display for the same y~0 visible-fluence slice.
%dev_visible_fluence_linear_clipped.png / .fig
%Anything below vis_bw_lo -> black; anything above vis_bw_hi -> white.
%In-between uses a smooth colormap gradient.
if emit_dev_only_plots && ~isempty(x_cut)
    vis_bw_lo = 0.1; % [J/m^2]
    vis_bw_hi = 3;   % [J/m^2]

    f_bw = real(store_fluence_xy_visible_r);
    opts_nf_bw = struct( ...
        'warn', true, ...
        'warn_id', 'CerUPP:Plot:NonFiniteCapped', ...
        'cap_value', diag_cap_hi, ...
        'treat_nan_as_blowup', false, ...
        'replace_nonfinite_with_nan', true, ...
        'naninfo', naninfo, ...
        'run_warn_state', run_warn_state, ...
        'phase_tag', 'end');
    [f_bw, naninfo, ~, run_warn_state] = plot_utils.sanitize_nonfinite_diag( ...
        f_bw, 'F_bw (visible fluence clipped plot)', opts_nf_bw);

    %clip data so out-of-range values map to the colormap endpoints
    f_bw = min(max(f_bw, vis_bw_lo), vis_bw_hi);

    %build colormap with BLACK at low end and WHITE at high end
    n_2 = 256;
    cmap_bw = parula(n_2);
    cmap_bw(1,:)   = [0 0 0];
    cmap_bw(end,:) = [1 1 1];

    fig_vis_clip = [];
    try
        dev_visible_plot_settings = plot_session;
        dev_visible_plot_settings.save_outputs_as_fig = false;
        dev_visible_plot_settings.save_outputs_as_png = false;
        dev_visible_plot_settings.close_figure = false;
        [ok_plot, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z, x_cut, f_bw, [], ...
            sprintf('Visible-band fluence display companion [dev]: F_vis(x at y~0, z) [J/m^2] (clipped to [%g,%g])', vis_bw_lo, vis_bw_hi), ...
            'z [m]', 'x (y~0 cut) [m]', 'dev_visible_fluence_linear_clipped', ...
            dev_visible_plot_settings, 'run_warn_state', run_warn_state);
        if ok_plot
            colormap(cmap_bw);
            caxis([vis_bw_lo vis_bw_hi]);
            cb = colorbar;
            ylabel(cb, 'Visible-band fluence [J/m^2]');
            fig_vis_clip = get(groot, 'CurrentFigure');
        else
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_visible_fluence_make_plot_failed', ...
                'CerUPP:Plot:MakePlotFailed', ...
                'make_plot returned ok=false for dev_visible_fluence_linear_clipped; skipping this plot.');
        end
    catch me_2
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plot_visible_fluence_make_plot_failed', ...
            'CerUPP:Plot:MakePlotFailed', ...
            'make_plot(...) failed for dev_visible_fluence_linear_clipped (%s): %s. Skipping this plot.', ...
            me_2.identifier, me_2.message);
    end

    if ~isempty(fig_vis_clip) && isgraphics(fig_vis_clip)
        [~, visible_clip_session, run_warn_state, ok_visible_clip_session] = ...
            plot_support_utils.begin_figure_session( ...
                plot_session.outdir, 'dev_visible_fluence_linear_clipped', ...
                run_warn_state, plot_session);
        if ok_visible_clip_session
            run_warn_state = plot_support_utils.finalize_figure_session( ...
                fig_vis_clip, visible_clip_session, run_warn_state);
        end
    end
end



%======================================================================
% On-axis spectrum diagnostics (dB, normalized to peak = 0 dB):
% - at detected-onset z (auto-detected from rising-branch slope metric)
% - at final z

%z_DETECTED_ONSET is auto-detected with NO predefined thresholds:
%Uses the maximum slope of a smoothed trace (moving-average window w)
%on the rising branch up to the smoothed peak, preferring:
%(1) rho_MAXPERP(z) = max_{x,y} max_t rho
%(2) Fvis_MAXPERP(z)= max_{x,y} F_vis(x,y;z)
%(3) rho_ONAXIS(z) = max_t rho(x~0,y~0;z)
%(4) Fvis_ONAXIS(z) = F_vis(x~0,y~0;z)
%If none exist, falls back to first stored plane.

% IMPORTANT: Runs only when reduced point-spectrum z traces exist (or the
% full stored 4D spectral cube is available), plus lambda_window/store_z and the
% shared plotting helpers.
%======================================================================
f_angle_estimate = [];
has_plot_utils = (exist('plot_utils','file') == 2);
if (have_store_spectral_line_oa || ~isempty(D.store_spectral_intens)) && ...
   has_plot_utils

    % Plot window for near-IR point-spectrum diagnostics [nm].
    % Keep this family fixed-window; the separate *_spectrum_fullrange_* family
    % owns full-range plotting.
    lam_lo_nm = 800;
    lam_hi_nm = 1200;
    lam_min = min(spectral_lambda_ctx.lambda_nm_sorted);
    lam_max = max(spectral_lambda_ctx.lambda_nm_sorted);
    lam_lo_eff = max(lam_lo_nm, lam_min);
    lam_hi_eff = min(lam_hi_nm, lam_max);
    if lam_lo_eff <= lam_hi_eff
        mask_plot = (spectral_lambda_ctx.lambda_nm_sorted >= lam_lo_eff) & ...
            (spectral_lambda_ctx.lambda_nm_sorted <= lam_hi_eff);
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plot_oa_spectrum_window_empty', ...
            'CerUPP:Plot:OaSpectrumWindowEmpty', ...
            ['On-axis spectrum plot window [%.0f, %.0f] nm does not intersect available range [%.1f, %.1f] nm. ' ...
            'Skipping the near-IR point-spectrum family; full-range point spectra are emitted separately.'], ...
            lam_lo_nm, lam_hi_nm, lam_min, lam_max);
        mask_plot = false(size(spectral_lambda_ctx.lambda_nm_sorted));
    end

    nearir_family_cfg = point_spectrum_family_base_cfg;
    nearir_family_cfg.mask_plot = mask_plot;
    nearir_family_cfg.lambda_nm_plot = spectral_lambda_ctx.lambda_nm_sorted(mask_plot);
    nearir_family_cfg.oa_curve_label_fmt = 'On-axis point spectrum (%s)';
    nearir_family_cfg.oa_scale_warn_key_fmt = 'plot_nonfinite_scale_s_plot_%d';
    nearir_family_cfg.oa_scale_warn_message = 'Smax invalid/empty in S_plot; using 1';
    nearir_family_cfg.oa_plot_title_fmt = sprintf([ ...
        'On-axis stored near-field relative point spectral fluence density dF/dlambda ', ...
        '[%%s, %.0f-%.0f nm] (peak-normalized; 0 dB at curve max)'], ...
        lam_lo_eff, lam_hi_eff);
    nearir_family_cfg.oa_dev_plot_title_fmt = sprintf([ ...
        'On-axis stored near-field relative point spectral fluence density dF/dlambda ', ...
        '[%%s, %.0f-%.0f nm] (peak-normalized; peak approx -40 dB) [dev]'], ...
        lam_lo_eff, lam_hi_eff);
    nearir_family_cfg.oa_save_stem = 'oa_point_spectrum';
    nearir_family_cfg.bc_curve_label_fmt = ...
        'Fundamental-band beam-center point spectrum (%s)';
    nearir_family_cfg.bc_plot_title_fmt = sprintf([ ...
        'Fundamental-band beam-center stored near-field relative point spectral fluence density dF/dlambda ', ...
        '[%%s, %.0f-%.0f nm] (peak-normalized; 0 dB at curve max)'], ...
        lam_lo_eff, lam_hi_eff);
    nearir_family_cfg.bc_dev_plot_title_fmt = sprintf([ ...
        'Fundamental-band beam-center stored near-field relative point spectral fluence density dF/dlambda ', ...
        '[%%s, %.0f-%.0f nm] (peak-normalized; peak approx -40 dB) [dev]'], ...
        lam_lo_eff, lam_hi_eff);
    nearir_family_cfg.bc_save_stem = 'beamcenter_point_spectrum';
    nearir_family_cfg.store_spectral_line_bc_field = ...
        'store_spectral_line_bc_fund';
    nearir_family_cfg.beam_center_offaxis_any = beam_center_fund_offaxis_any;
    nearir_family_cfg.store_beamcenter_ix = store_beamcenter_ix_fund;
    nearir_family_cfg.store_beamcenter_iy = store_beamcenter_iy_fund;
    nearir_family_cfg.beamcenter_spectral_plane_count = ...
        beamcenter_fund_spectral_plane_count;
    nearir_family_cfg.emit_onset_failure_warn = true;
    nearir_family_cfg.onset_failure_warn_key = 'plot_onset_detect_failed';
    nearir_family_cfg.onset_failure_warn_id = ...
        'CerUPP:Diagnostics:OnsetDetectFailed';
    nearir_family_cfg.onset_failure_warn_message = [ ...
        'Onset detection failed for all onset indicators (rho_MAXPERP, ', ...
        'Fvis_MAXPERP, rho_ONAXIS, Fvis_ONAXIS). Skipping onset-labeled slice generation ', ...
        'and emitting only z_final-tag diagnostics.'];
    nearir_family_cfg.use_first_valid_onset_note = true;
    nearir_family_cfg.warn_on_empty_lambda_per_tag = true;
    nearir_family_cfg.empty_lambda_warn_key_fmt = ...
        'nearir_oa_point_spectrum_lambda_window_empty_%s';
    nearir_family_cfg.empty_lambda_warn_id = ...
        'CerUPP:Plot:NearIROAPointSpectrumLambdaWindowEmpty';
    nearir_family_cfg.empty_lambda_warn_message = ...
        'Skipping on-axis near-IR point spectrum for %s: the selected wavelength window is empty.';
    nearir_family_cfg.warn_on_missing_oa_line = true;
    nearir_family_cfg.missing_oa_line_warn_key_fmt = ...
        'nearir_oa_point_spectrum_line_missing_%s';
    nearir_family_cfg.missing_oa_line_warn_id = ...
        'CerUPP:Plot:NearIROAPointSpectrumMissing';
    nearir_family_cfg.missing_oa_line_warn_message = [ ...
        'Skipping on-axis near-IR point spectrum for %s: no stored on-axis spectral line ', ...
        'was available at the selected stored plane.'];
    [shared_detected_onset_state, naninfo, run_warn_state, family_emit_state] = ...
        emit_point_spectrum_family_local( ...
            nearir_family_cfg, point_spectrum_ctx, ...
            shared_detected_onset_state, naninfo, run_warn_state);
elseif (have_store_spectral_line_oa || ~isempty(D.store_spectral_intens)) && ~has_plot_utils
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'plot_oa_spectrum_plot_utils_missing', ...
        'CerUPP:Plot:OnAxisSpectrumPlotUtilsMissing', ...
        ['On-axis spectrum diagnostics skipped: plot_utils.m was not found on the MATLAB path. ', ...
         'Add plot_utils.m to path or run from the project root.']);
end
if (double(family_emit_state.emitted_tag_count) < ...
        double(family_emit_state.requested_tag_count)) || ...
        (double(family_emit_state.emitted_tag_count) == 0)
    family_ledger = mark_postprocess_family_skipped_local( ...
        family_ledger, 'spectral_followup', ...
        'requested_point_spectrum_tags_not_emitted', ...
        build_point_spectrum_family_skip_message_local( ...
            family_emit_state.emitted_tag_count, ...
            family_emit_state.requested_tag_count));
else
    family_ledger = mark_postprocess_family_ok_local( ...
        family_ledger, 'spectral_followup');
end
catch me_family_spectral
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'spectral_followup', me_family_spectral);
    requested_outputs_complete = false;
    if isempty(requested_outputs_skipped_reason)
        requested_outputs_skipped_reason = 'postprocess_family_failure';
    end
    run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, 'spectral_followup', me_family_spectral);
end


%======================================================================
% y-integrated visible-band fluence (z-x image; log scale)
%======================================================================
side_view_visible_emitted = false;
try
    side_vis_xz = [];
    nz_plot = 0;
    if ~isempty(D.store_side_vis_xz) && ~isempty(D.store_z) && ~isempty(x)
        nz_plot = min(numel(D.store_z), size(D.store_side_vis_xz,2));
        if nz_plot >= 1
            side_vis_xz = D.store_side_vis_xz(:,1:nz_plot);
        end
    elseif ~isempty(D.store_fluence_xy_visible) && ~isempty(D.store_z) && ~isempty(x) && ~isempty(y)
        nz_plot = min(numel(D.store_z), size(D.store_fluence_xy_visible, 3));
        if nz_plot >= 1
            side_vis_xz = squeeze(trapz(y, D.store_fluence_xy_visible(:, :, 1:nz_plot), 2));
            if isvector(side_vis_xz)
                side_vis_xz = reshape(side_vis_xz, numel(x), nz_plot);
            end
        end
    end

    if ~isempty(side_vis_xz)
        if nz_plot >= 1
            [side_vis_xz_log, ~, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
                side_vis_xz, eps_safe, 'store_side_vis_xz (y-integrated visible-band fluence)', run_warn_state, 'end');
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(D.store_z(1:nz_plot), x, side_vis_xz_log, [], ...
                'Side-view visible-band y-integrated fluence: log10(int dy F_vis) [J/m]', ...
                'z [m]', 'x [m]', 'side_view_visible_xz_log', ...
                plot_session, ...
                'cbar_label', 'log10(int dy F_{vis}) [J/m]', ...
                'skip_nonfinite_scan', true, 'run_warn_state', run_warn_state);
            side_view_visible_emitted = true;
        else
            run_warn_state = run_warn_state_utils.emit_softwarn_each_time_with_phase( ...
                run_warn_state, 'end', 'CerUPP:Plot:SideViewVisibleEmissionPlotSkipped', ...
                'y-integrated visible-band fluence plot skipped: Nz_plot < 1.');
            family_ledger = mark_postprocess_family_skipped_local( ...
                family_ledger, 'side_view_visible_fluence', ...
                'nz_plot_empty', ...
                'y-integrated visible-band fluence plot skipped: Nz_plot < 1.');
        end
    else
        run_warn_state = run_warn_state_utils.emit_softwarn_each_time_with_phase( ...
            run_warn_state, 'end', 'CerUPP:Plot:SideViewVisibleEmissionPlotSkipped', ...
            'y-integrated visible-band fluence plot skipped: missing usable visible-fluence z-storage/store_z/x/y.');
        family_ledger = mark_postprocess_family_skipped_local( ...
            family_ledger, 'side_view_visible_fluence', ...
            'missing_visible_storage', ...
            ['y-integrated visible-band fluence plot skipped: missing usable ', ...
             'visible-fluence z-storage/store_z/x/y.']);
    end
    if side_view_visible_emitted
        family_ledger = mark_postprocess_family_ok_local( ...
            family_ledger, 'side_view_visible_fluence');
    end
catch me_2
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'side_view_visible_fluence', me_2);
    run_warn_state = run_warn_state_utils.emit_softwarn_each_time_with_phase( ...
        run_warn_state, 'end', 'CerUPP:Plot:SideViewVisibleEmissionPlotFailed', ...
        'y-integrated visible-band fluence plot failed: %s', me_2.message);
end

%======================================================================
%Angle-resolved reference-medium Jacobian-weighted estimate (final plane, ky=0 cut)
%======================================================================
try
    if ...
       ~isempty(A_F)

        %Choose a stored plane (final):
        af = A_F;  %final plane only

        %Take a ky = 0 cut as one reference-medium diagnostic slice
        % through the angle estimate.
        %Use nearest ky=0 index when ky-grid is available.
        if ~isempty(ky)
            [~, iy0] = min(abs(ky));
        else
            % FFT-order arrays (ifftshift): ky=0 is at index 1.

            iy0 = 1;
        end
        af_kx_w = squeeze(af(:, iy0, :));        %[nx x n]
        i_kx_w  = real(af_kx_w .* conj(af_kx_w));

        lambda_m_all = lambda_window(:);                              %[n x 1]
        valid_lam = isfinite(lambda_m_all) & (lambda_m_all > 0);
        if ~any(valid_lam)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'angle_resolved_estimate_no_valid_lambda_bins', ...
                'CerUPP:Plot:AngleResolvedEstimateNoValidLambdaBins', ...
                ['Angle-resolved spectrum estimate skipped: no finite positive lambda bins ', ...
                 'available for omega-to-lambda axis mapping.']);
        else
            valid_lam_idx = find(valid_lam);
            lambda_m_valid = lambda_m_all(valid_lam_idx);              %[n_valid x 1]
            lambda_nm_valid = lambda_m_valid * 1e9;                    %[n_valid x 1]
            [lambda_nm_sorted, idx_lam] = sort(lambda_nm_valid, 'ascend');

            max_theta_rows = 512; % bound estimate-plot work on large kx grids
            if numel(kx) > max_theta_rows
                idx_kx_plot = unique(round(linspace(1, numel(kx), max_theta_rows)));
            else
                idx_kx_plot = 1:numel(kx);
            end
            kx_plot = kx(idx_kx_plot);
            i_kx_w = i_kx_w(idx_kx_plot, :);

            max_lambda_cols = 400; % plotting cap to keep interpolation cost bounded
            if numel(lambda_nm_sorted) > max_lambda_cols
                idx_plot = unique(round(linspace(1, numel(lambda_nm_sorted), max_lambda_cols)));
            else
                idx_plot = 1:numel(lambda_nm_sorted);
            end
            idx_valid_sorted_plot = idx_lam(idx_plot);
            omega_plot_idx = valid_lam_idx(idx_valid_sorted_plot);
            lambda_nm_plot = reshape(lambda_nm_sorted(idx_plot), 1, []);
            lambda_m_plot = reshape(lambda_m_valid(idx_valid_sorted_plot), 1, []);

            % Compute the angle/Jacobian estimate only for plotted wavelength bins.
            k_w_all = (medium_state.n_sell(:) .* grid_state.omega_window(:) / c).';            %[1 x n]
            k_w = reshape(k_w_all(omega_plot_idx), 1, []);             %[1 x n_plot]
            invalid_k_w = ~isfinite(k_w) | (abs(k_w) < eps_safe);
            if any(invalid_k_w)
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    'angle_resolved_estimate_invalid_k', ...
                    'CerUPP:Plot:AngleResolvedEstimateInvalidK', ...
                    ['Angle-resolved spectrum estimate: %d/%d selected wavelength bins have ', ...
                    'non-finite or near-zero k(omega); marking theta as NaN for those bins.'], ...
                    nnz(invalid_k_w), numel(k_w));
                k_w(invalid_k_w) = NaN;
            end

            % Keep one shared sorted kx support, then build the theta and
            % Jacobian factors column by column so the estimate does not
            % materialize full [kx x lambda] geometry tables before the
            % per-lambda interpolation step.
            i_plot = i_kx_w(:, omega_plot_idx);                        %[n_kx_plot x n_plot]
            kx_plot_sorted = kx_plot(:);
            if ~issorted(kx_plot_sorted)
                [kx_plot_sorted, idx_kx_sort] = sort(kx_plot_sorted, 'ascend');
                i_plot = i_plot(idx_kx_sort, :);
            end

            % Convert the per-omega density estimate to per-nm on the
            % plotted lambda axis. S(omega) domega = S(lambda_nm) dlambda_nm,
            % so |domega/dlambda_nm| = (2*pi*c/lambda^2)*1e-9.
            jac_w_to_lambda = (2*pi*c ./ (lambda_m_plot.^2)) * 1e-9;     %[1 x n_lambda_plot], [(rad/s)/nm]

            theta_min = NaN;
            theta_max = NaN;
            for ilam = 1:numel(k_w)
                if ~isfinite(k_w(ilam))
                    continue;
                end
                support_mask = abs(kx_plot_sorted) <= abs(k_w(ilam));
                if ~any(support_mask)
                    continue;
                end
                kx_support = kx_plot_sorted(support_mask);
                theta_lo = asin(max(min(kx_support(1) / k_w(ilam), 1), -1));
                theta_hi = asin(max(min(kx_support(end) / k_w(ilam), 1), -1));
                if ~isfinite(theta_min) || (theta_lo < theta_min)
                    theta_min = theta_lo;
                end
                if ~isfinite(theta_max) || (theta_hi > theta_max)
                    theta_max = theta_hi;
                end
            end
            if ~(isfinite(theta_min) && isfinite(theta_max))
                theta_min = -pi/2 + 1e-6;
                theta_max =  pi/2 - 1e-6;
            end
            if ~(isfinite(theta_min) && isfinite(theta_max) && (theta_max > theta_min))
                theta_min = -pi/2 + 1e-6;
                theta_max =  pi/2 - 1e-6;
            end

            n_theta = numel(kx_plot_sorted);
            theta_grid = linspace(theta_min, theta_max, n_theta).';      %[n_theta x 1]
            sin_theta_grid = sin(theta_grid);                            %[n_theta x 1]
            i_theta_lambda = NaN(n_theta, numel(lambda_nm_plot));      %[n_theta x n_lambda_plot]
            if ~isempty(lambda_nm_plot)
                invalid_ratio_count = 0;
                invalid_i_plot_count = 0;
                n_lambda_plot = numel(lambda_nm_plot);
                for ilam = 1:n_lambda_plot
                    if ~isfinite(k_w(ilam))
                        continue;
                    end
                    i_col = i_plot(:, ilam);
                    ratio_col = kx_plot_sorted / k_w(ilam);
                    valid_ratio = isfinite(ratio_col) & (abs(ratio_col) <= 1);
                    invalid_ratio_count = invalid_ratio_count + nnz(~valid_ratio);
                    if nnz(valid_ratio) < 2
                        continue;
                    end
                    theta_col = asin(ratio_col(valid_ratio));
                    jacobian_kx_to_theta_deg = abs(cos(theta_col) .* k_w(ilam)) * (pi/180);
                    i_col_weighted = NaN(size(i_col));
                    i_col_weighted(valid_ratio) = ...
                        i_col(valid_ratio) .* jacobian_kx_to_theta_deg .* jac_w_to_lambda(ilam);
                    invalid_i_col = ~isfinite(i_col_weighted);
                    invalid_i_plot_count = invalid_i_plot_count + nnz(invalid_i_col & valid_ratio);
                    i_col_weighted(invalid_i_col) = NaN;
                    valid_col = isfinite(i_col_weighted);
                    if nnz(valid_col) < 2
                        continue;
                    end
                    kx_query = k_w(ilam) * sin_theta_grid;
                    i_theta_lambda(:, ilam) = interp1( ...
                        kx_plot_sorted(valid_col), i_col_weighted(valid_col), ...
                        kx_query, 'linear', NaN);
                end
                if invalid_ratio_count > 0
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', ...
                        'angle_resolved_estimate_invalid_ratio', ...
                        'CerUPP:Plot:AngleResolvedEstimateInvalidRatio', ...
                        ['Angle-resolved spectrum estimate: %d theta samples had ', ...
                        '|kx/k(omega)| > 1 or non-finite values; marking as NaN.'], ...
                        invalid_ratio_count);
                end
                if invalid_i_plot_count > 0
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', ...
                        'angle_resolved_estimate_nonfinite_lambda_weighted', ...
                        'CerUPP:Plot:AngleResolvedEstimateNonFiniteLambdaWeighted', ...
                        ['Angle-resolved spectrum estimate: %d lambda-weighted samples became non-finite; ', ...
                         'marking them as NaN before interpolation.'], ...
                        invalid_i_plot_count);
                end
            end

            [f_angle_estimate, angle_plot_session, run_warn_state, ok_angle_plot_session] = ...
                plot_support_utils.begin_figure_session( ...
                    plot_session.outdir, 'angle_resolved_in_medium_jacobian_estimate_ky0_relative', ...
                    run_warn_state, plot_session, ...
                    'create_figure', true);
            if ok_angle_plot_session
                log_i_theta_lambda = log10(i_theta_lambda + eps_safe);
                surf(lambda_nm_plot, theta_grid*180/pi, log_i_theta_lambda, 'EdgeColor', 'none');
                shading(gca, get_plot_surface_shading_mode_local(plot_session));
                view(0,90);
                set(gca,'YDir','normal'); axis tight;
                xlabel('Vacuum wavelength [nm]');
                ylabel('Theta_ref_medium [deg]');
                title({sprintf(['Reference-medium angle-spectrum estimate (ky=0, relative units; ', ...
                        '%s; ', ...
                        'uses k(\\omega)=n_{sell}(\\omega)\\omega/c for the rod/reference path; ', ...
                        'not directly comparable to external far-field {theta,lambda}; ', ...
                        'plotted lambda bins=%d of %d)'], ...
                        display_floor_note, numel(lambda_nm_plot), numel(lambda_nm_sorted)), ...
                       ['Theta_ref_medium from asin(k_x/k(\omega)) with the reference ', ...
                        'n_{sell}(\omega) curve; relative estimate on the plotted ', ...
                        '\lambda axis after k_x\rightarrow\theta and ', ...
                        '\omega\rightarrow\lambda_{nm} Jacobian weighting']});
                cb_angle = colorbar;
                ylabel(cb_angle, ['log10(relative reference-medium estimate on plotted \lambda axis \propto |A_F|^2*|dk_x/d\theta|*|d\omega/d\lambda_{nm}|) [arb. units; ' display_floor_note ']']);

                run_warn_state = plot_support_utils.finalize_figure_session( ...
                    f_angle_estimate, angle_plot_session, run_warn_state);
                f_angle_estimate = [];
            end
        end
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'angle_resolved_estimate_skipped', ...
            'CerUPP:Plot:AngleResolvedEstimateSkipped', ...
            'Angle-resolved spectrum estimate skipped: missing A_F/n_Sell/omega_window/lambda_window/kx/c.');
    end
catch me_2
    plot_support_utils.close_figure_if_valid(f_angle_estimate);
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'angle_resolved_estimate_failed', ...
        'CerUPP:Plot:AngleResolvedEstimateFailed', ...
        'Angle-resolved spectrum estimate failed: %s', me_2.message);
end

%======================================================================
%Additional visible-fluence dev plot:
%0 -> black, 18 -> white, >18 -> red (constant red region).
%Outputs: files are saved with fixed names, and this driver archives any
%existing run_output_root at startup so prior-run outputs are preserved.
%dev_visible_fluence_threshold_18.(fig|png)
%======================================================================
f_vis_bwr = [];
try
    if emit_dev_only_plots && ...
       ~isempty(store_fluence_xy_visible_r) && ~isempty(D.store_z) && ~isempty(x_cut)

        lo  = 0;    % [J/m^2]
        mid = 18;  % [J/m^2] (visible-band dev threshold)
        f_2_raw = real(store_fluence_xy_visible_r);
        opts_nf_detect = struct( ...
            'warn', true, ...
            'warn_id', 'CerUPP:Diagnostics:VisibleFluenceBWRInvalidSamples', ...
            'cap_value', diag_cap_hi, ...
            'treat_nan_as_blowup', false, ...
            'count_only', true, ...
            'naninfo', naninfo, ...
            'run_warn_state', run_warn_state, ...
            'phase_tag', 'end');
        [~, naninfo, ~, run_warn_state] = plot_utils.sanitize_nonfinite_diag( ...
            f_2_raw, 'F (visible fluence black-white-red plot)', opts_nf_detect);

        finite_mask = isfinite(f_2_raw);
        neg_mask = finite_mask & (f_2_raw < 0);
        if any(neg_mask(:))
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'visible_fluence_bwr_negative_samples', ...
                'CerUPP:Plot:VisibleFluenceBWRNegative', ...
                ['Visible-fluence BWR plot: %d negative samples found; ' ...
                 'marking them as invalid.'], ...
                nnz(neg_mask));
        end
        valid_mask = finite_mask & ~neg_mask;
        f_valid = f_2_raw(valid_mask);
        data_max_true = NaN;
        if isempty(f_valid)
            hi = mid; % [J/m^2]
        else
            data_max_true = max(f_valid(:)); % [J/m^2]
            hi = data_max_true;
            if ~isfinite(hi) || hi < mid
                hi = mid; % [J/m^2], keep the dev threshold inside the color axis
            end
        end

        % Value-driven (not caxis-driven) threshold map:
        % F<=18 -> grayscale (0:black, 18:white), F>18 -> constant red.
        n_gray = 255;
        idx_red = n_gray + 1;
        idx_bad = n_gray + 2;
        c_idx = idx_bad * ones(size(f_2_raw));
        if any(valid_mask(:))
            f_valid_vals = f_2_raw(valid_mask);
            f_clip_valid = min(max(f_valid_vals, lo), mid);
            gray_level = (f_clip_valid - lo) ./ max(mid - lo, eps_safe);
            gray_level = min(max(gray_level, 0), 1);
            c_idx_valid = 1 + round(gray_level * (n_gray - 1)); % [1..nGray]
            c_idx_valid(f_valid_vals > mid) = idx_red;
            c_idx(valid_mask) = c_idx_valid;
        end
        cmap = [gray(n_gray); 1 0 0; 1 0 1];

        [f_vis_bwr, visible_threshold_session, run_warn_state, ok_visible_threshold_session] = ...
            plot_support_utils.begin_figure_session( ...
                plot_session.outdir, 'dev_visible_fluence_threshold_18', ...
                run_warn_state, plot_session, ...
                'create_figure', true);
        if ok_visible_threshold_session
            surf(D.store_z, x_cut, c_idx, 'EdgeColor', 'none');
            shading(gca, get_plot_surface_shading_mode_local(plot_session));
            view(0,90);
            set(gca,'YDir','normal'); axis tight;
            colormap(cmap);
            set(gca, 'CLim', [1 idx_bad]);

            cb = colorbar;
            ylabel(cb,'Visible-band dev threshold map (0, 18, >18 J/m^2, invalid)');
            cb.Ticks = [1, n_gray, idx_red, idx_bad];
            cb.TickLabels = {'0', '18', '>18', 'invalid'};
            if isfinite(data_max_true)
                title(sprintf('Visible-band dev threshold map F_vis(x at y~0, z), max=%.2g J/m^2 (0:black, 18:white, >18:red)', ...
                    data_max_true), 'Interpreter','none');
            else
                title('Visible-band dev threshold map F_vis(x at y~0, z), no finite valid samples (0:black, 18:white, >18:red)', ...
                    'Interpreter','none');
            end
            xlabel('z [m]');
            ylabel('x (y~0 cut) [m]');

            run_warn_state = plot_support_utils.finalize_figure_session( ...
                f_vis_bwr, visible_threshold_session, run_warn_state);
            f_vis_bwr = [];
        end
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'visible_fluence_bwr_plot_skipped', ...
            'CerUPP:Plot:VisibleFluenceBWRPlotSkipped', ...
                'dev_visible_fluence_threshold_18 skipped: missing variables or dev plots disabled.');
    end
catch me_2
    plot_support_utils.close_figure_if_valid(f_vis_bwr);
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'visible_fluence_bwr_plot_failed', ...
        'CerUPP:Plot:VisibleFluenceBWRPlotFailed', ...
        'dev_visible_fluence_threshold_18 failed: %s', me_2.message);
end

%======================================================================


%======================================================================
% Visible-band dev-threshold diagnostics using spot size near ~750 nm:
% Heuristic threshold family built around the same dev threshold used in the
% visible-band threshold map (18 J/m^2), not a universal physics criterion.
%- Detect the narrow-band radius proxy w_{750,slice}(z) from the second
% moment (1/e^2 radius) of a narrow ~750-nm weighted fluence slice using
% the same spatial weighting and the same Parseval-vs-IFFT fluence method
% selection as the other band-fluence diagnostics.
%- Compute E_vis(z) from the integrated visible fluence map:
% E_vis(z) = integral_x integral_y F_vis(x,y;z) dx dy.
%- Compute the heuristic Gaussian-equivalent energy associated with the local
% threshold:
% E_ref,750(z) = F_threshold * pi * w_{750,slice}(z)^2 / 2.
%- Plots (generated only when required stored arrays exist):
% (1) log10 visible fluence F_vis(x at y~0,z).
%     If w_{750,slice}(z) is available, overlay x0_750(z) +/- w_{750,slice}(z);
%     otherwise emit the plot without that narrow-band radius overlay.
%     Requires stored visible-fluence z-storage; the y~0 x-z slice is
%     derived internally from that stored cube (overlay additionally
%     requires stored spectral field support near 750 nm).
% (2) E_vis(z) vs the heuristic Gaussian-equivalent E_ref,750(z) in nJ
%     (threshold-reference curve only if w_{750,slice} is available).
% (3) Ratio diagnostics: 100*eta_vis, F_vis,peak/F_threshold, and
%     E_vis/E_ref,750,
% where eta_vis(z) = E_vis(z)/E_total(z).
%======================================================================
if diagnostics_flag && emit_dev_only_plots
try
    fvis_threshold_jm2   = 18;               %[J/m^2]
    fvis_threshold_m_jcm2 = 0.1 * fvis_threshold_jm2; %1 J/m^2 = 0.1 mJ/cm^2

    if isempty(D.store_z)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'visible_criterion_diagnostics_skipped_no_store_z', ...
            'CerUPP:Diagnostics:VisibleCriterionDiagnosticsSkipped', ...
            'Visible dev-threshold diagnostics skipped: store_z missing/empty.');
    elseif isempty(D.store_fluence_xy_visible)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'visible_criterion_diagnostics_skipped_no_fluence', ...
            'CerUPP:Diagnostics:VisibleCriterionDiagnosticsSkipped', ...
            'Visible dev-threshold diagnostics skipped: store_fluence_xy_visible missing/empty.');
    else
        z_plot = D.store_z(:);
        nz_2 = numel(z_plot);

        %Plot x-axis from the y~0 cut (not a cylindrical radial average)
        if ~isempty(x_cut)
            x_cut_plot = x_cut(:);
        elseif ~isempty(x)
            x_cut_plot = x(:);
        else
            x_cut_plot = [];
        end

        %Prealloc diagnostics
        evis_int   = NaN(nz_2,1);    %[J]
        etot_int   = NaN(nz_2,1);    %[J]
        fvis_peak  = NaN(nz_2,1);    %[J/m^2]
        x0_vis_line= NaN(nz_2,1);    %[m] visible-fluence centroid x(z)
        y0_vis_line= NaN(nz_2,1);    %[m] visible-fluence centroid y(z)
        x0_750_line= NaN(nz_2,1);    %[m] ~750nm-band fluence centroid x(z)
        y0_750_line= NaN(nz_2,1);    %[m] ~750nm-band fluence centroid y(z)
        w_vis_m    = NaN(nz_2,1);    %[m] 2nd-moment 1/e^2 radius from visible fluence
        w_750_m    = NaN(nz_2,1);    %[m] narrow-band ~750 nm second-moment 1/e^2 radius; dev proxy only

        %~750 nm band selection (requires stored spectral field)
        lambda_750_band_half_width_nm = 5;
        idx750_band = [];
        lam750_nm = NaN;
        have_750 = false;
        if store_diag_plan.need_store_spectral_intens_cube && ...
           ~isempty(D.store_spectral_field) && ...
           ~isempty(lambda_window)

            lambda_nm_all = lambda_window(:) * 1e9; %[nm]
            valid_lam = isfinite(lambda_nm_all) & (lambda_nm_all > 0);
            if any(valid_lam)
                idx750_band = find(valid_lam & ...
                    (abs(lambda_nm_all - 750) <= lambda_750_band_half_width_nm));
                if ~isempty(idx750_band)
                    lam750_nm = mean(lambda_nm_all(idx750_band), 'omitnan');
                    have_750 = isfinite(lam750_nm);
                end
            end
        end

        have_xy_grid = ~isempty(x) && ~isempty(y);
        x_grid_2d = [];
        y_grid_2d = [];
        have_r2_grid = false;
        x_sq = [];
        y_sq = [];
        if have_xy_grid
            [x_grid_2d, y_grid_2d] = ndgrid(x(:), y(:));
            have_r2_grid = ~isempty(x_grid_2d) && ~isempty(y_grid_2d);
            x_sq = x(:).^2;
            y_sq = y(:).^2;
        end

        if have_xy_grid
            have_total_cube = ~isempty(D.store_fluence_xy);
            for iz_local = 1:nz_2
                fvis_plane = real(D.store_fluence_xy_visible(:,:,iz_local));
                [fvis_plane, fvis_plane_nonfinite_n, naninfo, run_warn_state] = ...
                    plot_support_utils.mark_nonfinite_for_diagnostics( ...
                        fvis_plane, sprintf('Fvis_plane (visible fluence plane, iz=%d)', iz_local), ...
                        naninfo, diag_cap_hi, false, run_warn_state);
                if (fvis_plane_nonfinite_n > 0) || any(~isfinite(fvis_plane(:)))
                    continue;
                end
                fvis_plane = struct_utils.assert_nonnegative_checked( ...
                    fvis_plane, sprintf('Fvis_plane (visible fluence plane, iz=%d)', iz_local));

                evis_here = real(trapz(x, trapz(y, fvis_plane, 2), 1));
                evis_int(iz_local) = evis_here;
                fvis_peak(iz_local) = max(fvis_plane(:));

                fy_vis = trapz(y, fvis_plane, 2);    % [nx,1]
                fx_vis = trapz(x, fvis_plane, 1).';  % [ny,1]
                x0_vis_line(iz_local) = real(trapz(x, x(:) .* fy_vis, 1)) / max(real(evis_here), eps_safe);
                y0_vis_line(iz_local) = real(trapz(y, y(:) .* fx_vis, 1)) / max(real(evis_here), eps_safe);

                if have_r2_grid
                    s2_vis_here = trapz(x, x_sq .* fy_vis, 1) + trapz(y, y_sq .* fx_vis, 1);
                    r2mean_vis_here = real(s2_vis_here) / max(real(evis_here), eps_safe);
                    r2mean_vis_here = struct_utils.assert_nonnegative_checked( ...
                        r2mean_vis_here, sprintf('r2mean_vis (visible second moment, iz=%d)', iz_local));
                    r2mean_vis_c_here = max( ...
                        r2mean_vis_here - x0_vis_line(iz_local)^2 - y0_vis_line(iz_local)^2, 0);
                    % For a 2D circular Gaussian fluence F(r) ~ exp(-2*r^2/w^2),
                    % <r^2> = w^2/2, so the 1/e^2 radius is w = sqrt(2)*sqrt(<r^2>).

                    w_vis_m(iz_local) = sqrt(2) * sqrt(r2mean_vis_c_here);
                end

                if have_total_cube
                    ftot_plane = real(D.store_fluence_xy(:,:,iz_local));
                    [ftot_plane, ftot_plane_nonfinite_n, naninfo, run_warn_state] = ...
                        plot_support_utils.mark_nonfinite_for_diagnostics( ...
                            ftot_plane, sprintf('Ftot_plane (total fluence plane, iz=%d)', iz_local), ...
                            naninfo, diag_cap_hi, false, run_warn_state);
                    if (ftot_plane_nonfinite_n == 0) && all(isfinite(ftot_plane(:)))
                        ftot_plane = struct_utils.assert_nonnegative_checked( ...
                            ftot_plane, sprintf('Ftot_plane (total fluence plane, iz=%d)', iz_local));
                        etot_int(iz_local) = real(trapz(x, trapz(y, ftot_plane, 2), 1));
                    end
                end
            end
            [x0_vis_line, ~, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
                x0_vis_line, 'x0_vis_line (visible centroid x)', naninfo, diag_cap_hi, false, run_warn_state);
            [y0_vis_line, ~, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
                y0_vis_line, 'y0_vis_line (visible centroid y)', naninfo, diag_cap_hi, false, run_warn_state);
        end

        %Batched ~750 nm fluence reduction across stored z planes.
        if have_750 && have_xy_grid && have_r2_grid
            r2 = x_grid_2d.^2 + y_grid_2d.^2;
            try
                mask750_band_3d = reshape(false(size(lambda_window(:))), 1, 1, []);
                mask750_band_3d(1, 1, idx750_band) = true;
                f750_cube = band_diagnostics_utils.build_weighted_fluence_from_masked_spectrum( ...
                    D.store_spectral_field(:, :, :, 1:nz_2) .* mask750_band_3d, ...
                    medium_state.n_ratio_diag_xy, t, delta_t, fluence_use_parseval, [], ...
                    time_grid_supports_parseval_fluence);
                [f750_cube, ~, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
                    f750_cube, 'F750_cube', naninfo, diag_cap_hi, false, run_warn_state);
                bad_plane = squeeze(any(any(~isfinite(f750_cube), 1), 2));
                if any(bad_plane)
                    f750_cube(:,:,bad_plane) = NaN;
                end
                f750_cube = struct_utils.assert_nonnegative_checked(f750_cube, 'F750_cube');

                s0 = squeeze(trapz(x, trapz(y, f750_cube, 2), 1));      % [Nz,1]
                s2 = squeeze(trapz(x, trapz(y, f750_cube .* r2, 2), 1)); % [Nz,1]
                r2mean = real(s2(:)) ./ max(real(s0(:)), eps_safe);
                r2mean = struct_utils.assert_nonnegative_checked(r2mean, 'r2mean_750');
                fy_750 = squeeze(trapz(y, f750_cube, 2));                % [nx,Nz]
                sx_750 = trapz(x, x(:) .* fy_750, 1);                    % [1,Nz]
                x0_750_line = real(sx_750(:)) ./ max(real(s0(:)), eps_safe);
                [x0_750_line, ~, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
                    x0_750_line, 'x0_750_line (~750nm centroid x)', naninfo, diag_cap_hi, false, run_warn_state);
                fx_750 = squeeze(trapz(x, f750_cube, 1));                % [ny,Nz]
                sy_750 = trapz(y, y(:) .* fx_750, 1);                    % [1,Nz]
                y0_750_line = real(sy_750(:)) ./ max(real(s0(:)), eps_safe);
                [y0_750_line, ~, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
                    y0_750_line, 'y0_750_line (~750nm centroid y)', naninfo, diag_cap_hi, false, run_warn_state);
                r2mean_750_c = max(r2mean - x0_750_line.^2 - y0_750_line.^2, 0);
                w_750_m(1:nz_2) = sqrt(2) * sqrt(r2mean_750_c);
            catch me750
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    'spot_size_750nm_failed', ...
                    'CerUPP:Plot:SpotSize750nmFailed', ...
                    '750nm spot size vectorized block failed: %s', me750.message);
            end
        end

        % Dev-only visible-energy reference from the narrow-band ~750 nm radius estimate: [J]
        % This is a plotting convenience proxy, not a core propagation result.
        ethreshold_vis = fvis_threshold_jm2 * (pi * (w_750_m.^2) / 2);
        [ethreshold_vis, ethreshold_vis_nonfinite_n, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
            ethreshold_vis, 'Ethreshold_vis (visible threshold energy)', naninfo, diag_cap_hi, false, run_warn_state);
        if ethreshold_vis_nonfinite_n > 0
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'visible_threshold_energy_proxy_nonfinite', ...
                'CerUPP:Plot:VisibleThresholdEnergyProxyNonfinite', ...
                ['Ethreshold_vis is a dev-only visible-threshold proxy built from the narrow-band 750 +/- 5 nm ', ...
                 'second-moment 1/e^2 radius estimate w_750_m, not a core propagation quantity. ', ...
                 '%d stored z planes lacked usable narrow-band support for that proxy, so Ethreshold_vis is nonfinite there; ', ...
                 'this does not indicate that the main propagation physics failed.'], ...
                ethreshold_vis_nonfinite_n);
        end

        % Ratios / fractions used below are plotted as percentages in the
        % visible-threshold companion figure.
        eta_vis_total   = evis_int ./ max(etot_int, eps_safe);          %E_vis / E_total(z)
        eta_vis_in      = evis_int ./ max(etot_int(1), eps_safe);       %E_vis / E_in(total)
        ratio_e_to_threshold  = evis_int ./ max(ethreshold_vis, eps_safe); %E_vis / E_ref,750
        ratio_f_to_threshold  = fvis_peak / max(fvis_threshold_jm2, eps_safe); %F_vis,peak / F_threshold

        %---------------- Plot 1: visible fluence [dev] with the narrow-band w_{750,slice} overlay ----------------
        f_vis_log_overlay = [];
        try
            if ~isempty(store_fluence_xy_visible_r) && ~isempty(x_cut_plot)
                f_rz = real(store_fluence_xy_visible_r);
                [log_f_rz, f_rz_plot, run_warn_state] = plot_support_utils.make_log10_nonnegative_for_plot( ...
                    f_rz, eps_safe, 'F_rz (visible fluence x-z(y~0 cut) plot)', run_warn_state, 'end');

                [f_vis_log_overlay, visible_overlay_session, run_warn_state, ok_visible_overlay_session] = ...
                    plot_support_utils.begin_figure_session( ...
                        plot_session.outdir, 'dev_visible_fluence_log_with_w750_overlay', ...
                        run_warn_state, plot_session, ...
                        'create_figure', true);
                if ~ok_visible_overlay_session
                    error('CerUPP:Plot:VisibleOverlaySessionInitFailed', ...
                        'Failed to initialize visible-fluence overlay plot session.');
                end
                h_vis_log = surf(z_plot, x_cut_plot, log_f_rz, 'EdgeColor', 'none');
                shading(gca, get_plot_surface_shading_mode_local(plot_session));
                set(h_vis_log, 'FaceAlpha', 'flat', 'AlphaData', isfinite(f_rz_plot), ...
                    'AlphaDataMapping', 'none');
                view(0,90);
                set(gca,'YDir','normal'); axis tight;
                xlabel('z [m]'); ylabel('x (y~0 cut) [m]');

                have_750_centroid_line = false;
                if ~isempty(x0_750_line) && ...
                        (numel(x0_750_line) >= numel(z_plot))
                    x0_750_tmp = x0_750_line(1:numel(z_plot));
                    have_750_centroid_line = any(isfinite(x0_750_tmp(:)));
                end
                if have_750 && have_750_centroid_line
                    title(sprintf(['Visible-band log10(F_vis(x at y~0,z) [J/m^2]) [dev] with narrow-band ', ...
                        'w_{750,slice} overlay (%.0f +/- %.0f nm second-moment 1/e^2 radius; ', ...
                        '~750 nm centroid-centered only; invalid/negative masked blank)'], ...
                        lam750_nm, lambda_750_band_half_width_nm), 'Interpreter','none');
                elseif have_750
                    title(sprintf(['Visible-band log10(F_vis(x at y~0,z) [J/m^2]) [dev] (narrow-band ', ...
                        'w_{750,slice} overlay unavailable: no usable %.0f +/- %.0f nm centroid support; ', ...
                        'invalid/negative masked blank)'], ...
                        lam750_nm, lambda_750_band_half_width_nm), 'Interpreter','none');
                else
                    title(['Visible-band log10(F_vis(x at y~0,z) [J/m^2]) [dev] ', ...
                        '(narrow-band w_{750,slice} overlay unavailable: no usable ~750 nm spectral support; ', ...
                        'invalid/negative masked blank)'], 'Interpreter','none');
                end

                cb = colorbar;
                ylabel(cb, 'log10(F_vis [J/m^2]); invalid/negative masked blank');
                hold on;
                if have_750 && have_750_centroid_line
                    z_line = z_plot(:);
                    w_line = w_750_m(:);
                    x0_line = x0_750_line(1:numel(z_line));
                    x0_line = x0_line(:);
                    plot(z_line, x0_line + w_line, 'w--', 'LineWidth', 1.2);
                    plot(z_line, x0_line - w_line, 'w--', 'LineWidth', 1.2);
                end
                hold off;

                run_warn_state = plot_support_utils.finalize_figure_session( ...
                    f_vis_log_overlay, visible_overlay_session, run_warn_state);
                f_vis_log_overlay = [];
            end
        catch m_ep1
            plot_support_utils.close_figure_if_valid(f_vis_log_overlay);
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'visible_fluence_overlay_plot_failed', ...
                'CerUPP:Plot:VisibleFluenceOverlayPlotFailed', ...
                'visible fluence overlay plot failed: %s', m_ep1.message);
        end

        %---------------- Plot 2: visible energy [dev] and the E_ref,750 threshold reference ----------------
        f_vis_energy_cap = [];
        try
            [f_vis_energy_cap, visible_energy_session, run_warn_state, ok_visible_energy_session] = ...
                plot_support_utils.begin_figure_session( ...
                    plot_session.outdir, 'dev_visible_energy_vs_w750_reference', ...
                    run_warn_state, plot_session, ...
                    'create_figure', true);
            if ~ok_visible_energy_session
                error('CerUPP:Plot:VisibleEnergySessionInitFailed', ...
                    'Failed to initialize visible-energy custom plot session.');
            end
            hold on;
            plot(z_plot, evis_int*1e9, 'k-', 'LineWidth', 1.5); %[nJ]
            if have_750
                plot(z_plot, ethreshold_vis*1e9, 'r--', 'LineWidth', 1.5); %[nJ]
                legend({'E_vis = \int\int F_vis dxdy', ...
                    ['E_ref,750 = F_threshold*pi*w_{750,slice}^2/2 ', ...
                     '(w_{750,slice}: narrow-band 750 +/- 5 nm second-moment 1/e^2 radius)']}, ...
                    'Location','best');
            else
                legend({'E_vis = \int\int F_vis dxdy'}, 'Location','best');
            end
            grid on;
            xlabel('z [m]');
            ylabel('Energy [nJ]');
            if have_750
                title(sprintf(['Visible energy and the E_ref,750(z) threshold reference [dev] from F_threshold ', ...
                    '%.1f J/m^2 (%.1f mJ/cm^2)'], fvis_threshold_jm2, fvis_threshold_m_jcm2));
            else
                title('Visible energy E_vis(z) [dev; E_ref,750 reference unavailable]');
            end
            hold off;

            run_warn_state = plot_support_utils.finalize_figure_session( ...
                f_vis_energy_cap, visible_energy_session, run_warn_state);
            f_vis_energy_cap = [];
        catch m_ep2
            plot_support_utils.close_figure_if_valid(f_vis_energy_cap);
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'visible_energy_vs_cap_plot_failed', ...
                'CerUPP:Plot:VisibleEnergyVsCapPlotFailed', ...
                'visible energy vs E_ref,750 threshold reference plot failed: %s', m_ep2.message);
        end

        %---------------- Plot 3: visible ratio diagnostics shown as percentages ----------------
        f_vis_ratio_diag = [];
        try
            [f_vis_ratio_diag, visible_ratio_session, run_warn_state, ok_visible_ratio_session] = ...
                plot_support_utils.begin_figure_session( ...
                    plot_session.outdir, 'dev_visible_ratio_diagnostics_w750_reference', ...
                    run_warn_state, plot_session, ...
                    'create_figure', true);
            if ~ok_visible_ratio_session
                error('CerUPP:Plot:VisibleRatioSessionInitFailed', ...
                    'Failed to initialize visible-ratio custom plot session.');
            end
            hold on;
            h1 = plot(z_plot, 100*eta_vis_total, 'b-', 'LineWidth', 1.5);
            h2 = plot(z_plot, 100*ratio_f_to_threshold, 'k--', 'LineWidth', 1.2);
            legend_handles = [h1 h2];
            legend_labels = {'E_vis/E_total(z) [%]', ...
                'F_vis,peak/F_threshold [%]'};
            have_ratio_e_to_threshold = have_750 && any(isfinite(ratio_e_to_threshold(:)));
            if have_ratio_e_to_threshold
                h3 = plot(z_plot, 100*ratio_e_to_threshold, 'r-.', 'LineWidth', 1.2);
                legend_handles = [legend_handles h3];
                legend_labels{end+1} = 'E_vis/E_ref,750 [%]';
            end
            h4 = [];
            have_yline = (exist('yline', 'file') == 2) || (exist('yline', 'builtin') == 5);
            if have_yline
                try
                    h4 = yline(100, 'k:');
                catch me_yline
                    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                        run_warn_state, 'end', ...
                        'visible_ratio_diag_yline_failed', ...
                        'CerUPP:Plot:PlotYlineFailed', ...
                        'Failed to draw yline(100) reference marker: %s', me_yline.message);
                    h4 = [];
                end
            end
            grid on;
            xlabel('z [m]');
            ylabel('Relative level [%]');
            if have_ratio_e_to_threshold
                    title(['Visible diagnostics [dev; % scale]: total-energy and E_ref,750 levels: ', ...
                        'E_vis/E_total(z), F_vis,peak/F_threshold, E_vis/E_ref,750']);
                elseif have_750
                    title(['Visible diagnostics [dev; % scale] (reduced E_ref,750 form): ', ...
                        'E_vis/E_total(z) and F_vis,peak/F_threshold']);
                else
                    title(['Visible diagnostics [dev; % scale] (E_ref,750 reference unavailable): ', ...
                        'E_vis/E_total(z) and F_vis,peak/F_threshold']);
                end
            if ~isempty(h4) && isgraphics(h4)
                legend_handles = [legend_handles h4];
                legend_labels{end+1} = '100% reference';
            end
            legend(legend_handles, legend_labels, 'Location', 'best');
            hold off;

            run_warn_state = plot_support_utils.finalize_figure_session( ...
                f_vis_ratio_diag, visible_ratio_session, run_warn_state);
            f_vis_ratio_diag = [];
        catch m_ep3
            plot_support_utils.close_figure_if_valid(f_vis_ratio_diag);
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'visible_ratio_plot_failed', ...
                'CerUPP:Plot:VisibleRatioPlotFailed', ...
                'visible ratio plot failed: %s', m_ep3.message);
        end
    end
catch me_2
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'visible_spot_size_energy_diag_block_failed', ...
        'CerUPP:Diagnostics:VisibleSpotSizeEnergyDiagBlockFailed', ...
        'Visible dev-threshold spot-size/energy diagnostic block failed: %s', me_2.message);
end
end

%==================================================================
%Plasma time-step stiffness diagnostic (explicit pulse-frame t update for rho):
%If W_OFI,max * delta_t <= 0.1, step-size dependence is typically small.
%If W_OFI,max * delta_t >= 1, explicit updates can become qualitatively wrong (overshoot and strong step-size sensitivity).
%Same idea for avalanche: W_aval,max * delta_t controls stiffness of exponential growth.
%==================================================================
if perf_cfg.show_plasma_stiffness_diagnostic_flag
    try
        if ~isempty(plasma_stiffness_diagnostic) && isstruct(plasma_stiffness_diagnostic)
            diag = plasma_stiffness_diagnostic;
            fprintf('\n================== PLASMA STIFFNESS DIAGNOSTIC ==================\n');
            fprintf('max(W_OFI * dt)  = %.6g   (max W_OFI = %.6e 1/s at pulse-frame dt = %.6e s)\n', ...
                diag.ofi_wdt_max, diag.ofi_w_max, diag.dt_at_ofi);
            fprintf('max(W_aval * dt) = %.6g   (max W_aval= %.6e 1/s at pulse-frame dt = %.6e s)\n', ...
                diag.aval_wdt_max, diag.aval_w_max, diag.dt_at_aval);
            fprintf('Guideline: W*dt <= 0.1 => modest step-size effects; W*dt >= 1 => Euler may be qualitatively wrong for the pulse-frame density update.\n');
            fprintf('==================================================================\n\n');
        end
    catch me_2
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'plasma_stiffness_diag_print_failed', ...
            'CerUPP:Diagnostics:PlasmaStiffnessDiagnosticPrintFailed', ...
            'Plasma stiffness diagnostic print failed: %s', me_2.message);
    end
end
%==================================================================

%==================================================================
%FWHM diameter plots: total and fundamental (from spatial fluence profiles), versus z.
try
    have_total_bw_data = any(isfinite(D.store_diameter_total(:)));
    have_fund_bw_data = any(isfinite(D.store_diameter_fund(:)));
    have_bw_data = any(isfinite(D.store_z(:))) && ...
        (have_total_bw_data || have_fund_bw_data);
    emitted_fund_beamwidth_plots = false;
    if have_bw_data
        % BEAMWIDTH_REFRESH_BEFORE_PLOTS: rebuild from latest stored diagnostics

        bw_total = D.store_diameter_total(:)';
        bw_fund  = D.store_diameter_fund(:)';
        z_bw = D.store_z(:)';
        % Stored-plane traces only; no synthetic z=0 prepend is emitted.

        if have_total_bw_data
            [~, ~, ~, run_warn_state] = plot_utils.make_plot(z_bw, [], bw_total*1e6, '', ...
                'Stored-plane total-fluence FWHM diameter vs z (beam-center-tracked x/y cut proxy)', ...
                'z [m]', 'Fluence FWHM diameter [um]', ...
                'diameter_fwhm_total_vs_z', ...
                plot_session, ...
                'run_warn_state', run_warn_state);
        end

        if fundamental_band_has_any_support
            if fundamental_band_has_partial_support
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    'beamwidth_fund_plots_partial_support', ...
                    'CerUPP:Plot:BeamwidthFundPlotsPartialSupport', ...
                    ['Fundamental-band beamwidth plots are using partial support: ', ...
                     'requested %s; %s.'], ...
                    fundamental_band_requested_range_label, ...
                    fundamental_band_sampled_support_label);
            end
            if have_fund_bw_data
                [~, ~, ~, run_warn_state] = plot_utils.make_plot(z_bw, [], bw_fund*1e6, '', ...
                    sprintf(['Stored-plane fundamental-band fluence FWHM diameter vs z ', ...
                        '(fundamental-band-centered x/y cuts; %s)'], fundamental_band_plot_label), ...
                    'z [m]', 'Fluence FWHM diameter [um]', ...
                    'diameter_fwhm_fund_vs_z', ...
                    plot_session, ...
                    'run_warn_state', run_warn_state);
                emitted_fund_beamwidth_plots = true;
                if have_total_bw_data
                    [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
                        z_bw, [], [bw_total(:) bw_fund(:)]*1e6, ...
                        {'total', sprintf('fundamental-band (%s)', fundamental_band_plot_label)}, ...
                        sprintf(['Stored-plane fluence FWHM diameter vs z: total beam-center proxy ', ...
                            'and fundamental-band self-centered cuts (%s)'], ...
                            fundamental_band_plot_label), ...
                        'z [m]', 'Fluence FWHM diameter [um]', ...
                        'diameter_fwhm_total_and_fund_vs_z', ...
                        plot_session, ...
                        'run_warn_state', run_warn_state);
                end
            else
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    'beamwidth_fund_plots_skipped_no_samples', ...
                    'CerUPP:Plot:BeamwidthFundPlotsSkippedNoSamples', ...
                    'Skipping fundamental-band beamwidth plots: no finite stored fundamental-band diameter samples.');
                family_ledger = mark_postprocess_family_skipped_local( ...
                    family_ledger, 'fundamental_beamwidth_plots', ...
                    'no_finite_samples', ...
                    ['Skipping fundamental-band beamwidth plots: no finite stored ', ...
                     'fundamental-band diameter samples.']);
            end
        else
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'beamwidth_fund_plots_empty_mask', ...
                'CerUPP:Plot:BeamwidthFundPlotsEmptyMask', ...
                'Skipping fundamental-band beamwidth plots: no sampled wavelength bins fall inside the requested band.');
            family_ledger = mark_postprocess_family_skipped_local( ...
                family_ledger, 'fundamental_beamwidth_plots', ...
                'empty_requested_band', ...
                ['Skipping fundamental-band beamwidth plots: no sampled wavelength ', ...
                 'bins fall inside the requested band.']);
        end
    else
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'beamwidth_plots_skipped', ...
            'CerUPP:Plot:BeamwidthPlotsSkipped', ...
            'FWHM diameter-vs-z plots skipped: no finite diameter/z samples were stored.');
        family_ledger = mark_postprocess_family_skipped_local( ...
            family_ledger, 'fundamental_beamwidth_plots', ...
            'no_beamwidth_samples', ...
            'FWHM diameter-vs-z plots skipped: no finite diameter/z samples were stored.');
    end
    if emitted_fund_beamwidth_plots
        family_ledger = mark_postprocess_family_ok_local( ...
            family_ledger, 'fundamental_beamwidth_plots');
    end
catch me_2
    family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, 'fundamental_beamwidth_plots', me_2);
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'beamwidth_plot_failed', ...
        'CerUPP:Plot:BeamwidthPlotFailed', ...
        'FWHM diameter plot failed: %s', me_2.message);
end
if ~isempty(naninfo)
    nanlog_txt = fullfile(plot_session.outdir, 'diagnostic_naninfo.txt');
    try
        fid_nanlog = fopen(nanlog_txt, 'w');
        if fid_nanlog == -1
            error('CerUPP:Diagnostics:NonFiniteSummaryWriteFailed', ...
                'Could not open %s for writing.', nanlog_txt);
        end
        fid_cleanup = onCleanup(@() fclose(fid_nanlog)); %#ok<NASGU>

        fprintf(fid_nanlog, 'CerUPP diagnostic nonfinite summary\n');
        fprintf(fid_nanlog, 'Generated: %s\n', datestr(now, 'yyyy-mm-dd HH:MM:SS'));
        fprintf(fid_nanlog, 'Entries: %d\n\n', numel(naninfo));
        fprintf(fid_nanlog, 'idx\tlabel\tn_nan\tn_cap\tcap_hi\n');

        sum_n_nan = 0;
        sum_n_cap = 0;
        for ii = 1:numel(naninfo)
            rec = naninfo(ii);
            label_txt = '<missing>';
            if isfield(rec, 'label') && ~isempty(rec.label)
                if ischar(rec.label)
                    label_txt = rec.label;
                elseif isa(rec.label, 'string') && isscalar(rec.label)
                    label_txt = char(rec.label);
                end
            end
            label_txt = strrep(label_txt, sprintf('\t'), ' ');
            label_txt = strrep(label_txt, sprintf('\n'), ' ');
            label_txt = strrep(label_txt, sprintf('\r'), ' ');

            n_nan_i = NaN;
            n_cap_i = NaN;
            cap_hi_i = NaN;
            if isfield(rec, 'n_nan') && ~isempty(rec.n_nan)
                n_nan_i = double(rec.n_nan(1));
            end
            if isfield(rec, 'n_cap') && ~isempty(rec.n_cap)
                n_cap_i = double(rec.n_cap(1));
            end
            if isfield(rec, 'cap_hi') && ~isempty(rec.cap_hi)
                cap_hi_i = double(rec.cap_hi(1));
            end

            if isfinite(n_nan_i), sum_n_nan = sum_n_nan + max(n_nan_i, 0); end
            if isfinite(n_cap_i), sum_n_cap = sum_n_cap + max(n_cap_i, 0); end

            fprintf(fid_nanlog, '%d\t%s\t%g\t%g\t%g\n', ...
                ii, label_txt, n_nan_i, n_cap_i, cap_hi_i);
        end

        fprintf(fid_nanlog, '\nTotals\n');
        fprintf(fid_nanlog, 'sum_n_nan\t%g\n', sum_n_nan);
        fprintf(fid_nanlog, 'sum_n_cap\t%g\n', sum_n_cap);
        run_warn_state = output_io_warn_utils.record_output_io_info( ...
            run_warn_state, 'nonfinite_diagnostic_log', nanlog_txt, ...
            'CerUPP:Diagnostics:NonfiniteSummary', ...
            sprintf('Diagnostic sanitation log contains %d entries; writing %s.', ...
                numel(naninfo), char(nanlog_txt)), ...
            'end');
    catch me_nanlog
        run_warn_state = emit_postrun_output_io_failure_local( ...
            run_warn_state, 'naninfo_log_write_failed', nanlog_txt, me_nanlog, ...
            'naninfo_log_write_failed', 'CerUPP:Diagnostics:NonfiniteSummaryWriteFailed', ...
            'Failed to write nonfinite diagnostic log %s; continuing. Error: %s');
    end
end
    catch me_section6a
        postprocess_phase_ok = false;
        requested_outputs_complete = false;
        requested_outputs_skipped_reason = 'section6a_exception';
        error_id = char(me_section6a.identifier);
        error_message = char(me_section6a.message);
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'section6a_postprocess_failed', ...
            'CerUPP:Section6APostprocessFailed', ...
            ['Section 6A postprocessing failed after some output work had already started. ', ...
             'Keeping the partial family ledger and warning state collected so far. ', ...
             'Error: %s (%s)'], ...
            error_message, error_id);
    end

section6_output_io_failure_count_after = ...
    count_section6_output_io_failures_local(run_warn_state);
new_output_io_failure_count = max( ...
    section6_output_io_failure_count_after - ...
    section6_output_io_failure_count_before, 0);
    family_failure_count = count_postprocess_family_failures_local(family_ledger);
    family_skip_count = count_postprocess_family_skips_local(family_ledger);
    family_blocking_skip_count = ...
        count_postprocess_family_blocking_skips_local(family_ledger);
    if family_failure_count > 0
        requested_outputs_complete = false;
        if isempty(requested_outputs_skipped_reason)
            requested_outputs_skipped_reason = 'postprocess_family_failure';
        end
    end
    if family_blocking_skip_count > 0
        requested_outputs_complete = false;
        if isempty(requested_outputs_skipped_reason) && ...
                (family_failure_count == 0)
            requested_outputs_skipped_reason = ...
                'postprocess_blocking_family_skip';
        end
    end
    if family_skip_count > 0
        requested_outputs_complete = false;
        if isempty(requested_outputs_skipped_reason) && ...
                (family_failure_count == 0) && ...
                (family_blocking_skip_count == 0)
            requested_outputs_skipped_reason = 'postprocess_family_skip';
        end
    end
    if new_output_io_failure_count > 0
        requested_outputs_complete = false;
        if isempty(requested_outputs_skipped_reason) && ...
                (family_failure_count == 0) && ...
                (family_blocking_skip_count == 0) && ...
                (family_skip_count == 0)
            requested_outputs_skipped_reason = 'output_io_failures';
        end
    end
postprocess_state = struct( ...
    'run_warn_state', run_warn_state, ...
    'postprocess_phase_ok', postprocess_phase_ok, ...
    'requested_outputs_complete', requested_outputs_complete, ...
    'requested_outputs_skipped_reason', requested_outputs_skipped_reason, ...
    'new_output_io_failure_count', new_output_io_failure_count, ...
    'family_failure_count', family_failure_count, ...
    'family_skip_count', family_skip_count, ...
    'family_blocking_skip_count', family_blocking_skip_count, ...
    'family_ledger', family_ledger, ...
    'error_id', error_id, ...
    'error_message', error_message);
end

function family_ledger = mark_postprocess_family_ok_local(family_ledger, family_name)
% Record one successful Section 6A family pass.

    family_ledger.(family_name) = struct( ...
        'status', 'ok', ...
        'attempted', true, ...
        'ok', true, ...
        'skip_severity', '', ...
        'skip_reason', '', ...
        'skip_message', '', ...
        'error_id', '', ...
        'error_message', '');
end

function skip_message = build_point_spectrum_family_skip_message_local( ...
        emitted_tag_count, requested_tag_count)
% Summarize a partial/empty point-spectrum family outcome in one line.

    skip_message = sprintf( ...
        'Emitted %d/%d requested point-spectrum tag(s) for this family.', ...
        double(emitted_tag_count), double(requested_tag_count));
end

function family_ledger = mark_postprocess_family_skipped_local( ...
        family_ledger, family_name, skip_reason, skip_message)
% Record one requested-but-skipped Section 6A family.

    if nargin < 3 || isempty(skip_reason)
        skip_reason = 'skipped';
    end
    if nargin < 4 || isempty(skip_message)
        skip_message = '';
    end
    skip_severity = resolve_postprocess_skip_severity_local(skip_reason);
    family_ledger.(family_name) = struct( ...
        'status', 'skipped', ...
        'attempted', true, ...
        'ok', false, ...
        'skip_severity', skip_severity, ...
        'skip_reason', char(skip_reason), ...
        'skip_message', char(skip_message), ...
        'error_id', '', ...
        'error_message', '');
end

function family_ledger = mark_postprocess_family_failed_local( ...
        family_ledger, family_name, me_family)
% Record one failed Section 6A family pass.

    error_id = '';
    error_message = '';
    if nargin >= 3 && ~isempty(me_family)
        error_id = char(me_family.identifier);
        error_message = char(me_family.message);
    end
    family_ledger.(family_name) = struct( ...
        'status', 'failed', ...
        'attempted', true, ...
        'ok', false, ...
        'skip_severity', '', ...
        'skip_reason', '', ...
        'skip_message', '', ...
        'error_id', error_id, ...
        'error_message', error_message);
end

function run_warn_state = emit_stored_high_angle_review_local( ...
        run_warn_state, store_spectral_intens, store_z, kperp, n_sell, lambda_window)
% Review stored-plane spectral weight above the small-angle NA_eff threshold.

    if isempty(store_spectral_intens) || isempty(store_z) || ...
            isempty(kperp) || isempty(n_sell) || isempty(lambda_window)
        return;
    end
    if ~isequal(size(store_spectral_intens, 1), size(kperp, 1)) || ...
            ~isequal(size(store_spectral_intens, 2), size(kperp, 2)) || ...
            (size(store_spectral_intens, 3) ~= numel(n_sell)) || ...
            (numel(n_sell) ~= numel(lambda_window)) || ...
            (size(store_spectral_intens, 4) ~= numel(store_z))
        return;
    end

    high_na_threshold = 0.03;
    high_na_fraction_warn_threshold = 0.03;
    kperp_abs = double(kperp);
    k_band_med = 2*pi * real(double(n_sell(:))) ./ double(lambda_window(:));
    high_na_z_hits = [];
    high_na_fraction_hits = [];

    for iz = 1:numel(store_z)
        total_weight = 0;
        high_na_weight = 0;
        for iw = 1:numel(k_band_med)
            k_med_i = k_band_med(iw);
            if ~(isfinite(k_med_i) && (k_med_i > 0))
                continue;
            end
            slice_weight = double(store_spectral_intens(:, :, iw, iz));
            slice_weight(~isfinite(slice_weight)) = 0;
            slice_weight(slice_weight < 0) = 0;
            if ~any(slice_weight(:))
                continue;
            end
            na_map = kperp_abs / k_med_i;
            total_weight = total_weight + sum(slice_weight, 'all');
            high_na_weight = high_na_weight + ...
                sum(slice_weight(na_map > high_na_threshold), 'all');
        end
        if total_weight <= 0
            continue;
        end
        high_na_fraction = min(max(high_na_weight / total_weight, 0), 1);
        if high_na_fraction > high_na_fraction_warn_threshold
            high_na_z_hits(end+1, 1) = double(store_z(iz)); %#ok<AGROW>
            high_na_fraction_hits(end+1, 1) = high_na_fraction; %#ok<AGROW>
        end
    end

    if isempty(high_na_z_hits)
        return;
    end

    preview_count = min(numel(high_na_z_hits), 12);
    preview_parts = arrayfun( ...
        @(z_val, frac_val) sprintf('%.3f mm (%.2f%%)', ...
            1e3 * double(z_val), 100 * double(frac_val)), ...
        high_na_z_hits(1:preview_count), high_na_fraction_hits(1:preview_count), ...
        'UniformOutput', false);
    preview_text = strjoin(preview_parts, ', ');
    if numel(high_na_z_hits) > preview_count
        preview_text = sprintf('%s, ... (+%d more)', preview_text, ...
            numel(high_na_z_hits) - preview_count);
    end

    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'stored_high_angle_na_review', ...
        'CerUPP:StoredHighAngleNAReview', ...
        ['Stored-plane high-angle review: spectral weight with NA_eff > %.2f ', ...
         'exceeded %.1f%% on %d/%d stored planes at z = %s. Those bins stayed ', ...
         'inside the selected k-passband but exceed the small-angle review threshold.'], ...
        high_na_threshold, 100 * high_na_fraction_warn_threshold, ...
        numel(high_na_z_hits), numel(store_z), preview_text);
end

function failure_count = count_postprocess_family_failures_local(family_ledger)
% Count failed Section 6A output families from the local family ledger.

    failure_count = 0;
    if ~(isstruct(family_ledger) && isscalar(family_ledger))
        return;
    end
    family_names = fieldnames(family_ledger);
    for family_idx = 1:numel(family_names)
        family_state = family_ledger.(family_names{family_idx});
        if ~(isstruct(family_state) && isscalar(family_state))
            continue;
        end
        family_status = char(struct_utils.opt_struct_field( ...
            family_state, 'status', ''));
        attempted = logical(struct_utils.opt_struct_field( ...
            family_state, 'attempted', false));
        ok = logical(struct_utils.opt_struct_field( ...
            family_state, 'ok', false));
        if strcmp(family_status, 'failed')
            failure_count = failure_count + 1;
        elseif isempty(family_status) && attempted && ~ok
            failure_count = failure_count + 1;
        end
    end
end

function skip_count = count_postprocess_family_skips_local(family_ledger)
% Count requested-but-skipped Section 6A output families from the local ledger.

    skip_count = 0;
    if ~(isstruct(family_ledger) && isscalar(family_ledger))
        return;
    end
    family_names = fieldnames(family_ledger);
    for family_idx = 1:numel(family_names)
        family_state = family_ledger.(family_names{family_idx});
        if ~(isstruct(family_state) && isscalar(family_state))
            continue;
        end
        family_status = char(struct_utils.opt_struct_field( ...
            family_state, 'status', ''));
        if strcmp(family_status, 'skipped')
            skip_count = skip_count + 1;
        end
    end
end

function skip_count = count_postprocess_family_blocking_skips_local(family_ledger)
% Count skipped Section 6A families that should still downgrade the output contract.

    skip_count = 0;
    if ~(isstruct(family_ledger) && isscalar(family_ledger))
        return;
    end
    family_names = fieldnames(family_ledger);
    for family_idx = 1:numel(family_names)
        family_state = family_ledger.(family_names{family_idx});
        if ~(isstruct(family_state) && isscalar(family_state))
            continue;
        end
        family_status = char(struct_utils.opt_struct_field( ...
            family_state, 'status', ''));
        if ~strcmp(family_status, 'skipped')
            continue;
        end
        skip_severity = char(struct_utils.opt_struct_field( ...
            family_state, 'skip_severity', 'blocking'));
        if ~strcmp(skip_severity, 'soft')
            skip_count = skip_count + 1;
        end
    end
end

function skip_severity = resolve_postprocess_skip_severity_local(skip_reason)
% Classify skipped Section 6A families as soft/inapplicable vs blocking.

    skip_reason = char(skip_reason);
    soft_skip_reasons = { ...
        'axis_not_in_core_idx', ...
        'missing_band_data', ...
        'nz_plot_empty', ...
        'missing_visible_storage', ...
        'partial_band_support', ...
        'empty_requested_band', ...
        'no_finite_samples', ...
        'no_beamwidth_samples'};
    if any(strcmp(skip_reason, soft_skip_reasons))
        skip_severity = 'soft';
    else
        skip_severity = 'blocking';
    end
end

function run_warn_state = emit_postprocess_family_failure_local( ...
        run_warn_state, family_name, me_family)
% Emit one warn-once warning when a broad Section 6A family fails.

    family_label = strrep(char(family_name), '_', ' ');
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        ['section6a_' char(family_name) '_failed'], ...
        'CerUPP:Section6AFamilyFailed', ...
        ['Section 6A output family "%s" failed after propagation completed. ', ...
         'Continuing with the remaining Section 6A families. Error: %s (%s)'], ...
        family_label, char(me_family.message), ...
        char(me_family.identifier));
end

function failure_count = count_section6_output_io_failures_local(run_warn_state)
% Count output-I/O failures while excluding info-only output ledger entries.

    failure_count = 0;
    if ~(isstruct(run_warn_state) && isfield(run_warn_state, 'output_io') && ...
            isstruct(run_warn_state.output_io) && isfield(run_warn_state.output_io, 'records'))
        return;
    end
    output_io_records = run_warn_state.output_io.records;
    if isempty(output_io_records)
        return;
    end
    for rec_idx = 1:numel(output_io_records)
        rec = output_io_records(rec_idx);
        if ~isfield(rec, 'tag') || is_section6_output_io_info_record_local(rec)
            continue;
        end
        if isfield(rec, 'count') && isnumeric(rec.count) && isfinite(rec.count)
            failure_count = failure_count + max(floor(double(rec.count)), 0);
        end
    end
end

function is_info_record = is_section6_output_io_info_record_local(rec)
% Return true for successful informational output-ledger records.

    is_info_record = false;
    if ~(isstruct(rec) && isfield(rec, 'tag'))
        return;
    end
    info_tags = {'output_io', 'nonfinite_diagnostic_log'};
    tag_value = char(string(rec.tag));
    is_info_record = any(strcmp(tag_value, info_tags));
end

function [shared_detected_onset_state, naninfo, run_warn_state, family_emit_state] = emit_point_spectrum_family_local( ...
        family_cfg, point_spectrum_ctx, shared_detected_onset_state, naninfo, run_warn_state)
% Emit one stored point-spectrum family using a shared tag/load/normalize path.

    [shared_detected_onset_state, run_warn_state] = ensure_shared_detected_onset_state_local( ...
        shared_detected_onset_state, point_spectrum_ctx, run_warn_state);
    [tag_specs, run_warn_state] = build_point_spectrum_tag_specs_local( ...
        shared_detected_onset_state, numel(point_spectrum_ctx.D.store_z), family_cfg, run_warn_state);
    family_emit_state = struct( ...
        'requested_tag_count', numel(tag_specs), ...
        'emitted_tag_count', 0, ...
        'skipped_tag_count', 0);
    for tag_idx = 1:numel(tag_specs)
        tag_spec = tag_specs(tag_idx);
        if family_cfg.catch_each_tag
            try
                [tag_emitted, naninfo, run_warn_state] = emit_point_spectrum_tag_local( ...
                    family_cfg, point_spectrum_ctx, tag_spec, tag_idx, naninfo, run_warn_state);
                if tag_emitted
                    family_emit_state.emitted_tag_count = ...
                        family_emit_state.emitted_tag_count + 1;
                else
                    family_emit_state.skipped_tag_count = ...
                        family_emit_state.skipped_tag_count + 1;
                end
            catch me_point_spectrum_tag
                family_emit_state.skipped_tag_count = ...
                    family_emit_state.skipped_tag_count + 1;
                run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                    run_warn_state, 'end', ...
                    sprintf(family_cfg.tag_failure_warn_key_fmt, tag_spec.tag), ...
                    family_cfg.tag_failure_warn_id, ...
                    family_cfg.tag_failure_warn_message, ...
                    tag_spec.tag, me_point_spectrum_tag.message);
            end
        else
            [tag_emitted, naninfo, run_warn_state] = emit_point_spectrum_tag_local( ...
                family_cfg, point_spectrum_ctx, tag_spec, tag_idx, naninfo, run_warn_state);
            if tag_emitted
                family_emit_state.emitted_tag_count = ...
                    family_emit_state.emitted_tag_count + 1;
            else
                family_emit_state.skipped_tag_count = ...
                    family_emit_state.skipped_tag_count + 1;
            end
        end
    end
end

function [shared_detected_onset_state, run_warn_state] = ensure_shared_detected_onset_state_local( ...
        shared_detected_onset_state, point_spectrum_ctx, run_warn_state)
% Build the shared onset-analysis state once for all point-spectrum families.

    if isempty(shared_detected_onset_state)
        store_fluence_vis_onaxis = point_spectrum_ctx.store_fluence_vis_onaxis;
        if isempty(store_fluence_vis_onaxis)
            [~, store_fluence_vis_onaxis] = build_visible_fluence_cuts_local( ...
                point_spectrum_ctx.D.store_fluence_xy_visible, ...
                point_spectrum_ctx.iy_oa, point_spectrum_ctx.ix_oa);
        end
        [shared_detected_onset_state, run_warn_state] = ...
            filament_diagnostics_utils.build_detected_onset_analysis_state( ...
                point_spectrum_ctx.D.store_max_rho, ...
                point_spectrum_ctx.D.store_fluence_xy_visible, ...
                point_spectrum_ctx.D.store_fpeak_vis, ...
                store_fluence_vis_onaxis, ...
                point_spectrum_ctx.D.store_z, ...
                point_spectrum_ctx.ix_oa, ...
                point_spectrum_ctx.iy_oa, ...
                run_warn_state);
        if ~logical(shared_detected_onset_state.window_supported)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                'plot_onset_detect_sampling_too_coarse', ...
                'CerUPP:Diagnostics:OnsetDetectSamplingTooCoarse', ...
                build_detected_onset_sampling_warn_message_local(shared_detected_onset_state));
        end
    end
end

function [surface_xz, trace_onaxis] = build_visible_fluence_cuts_local( ...
        store_fluence_xy_visible, y_idx, ix_trace)
% Build the reused visible-fluence y~0 x-z cut and optional on-axis trace on demand.

    surface_xz = extract_y0_xz_surface_local(store_fluence_xy_visible, y_idx);
    trace_onaxis = extract_x_trace_local(surface_xz, ix_trace);
end

function [tag_specs, run_warn_state] = build_point_spectrum_tag_specs_local( ...
        shared_detected_onset_state, store_plane_count, family_cfg, run_warn_state)
% Build the z tags/titles for one point-spectrum family from shared onset state.

    valid = shared_detected_onset_state.valid;
    onset_det = shared_detected_onset_state.onset_det;
    j_final = valid(end);
    final_title = 'z_final';
    if j_final ~= store_plane_count
        final_title = 'z_final (last valid stored plane)';
    end
    tag_specs = struct('idx', j_final, 'tag', 'z_final', 'title', final_title);
    if ~logical(shared_detected_onset_state.window_supported)
        return;
    end
    if logical(onset_det.success)
        onset_indicator = char(onset_det.indicator_label);
        j_onset = valid(1);
        if isfinite(onset_det.onset_idx)
            j_onset = max(1, min(store_plane_count, double(onset_det.onset_idx)));
        end
        onset_title = sprintf(['z_onset_detected (%s onset-plane estimate; physical-z smoothing ', ...
            '%.3g m across %d stored planes)'], ...
            onset_indicator, shared_detected_onset_state.window_effective_span_m, ...
            shared_detected_onset_state.window_samples);
        if family_cfg.use_first_valid_onset_note && (j_onset == valid(1))
            onset_title = sprintf(['z_onset_detected (%s onset-plane estimate; physical-z smoothing ', ...
                '%.3g m across %d stored planes; first valid stored plane)'], ...
                onset_indicator, shared_detected_onset_state.window_effective_span_m, ...
                shared_detected_onset_state.window_samples);
        end
        tag_specs = [ ...
            struct('idx', j_onset, 'tag', 'z_onset_detected', 'title', onset_title), ...
            struct('idx', j_final, 'tag', 'z_final', 'title', final_title)];
        return;
    end
    if family_cfg.emit_onset_failure_warn
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            family_cfg.onset_failure_warn_key, ...
            family_cfg.onset_failure_warn_id, ...
            family_cfg.onset_failure_warn_message);
    end
end

function warn_message = build_detected_onset_sampling_warn_message_local(shared_detected_onset_state)
% Explain why sparse stored-z support suppresses onset-labeled exports.

    target_span_m = shared_detected_onset_state.window_target_span_m;
    median_dz_m = shared_detected_onset_state.window_median_dz_m;
    if isfinite(median_dz_m)
        warn_message = sprintf(['Skipping onset-labeled slice generation: the stored z support was not sufficient ', ...
            'to apply the built-in detected-onset smoother across at least 3 stored planes ', ...
            '(target span %.3g m, median dz %.3g m), so only z_final-tag diagnostics will be emitted.'], ...
            target_span_m, median_dz_m);
        return;
    end
    warn_message = sprintf(['Skipping onset-labeled slice generation: the stored z support was not sufficient ', ...
        'to apply the built-in %.3g m physical-z onset smoother, so only z_final-tag diagnostics will be emitted.'], ...
        target_span_m);
end

function [tag_emitted, naninfo, run_warn_state] = emit_point_spectrum_tag_local( ...
        family_cfg, point_spectrum_ctx, tag_spec, tag_idx, naninfo, run_warn_state)
% Emit OA and beam-center point-spectrum plots for one family/tag pair.

    tag_emitted = false;
    lam_plot = family_cfg.lambda_nm_plot;
    if isempty(lam_plot)
        if family_cfg.warn_on_empty_lambda_per_tag
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                sprintf(family_cfg.empty_lambda_warn_key_fmt, tag_spec.tag), ...
                family_cfg.empty_lambda_warn_id, ...
                family_cfg.empty_lambda_warn_message, ...
                tag_spec.tag);
        end
        return;
    end

    s_oa_line = resolve_stored_point_spectrum_line_local( ...
        point_spectrum_ctx.D.store_spectral_line_oa, ...
        point_spectrum_ctx.D.store_spectral_intens, ...
        tag_spec.idx, ...
        point_spectrum_ctx.ix_oa, ...
        point_spectrum_ctx.iy_oa);
    if isempty(s_oa_line)
        if family_cfg.warn_on_missing_oa_line
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                sprintf(family_cfg.missing_oa_line_warn_key_fmt, tag_spec.tag), ...
                family_cfg.missing_oa_line_warn_id, ...
                family_cfg.missing_oa_line_warn_message, ...
                tag_spec.tag);
        end
        return;
    end

    [s_plot, naninfo, run_warn_state] = build_point_spectrum_curve_local( ...
        s_oa_line, ...
        sprintf(family_cfg.oa_curve_label_fmt, tag_spec.tag), ...
        point_spectrum_ctx.spectral_lambda_ctx, ...
        family_cfg.mask_plot, ...
        naninfo, ...
        point_spectrum_ctx.diag_cap_hi, ...
        run_warn_state);
    smax = extract_point_spectrum_peak_local(s_plot);
    if isempty(smax) || (smax <= 0)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            sprintf(family_cfg.oa_scale_warn_key_fmt, tag_idx), ...
            'CerUPP:Diagnostics:NonFiniteScale', ...
            family_cfg.oa_scale_warn_message);
        smax = 1;
    end
    db0 = 10*log10(s_plot./smax + point_spectrum_ctx.eps_safe);
    db40 = db0 - 40;

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(lam_plot, [], db0, [], ...
        sprintf(family_cfg.oa_plot_title_fmt, tag_spec.title), ...
        'Vacuum wavelength [nm]', 'Level [dB]', ...
        sprintf('%s_db0_%s', family_cfg.oa_save_stem, tag_spec.tag), ...
        point_spectrum_ctx.plot_session, ...
        'run_warn_state', run_warn_state);
    tag_emitted = true;

    if point_spectrum_ctx.emit_dev_only_plots
        run_warn_state = emit_dev_point_spectrum_companion_plot_local( ...
            lam_plot, db40, ...
            sprintf(family_cfg.oa_dev_plot_title_fmt, tag_spec.title), ...
            sprintf('dev_%s_db40_%s', family_cfg.oa_save_stem, tag_spec.tag), ...
            point_spectrum_ctx.plot_session, run_warn_state);
    end

    if ~family_cfg.beam_center_offaxis_any || ...
            (tag_spec.idx < 1) || (tag_spec.idx > point_spectrum_ctx.num_storage_steps)
        return;
    end
    ix_bc_here = 1;
    iy_bc_here = 1;
    store_spectral_line_bc = [];
    if isfield(point_spectrum_ctx.D, family_cfg.store_spectral_line_bc_field)
        store_spectral_line_bc = ...
            point_spectrum_ctx.D.(family_cfg.store_spectral_line_bc_field);
    end
    if isempty(store_spectral_line_bc)
        if tag_spec.idx > family_cfg.beamcenter_spectral_plane_count
            run_warn_state = emit_short_beamcenter_spectral_history_warning_local( ...
                run_warn_state, tag_spec.idx, family_cfg.beamcenter_spectral_plane_count, ...
                sprintf('the beam-center point-spectrum tag %s', tag_spec.tag));
            return;
        end
        ix_bc_here = family_cfg.store_beamcenter_ix(tag_spec.idx);
        iy_bc_here = family_cfg.store_beamcenter_iy(tag_spec.idx);
        if ~(isscalar(ix_bc_here) && isscalar(iy_bc_here) && ...
                isfinite(ix_bc_here) && isfinite(iy_bc_here) && ...
                (ix_bc_here == round(ix_bc_here)) && ...
                (iy_bc_here == round(iy_bc_here)))
            return;
        end
    end

    s_bc_line = resolve_stored_point_spectrum_line_local( ...
        store_spectral_line_bc, ...
        point_spectrum_ctx.D.store_spectral_intens, ...
        tag_spec.idx, ix_bc_here, iy_bc_here);
    if isempty(s_bc_line)
        return;
    end

    [s_plot_bc, naninfo, run_warn_state] = build_point_spectrum_curve_local( ...
        s_bc_line, ...
        sprintf(family_cfg.bc_curve_label_fmt, tag_spec.tag), ...
        point_spectrum_ctx.spectral_lambda_ctx, ...
        family_cfg.mask_plot, ...
        naninfo, ...
        point_spectrum_ctx.diag_cap_hi, ...
        run_warn_state);
    smax_bc = extract_point_spectrum_peak_local(s_plot_bc);
    if isempty(smax_bc) || ~isfinite(smax_bc) || (smax_bc <= 0)
        smax_bc = 1;
    end
    db0_bc = 10*log10(s_plot_bc./smax_bc + point_spectrum_ctx.eps_safe);
    db40_bc = db0_bc - 40;

    [~, ~, ~, run_warn_state] = plot_utils.make_plot(lam_plot, [], db0_bc, [], ...
        sprintf(family_cfg.bc_plot_title_fmt, tag_spec.title), ...
        'Vacuum wavelength [nm]', 'Level [dB]', ...
        sprintf('%s_db0_%s', family_cfg.bc_save_stem, tag_spec.tag), ...
        point_spectrum_ctx.plot_session, ...
        'run_warn_state', run_warn_state);

    if point_spectrum_ctx.emit_dev_only_plots
        run_warn_state = emit_dev_point_spectrum_companion_plot_local( ...
            lam_plot, db40_bc, ...
            sprintf(family_cfg.bc_dev_plot_title_fmt, tag_spec.title), ...
            sprintf('dev_%s_db40_%s', family_cfg.bc_save_stem, tag_spec.tag), ...
            point_spectrum_ctx.plot_session, run_warn_state);
    end
end

function smax = extract_point_spectrum_peak_local(s_plot)
% Return the finite curve maximum for point-spectrum dB normalization.

    finite_vals = s_plot(isfinite(s_plot));
    if isempty(finite_vals)
        smax = [];
        return;
    end
    smax = max(finite_vals);
end

function [s_plot, naninfo, run_warn_state] = build_point_spectrum_curve_local( ...
        s_omega_in, curve_label, spectral_lambda_ctx, mask_plot, naninfo, diag_cap_hi, run_warn_state)
% Shared OA/beam-center point-spectrum preprocessing for consistent plotting.

    if nargin < 7 || ~isstruct(run_warn_state)
        run_warn_state = struct();
    end
    [s_omega, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
        s_omega_in(:).', ...
        sprintf('%s point-spectrum source', curve_label), ...
        'point_spectrum_curve_complex_leakage', ...
        'CerUPP:Plot:StoredSpectralComplexLeakage', ...
        run_warn_state);
    [s_omega, s_omega_nonfinite_n, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
        s_omega, sprintf('%s: S_omega', curve_label), naninfo, diag_cap_hi, false, run_warn_state);
    if s_omega_nonfinite_n > 0
        s_omega(~isfinite(s_omega)) = NaN;
    end

    s_omega_sorted = s_omega(spectral_lambda_ctx.idx_lam);
    s_lambda_sorted = s_omega_sorted .* spectral_lambda_ctx.radps_to_nm_factor_sorted;
    [s_lambda_sorted, s_lambda_nonfinite_n, naninfo, run_warn_state] = plot_support_utils.mark_nonfinite_for_diagnostics( ...
        s_lambda_sorted, sprintf('%s: S_lambda_sorted', curve_label), naninfo, diag_cap_hi, false, run_warn_state);
    if s_lambda_nonfinite_n > 0
        s_lambda_sorted(~isfinite(s_lambda_sorted)) = NaN;
    end
    [s_lambda_sorted, ~, run_warn_state] = plot_support_utils.clamp_nonnegative_diagnostic_leakage( ...
        s_lambda_sorted, sprintf('%s: S_lambda_sorted', curve_label), ...
        run_warn_state, 'end', 'point_spectrum_curve_nonnegative_clamped', ...
        'CerUPP:Plot:PointSpectrumCurveNonnegativeClamped');
    s_plot = s_lambda_sorted(mask_plot);
end

function run_warn_state = emit_dev_point_spectrum_companion_plot_local( ...
        lambda_nm_plot, level_db_curve, title_text, save_stem, plot_session, run_warn_state)
% Emit one dev-only point-spectrum companion without letting a single
% companion-plot failure suppress the parent user-facing spectrum family.

    try
        [~, ~, ~, run_warn_state] = plot_utils.make_plot(lambda_nm_plot, [], level_db_curve, [], ...
            title_text, ...
            'Vacuum wavelength [nm]', 'Level [dB]', ...
            save_stem, ...
            plot_session, ...
            'run_warn_state', run_warn_state);
    catch me_dev_point_plot
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            sprintf('dev_point_spectrum_companion_failed_%s', save_stem), ...
            'CerUPP:Plot:DevPointSpectrumCompanionFailed', ...
            'Skipping dev-only point-spectrum companion plot %s because plotting failed: %s', ...
            save_stem, me_dev_point_plot.message);
    end
end

function [cumulative_loss, cumulative_status] = build_launch_anchored_cumulative_loss_local( ...
        z_launch, store_z, loss_rate_store)
% Reconstruct cumulative loss from launch using saved z-span-average samples.

    cumulative_status = struct('ok', false, 'message', '');
    if isempty(store_z) || isempty(loss_rate_store)
        cumulative_loss = [];
        cumulative_status.message = 'stored z or stored loss-rate history is empty.';
        return;
    end
    if ~(isscalar(z_launch) && isfinite(z_launch))
        cumulative_loss = [];
        cumulative_status.message = sprintf( ...
            'z_launch must be a finite scalar; got %s.', mat2str(z_launch));
        return;
    end
    if ~(isvector(store_z) && isvector(loss_rate_store) && ...
            (numel(store_z) == numel(loss_rate_store)))
        cumulative_loss = [];
        cumulative_status.message = sprintf( ...
            ['stored loss reconstruction expects equal-length z and saved-z-span-average vectors; ', ...
             'got size(store_z)=%s and size(loss_rate_store)=%s.'], ...
            mat2str(size(store_z)), mat2str(size(loss_rate_store)));
        return;
    end
    z_store_row = double(reshape(store_z, 1, []));
    if any(~isfinite(z_store_row))
        cumulative_loss = [];
        cumulative_status.message = 'stored loss reconstruction received nonfinite z positions.';
        return;
    end
    dz_segments = diff([double(z_launch), z_store_row]);
    if any(~isfinite(dz_segments)) || any(dz_segments < 0)
        cumulative_loss = [];
        cumulative_status.message = ...
            'stored loss reconstruction requires nondecreasing finite z positions.';
        return;
    end
    loss_rate_row = reshape(real(loss_rate_store), 1, []);
    cumulative_row = zeros(size(loss_rate_row), 'like', loss_rate_row);
    if ~isempty(loss_rate_row)
        cumulative_row(1) = loss_rate_row(1) .* cast(dz_segments(1), 'like', loss_rate_row);
        for idx = 2:numel(loss_rate_row)
            interval_loss = loss_rate_row(idx) .* cast(dz_segments(idx), 'like', loss_rate_row);
            cumulative_row(idx) = cumulative_row(idx - 1) + interval_loss;
        end
    end
    cumulative_loss = reshape(cumulative_row, size(loss_rate_store));
    cumulative_status.ok = true;
end

function b_scale_trace = resolve_b_integral_scale_trace_local(D, field_name, legacy_scale, z_vec)
% Resolve one stored k0_vac*n2 scale trace, falling back to the legacy scalar path for older artifacts.

    b_scale_trace = legacy_scale;
    if nargin < 4 || isempty(z_vec)
        return;
    end
    if isstruct(D) && isfield(D, field_name)
        candidate = D.(field_name);
        if isnumeric(candidate) && isvector(candidate) && (numel(candidate) == numel(z_vec))
            b_scale_trace = reshape(candidate, size(z_vec));
        end
    end
end

function [b_trace, first_valid_z] = build_finite_aware_b_integral_trace_local(z_vec, intensity_trace, b_scale)
% Build one cumulative B-integral trace using the same finite-sample policy for every curve.

    b_trace = NaN(size(intensity_trace));
    first_valid_z = NaN;
    if isempty(z_vec) || isempty(intensity_trace)
        return;
    end
    if ~(isvector(z_vec) && isvector(intensity_trace) && (numel(z_vec) == numel(intensity_trace)))
        return;
    end
    z_row = reshape(z_vec, 1, []);
    intensity_row = reshape(intensity_trace, 1, []);
    if isscalar(b_scale)
        scale_row = repmat(cast(b_scale, 'like', intensity_row), size(z_row));
    elseif isvector(b_scale) && (numel(b_scale) == numel(z_vec))
        scale_row = reshape(cast(b_scale, 'like', intensity_row), 1, []);
    else
        return;
    end
    valid_mask = isfinite(z_row) & isfinite(intensity_row) & isfinite(scale_row);
    if any(valid_mask)
        z_valid = reshape(z_row(valid_mask), 1, []);
        intensity_valid = reshape(scale_row(valid_mask) .* intensity_row(valid_mask), 1, []);
        first_valid_z = z_valid(1);
        if numel(z_valid) == 1
            b_trace(valid_mask) = 0;
        else
            b_trace(valid_mask) = cumtrapz(z_valid, intensity_valid, 2);
        end
    end
    b_trace = reshape(b_trace, size(intensity_trace));
end

function ref_text = format_b_integral_reference_text_local(ref_z)
% Format the zero-reference note for one B-integral trace.

    if isfinite(ref_z)
        ref_text = sprintf('referenced to first finite stored sample z0 = %.3e m', ref_z);
    else
        ref_text = 'no finite stored sample';
    end
end

function max_trace = reduce_stored_time_max_local(trace_store)
% Reduce one stored z-by-t trace with a finite-aware max over time.

    if isempty(trace_store)
        max_trace = [];
        return;
    end
    n_store = size(trace_store, 1);
    trace_matrix = reshape(trace_store, n_store, []);
    finite_support = any(isfinite(trace_matrix), 2);
    max_trace = max(trace_matrix, [], 2, 'omitnan');
    max_trace(~finite_support) = NaN;
    max_trace = max_trace(:);
end

function rgb_plane = resolve_final_rgb_fluence_plane_local(diagnostic_store, channel_suffix)
% Prefer the direct final RGB plane and otherwise fall back to the last stored z slice.

    rgb_plane = [];
    channel_suffix = char(channel_suffix);
    final_field = ['final_rgb_fluence_' channel_suffix];
    store_field = ['store_rgb_fluence_' channel_suffix];
    if isfield(diagnostic_store, final_field) && ~isempty(diagnostic_store.(final_field))
        rgb_plane = diagnostic_store.(final_field);
    elseif isfield(diagnostic_store, store_field) && ~isempty(diagnostic_store.(store_field))
        rgb_plane = diagnostic_store.(store_field)(:, :, end);
    end
end

function trace_out = extract_x_trace_local(surface_xz, ix_trace)
% Extract one x-indexed z-trace from a reduced x-z surface when available.

    trace_out = [];
    if isempty(surface_xz) || isempty(ix_trace)
        return;
    end
    if ~(isscalar(ix_trace) && isnumeric(ix_trace) && isfinite(ix_trace) && (ix_trace == round(ix_trace)))
        return;
    end
    ix_trace = double(ix_trace);
    if (ix_trace < 1) || (ix_trace > size(surface_xz, 1))
        return;
    end
    trace_out = squeeze(surface_xz(ix_trace, :));
    trace_out = trace_out(:);
end

function beamcenter_state = normalize_beamcenter_state_local( ...
        beamcenter_state_in, beam_center_offaxis_any)
% Normalize the beam-center postprocess data once before Section 6 uses it.

    if nargin < 1 || ~isstruct(beamcenter_state_in) || isempty(beamcenter_state_in)
        beamcenter_state_in = struct();
    end
    if nargin < 2 || isempty(beam_center_offaxis_any)
        beam_center_offaxis_any = false;
    end

    beamcenter_state = struct( ...
        'offaxis_any', logical(struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'offaxis_any', beam_center_offaxis_any)), ...
        'store_ix', struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'store_ix', zeros(0, 1)), ...
        'store_iy', struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'store_iy', zeros(0, 1)), ...
        'store_x', struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'store_x', zeros(0, 1)), ...
        'store_y', struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'store_y', zeros(0, 1)), ...
        'store_method_code', struct_utils.opt_struct_field( ...
            beamcenter_state_in, 'store_method_code', zeros(0, 1)));

    beamcenter_state.store_ix = beamcenter_state.store_ix(:);
    beamcenter_state.store_iy = beamcenter_state.store_iy(:);
    beamcenter_state.store_x = beamcenter_state.store_x(:);
    beamcenter_state.store_y = beamcenter_state.store_y(:);
    beamcenter_state.store_method_code = beamcenter_state.store_method_code(:);
end

function run_warn_state = emit_postrun_filament_csv_specs_local( ...
        run_warn_state, filament_diag_specs, store_z, ...
        distance_to_propagate, csv_path_for_run)
% Emit the shared filament-info CSV family from one spec table.

    if nargin < 2 || isempty(filament_diag_specs)
        return;
    end
    for filament_diag_idx = 1:numel(filament_diag_specs)
        filament_diag_spec = filament_diag_specs(filament_diag_idx);
        onset_window_samples = filament_diag_spec.window_samples;
        if isempty(onset_window_samples)
            onset_window_samples = [];
        end
        [detected_onset, run_warn_state] = filament_diagnostics_utils.detect_onset_trace( ...
            filament_diag_spec.trace, store_z, filament_diag_spec.method, ...
            filament_diag_spec.reference_scalar_value, ...
            filament_diag_spec.threshold_frac, filament_diag_spec.label, ...
            onset_window_samples, run_warn_state);
        filament_diag_spec.threshold_abs = detected_onset.threshold;
        [num_fils, ent_loc, exit_loc, lengths, run_warn_state] = filament_diagnostics_utils.get_num_notches( ...
            store_z, filament_diag_spec.trace, detected_onset.threshold, run_warn_state);
        filament_info_path = csv_path_for_run(filament_diag_spec.csv_name);
        [ok_io, err_info] = filament_diagnostics_utils.write_filament_info( ...
            filament_info_path, filament_diag_spec, distance_to_propagate, ...
            num_fils, ent_loc, exit_loc, lengths);
        if ~ok_io
            run_warn_state = emit_postrun_output_io_failure_local( ...
                run_warn_state, 'filament_info_csv', filament_info_path, err_info, ...
                'filament_info_csv_failed', 'CerUPP:FilamentInfoCsvExportFailed', ...
                ['Filament-info CSV export failed (subsequent failures are summarized in output I/O diagnostics). ', ...
                 'First file: %s (%s)']);
        end
    end
end

function run_warn_state = emit_postrun_output_io_failure_local( ...
        run_warn_state, failure_tag, io_path, err_in, warn_key, warn_id, warn_fmt)
% Route one auxiliary Section 6 file-write failure through the shared output-I/O warning path.

    if nargin < 2 || isempty(failure_tag)
        failure_tag = 'output_io_failure';
    end
    if nargin < 3 || isempty(io_path)
        io_path = '';
    end
    if nargin < 5 || isempty(warn_key)
        warn_key = 'output_io_failure';
    end
    if nargin < 6 || isempty(warn_id)
        warn_id = 'CerUPP:OutputIO:Failure';
    end
    if nargin < 7 || isempty(warn_fmt)
        warn_fmt = 'Output write failed for %s (%s).';
    end

    io_path = char(io_path);
    detail_txt = '(no message)';
    if isa(err_in, 'MException')
        if ~isempty(err_in.message)
            detail_txt = err_in.message;
        end
    elseif isstruct(err_in) && isfield(err_in, 'message') && ~isempty(err_in.message)
        detail_txt = err_in.message;
    end
    detail_txt = plot_support_utils.compact_detail_text(detail_txt, 240);

    run_warn_state = output_io_warn_utils.record_output_io_failure( ...
        run_warn_state, failure_tag, io_path, err_in, 'end');
    run_warn_state = output_io_warn_utils.emit_output_io_warn_once( ...
        run_warn_state, 'end', warn_key, warn_id, warn_fmt, io_path, detail_txt);
end

function run_warn_state = emit_short_beamcenter_spectral_history_warning_local( ...
        run_warn_state, needed_plane_count, available_plane_count, consumer_label)
% Warn once when cube-backed beam-center spectral products outrun the stored beam-center history.

    if nargin < 4 || isempty(consumer_label)
        consumer_label = 'the requested beam-center spectral product';
    end
    run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
        run_warn_state, 'end', ...
        'plot_beamcenter_spectral_history_short', ...
        'CerUPP:Plot:BeamcenterSpectralHistoryShort', ...
        ['Beam-center spectral reconstruction needs %d stored beam-center planes for %s, but only %d are available. ', ...
         'Section 6A will leave the missing cube-backed beam-center spectral planes undefined and skip any affected point-spectrum tags instead of failing.'], ...
        double(needed_plane_count), consumer_label, double(available_plane_count));
end

function run_warn_state = emit_postrun_matrix_csv_specs_local(run_warn_state, csv_specs, csv_path_for_run)
% Emit one spec-driven family of matrix-valued post-run CSV files.

    if nargin < 2 || isempty(csv_specs)
        return;
    end
    for csv_idx = 1:numel(csv_specs)
        run_warn_state = storage_support.write_debug_csv_matrix_local( ...
            run_warn_state, csv_specs(csv_idx).matrix_data, ...
            csv_path_for_run(csv_specs(csv_idx).csv_name));
    end
end

function ny = spectral_fund_y_count_local(D, have_store_spectral_intens, have_store_spectral_fund_xy)
% Return the y-count for whichever central-spectrum x-y-z source is available.

    if have_store_spectral_fund_xy
        ny = size(D.store_spectral_fund_xy, 2);
    elseif have_store_spectral_intens
        ny = size(D.store_spectral_intens, 2);
    else
        ny = 0;
    end
end

function xyz_volume = extract_spectral_xyz_volume_local(store_xywz, omega_idx, z_idx)
% Extract a [Nx Ny Nz_subset] spectral volume at one omega index without copying the full z-stack.

    xyz_volume = extract_spectral_xyz_volume_indexed_local( ...
        store_xywz, 1:size(store_xywz, 1), 1:size(store_xywz, 2), omega_idx, z_idx);
end

function xyz_volume = extract_spectral_xyz_volume_indexed_local(store_xywz, x_idx, y_idx, omega_idx, z_idx)
% Extract a [numel(x_idx) numel(y_idx) numel(z_idx)] spectral volume at one omega index.

    if isempty(store_xywz) || isempty(omega_idx) || isempty(z_idx)
        xyz_volume = [];
        return;
    end
    if numel(size(store_xywz)) < 3
        error('CerUPP:InvalidSpectralVolumeRank', ...
            'Expected a stored spectral array with leading dimensions [Nx Ny Nw ...]; got %s.', ...
            mat2str(size(store_xywz)));
    end
    nx = size(store_xywz, 1);
    ny = size(store_xywz, 2);
    nw = size(store_xywz, 3);
    nz = size(store_xywz, 4);
    x_idx = x_idx(:).';
    y_idx = y_idx(:).';
    if any(~isfinite(x_idx)) || any(round(x_idx) ~= x_idx) || any(x_idx < 1) || any(x_idx > nx)
        error('CerUPP:InvalidSpectralVolumeXIndex', ...
            'x_idx must contain integers in [1,%d].', nx);
    end
    if any(~isfinite(y_idx)) || any(round(y_idx) ~= y_idx) || any(y_idx < 1) || any(y_idx > ny)
        error('CerUPP:InvalidSpectralVolumeYIndex', ...
            'y_idx must contain integers in [1,%d].', ny);
    end
    if ~(isscalar(omega_idx) && isfinite(omega_idx) && (round(omega_idx) == omega_idx) && ...
            (omega_idx >= 1) && (omega_idx <= nw))
        error('CerUPP:InvalidSpectralVolumeOmegaIndex', ...
            'omega_idx must be an integer in [1,%d]; got %g.', nw, omega_idx);
    end
    z_idx = z_idx(:).';
    if any(~isfinite(z_idx)) || any(round(z_idx) ~= z_idx) || any(z_idx < 1) || any(z_idx > nz)
        error('CerUPP:InvalidSpectralVolumeZIndex', ...
            'z_idx must contain integers in [1,%d].', nz);
    end
    xyz_volume = reshape(store_xywz(x_idx, y_idx, omega_idx, z_idx), ...
        [numel(x_idx), numel(y_idx), numel(z_idx)]);
end

function xz_cut = extract_spectral_y0_xz_surface_local(store_xywz, y_idx, omega_idx)
% Extract a fixed-y x-z cut from a [Nx Ny Nw Nz] stored spectral cube at one omega index.

    if isempty(store_xywz) || isempty(omega_idx)
        xz_cut = [];
        return;
    end
    if numel(size(store_xywz)) < 3
        error('CerUPP:InvalidSpectralHistoryRank', ...
            'Expected a stored spectral array with leading dimensions [Nx Ny Nw ...]; got %s.', ...
            mat2str(size(store_xywz)));
    end
    ny = size(store_xywz, 2);
    nw = size(store_xywz, 3);
    if ~(isscalar(y_idx) && isfinite(y_idx) && (round(y_idx) == y_idx) && ...
            (y_idx >= 1) && (y_idx <= ny))
        error('CerUPP:InvalidSpectralYCutIndex', ...
            'y_idx must be an integer in [1,%d]; got %g.', ny, y_idx);
    end
    if ~(isscalar(omega_idx) && isfinite(omega_idx) && (round(omega_idx) == omega_idx) && ...
            (omega_idx >= 1) && (omega_idx <= nw))
        error('CerUPP:InvalidSpectralOmegaIndex', ...
            'omega_idx must be an integer in [1,%d]; got %g.', nw, omega_idx);
    end
    xz_cut = reshape(store_xywz(:, y_idx, omega_idx, :), [size(store_xywz, 1), size(store_xywz, 4)]);
end

function xz_cut = extract_spectral_ytracked_xz_surface_local(store_xywz, y_idx_track, omega_idx)
% Extract an x-z cut whose y index follows one per-plane tracked beam-center path.

    if isempty(store_xywz) || isempty(omega_idx) || isempty(y_idx_track)
        xz_cut = [];
        return;
    end
    if numel(size(store_xywz)) < 4
        error('CerUPP:InvalidTrackedSpectralHistoryRank', ...
            'Expected a stored spectral array with dimensions [Nx Ny Nw Nz]; got %s.', ...
            mat2str(size(store_xywz)));
    end
    ny = size(store_xywz, 2);
    nw = size(store_xywz, 3);
    nz = size(store_xywz, 4);
    if ~(isscalar(omega_idx) && isfinite(omega_idx) && (round(omega_idx) == omega_idx) && ...
            (omega_idx >= 1) && (omega_idx <= nw))
        error('CerUPP:InvalidTrackedSpectralOmegaIndex', ...
            'omega_idx must be an integer in [1,%d]; got %g.', nw, omega_idx);
    end
    y_idx_track = y_idx_track(:);
    if numel(y_idx_track) ~= nz
        error('CerUPP:TrackedSpectralYCutCountMismatch', ...
            'numel(y_idx_track) must match Nz=%d; got %d.', nz, numel(y_idx_track));
    end
    if any(~isfinite(y_idx_track)) || any(round(y_idx_track) ~= y_idx_track) || ...
            any(y_idx_track < 1) || any(y_idx_track > ny)
        error('CerUPP:InvalidTrackedSpectralYCutIndices', ...
            'Tracked spectral y indices must be integers in [1,%d].', ny);
    end
    xz_cut = zeros(size(store_xywz, 1), nz, 'like', store_xywz);
    for zz = 1:nz
        xz_cut(:, zz) = store_xywz(:, y_idx_track(zz), omega_idx, zz);
    end
end

function xz_cut = extract_y0_xz_surface_local(history_xyz, y_idx)
% Extract a fixed-y x-z surface without squeeze-driven shape ambiguity.

    if isempty(history_xyz)
        xz_cut = [];
        return;
    end
    if numel(size(history_xyz)) < 2
        error('CerUPP:InvalidXZHistoryRank', ...
            'Expected a stored array with leading dimensions [Nx Ny ...]; got %s.', ...
            mat2str(size(history_xyz)));
    end
    ny = size(history_xyz, 2);
    if ~(isscalar(y_idx) && isfinite(y_idx) && (round(y_idx) == y_idx) && ...
            (y_idx >= 1) && (y_idx <= ny))
        error('CerUPP:InvalidYCutIndex', ...
            'y_idx must be an integer in [1,%d]; got %g.', ny, y_idx);
    end
    xz_cut = reshape(history_xyz(:, y_idx, :), [size(history_xyz, 1), size(history_xyz, 3)]);
end

function xz_cut = extract_ytracked_xz_surface_local(history_xyz, y_idx_track)
% Extract an x-z surface whose y index follows one per-plane tracked path.

    if isempty(history_xyz) || isempty(y_idx_track)
        xz_cut = [];
        return;
    end
    if numel(size(history_xyz)) < 3
        error('CerUPP:InvalidTrackedXZHistoryRank', ...
            'Expected a stored array with dimensions [Nx Ny Nz]; got %s.', ...
            mat2str(size(history_xyz)));
    end
    ny = size(history_xyz, 2);
    nz = size(history_xyz, 3);
    y_idx_track = y_idx_track(:);
    if numel(y_idx_track) ~= nz
        error('CerUPP:TrackedYCutCountMismatch', ...
            'numel(y_idx_track) must match Nz=%d; got %d.', nz, numel(y_idx_track));
    end
    if any(~isfinite(y_idx_track)) || any(round(y_idx_track) ~= y_idx_track) || ...
            any(y_idx_track < 1) || any(y_idx_track > ny)
        error('CerUPP:InvalidTrackedYCutIndices', ...
            'Tracked y indices must be integers in [1,%d].', ny);
    end
    xz_cut = zeros(size(history_xyz, 1), nz, 'like', history_xyz);
    for zz = 1:nz
        xz_cut(:, zz) = history_xyz(:, y_idx_track(zz), zz);
    end
end

function [y_idx_track, enabled, run_warn_state] = resolve_beamcenter_ytrack_local( ...
        store_iy, plane_count, ny, offaxis_any, cut_label, run_warn_state)
% Validate one beam-center y-track before x-z companion maps use it.

    y_idx_track = zeros(0, 1);
    enabled = false;
    if ~offaxis_any
        return;
    end
    if isempty(store_iy) || ~isscalar(plane_count) || (plane_count < 1)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'beamcenter_ytrack_unavailable_for_xz_companions', ...
            'CerUPP:Postprocess:BeamcenterYTrackUnavailableForXZCompanions', ...
            ['Skipping %s because the beam-center y-track was unavailable ', ...
             'after the run left the on-axis sample.'], ...
            cut_label);
        return;
    end
    store_iy = store_iy(:);
    if numel(store_iy) ~= plane_count
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'beamcenter_ytrack_count_mismatch_for_xz_companions', ...
            'CerUPP:Postprocess:BeamcenterYTrackCountMismatchForXZCompanions', ...
            ['Skipping %s because numel(store_iy)=%d does not match the ', ...
             'stored-plane count %d.'], ...
            cut_label, numel(store_iy), plane_count);
        return;
    end
    if any(~isfinite(store_iy)) || any(round(store_iy) ~= store_iy) || ...
            any(store_iy < 1) || any(store_iy > ny)
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            'beamcenter_ytrack_invalid_for_xz_companions', ...
            'CerUPP:Postprocess:BeamcenterYTrackInvalidForXZCompanions', ...
            ['Skipping %s because the beam-center y-track contains invalid ', ...
             'indices for Ny=%d.'], ...
            cut_label, ny);
        return;
    end
    y_idx_track = round(store_iy);
    enabled = true;
end

function [ratio_out, n_undefined] = ratio_with_nan_on_small_den(num_in, den_in, den_floor)
% Compute num/den without epsilon bias in the numerator.

    if nargin < 3 || isempty(den_floor) || ~isfinite(den_floor) || (den_floor <= 0)
        den_floor = eps;
    end
    if ~(isequal(size(num_in), size(den_in)) || isscalar(num_in) || isscalar(den_in))
        error('CerUPP:RatioSizeMismatch', ...
            'num_in and den_in must be same size, or one input must be scalar. Got %s vs %s.', ...
            mat2str(size(num_in)), mat2str(size(den_in)));
    end
    if ~isscalar(num_in)
        out_size = size(num_in);
    elseif ~isscalar(den_in)
        out_size = size(den_in);
    else
        out_size = size(num_in);
    end
    num_full = num_in + zeros(out_size, 'like', num_in);
    den_full = den_in + zeros(out_size, 'like', den_in);
    ratio_out = NaN(out_size);
    valid_mask = isfinite(num_full) & isfinite(den_full) & (abs(den_full) > den_floor);
    ratio_out(valid_mask) = num_full(valid_mask) ./ den_full(valid_mask);
    n_undefined = nnz(~valid_mask);
end

function s_omega_line = resolve_stored_point_spectrum_line_local( ...
        store_spectral_line, store_spectral_intens, plane_idx, ix_idx, iy_idx)
% Resolve one stored point-spectrum line from the reduced history when available.

    s_omega_line = [];
    if ~isempty(store_spectral_line)
        if isscalar(plane_idx) && isfinite(plane_idx) && ...
                (plane_idx == round(plane_idx)) && ...
                (plane_idx >= 1) && (plane_idx <= size(store_spectral_line, 1))
            s_omega_line = reshape(store_spectral_line(plane_idx, :), 1, []);
        end
        return;
    end
    if isempty(store_spectral_intens)
        return;
    end
    if ~(isscalar(plane_idx) && isfinite(plane_idx) && (plane_idx == round(plane_idx)) && ...
            isscalar(ix_idx) && isfinite(ix_idx) && (ix_idx == round(ix_idx)) && ...
            isscalar(iy_idx) && isfinite(iy_idx) && (iy_idx == round(iy_idx)))
        return;
    end
    if (plane_idx < 1) || (plane_idx > size(store_spectral_intens, 4)) || ...
            (ix_idx < 1) || (ix_idx > size(store_spectral_intens, 1)) || ...
            (iy_idx < 1) || (iy_idx > size(store_spectral_intens, 2))
        return;
    end
    s_omega_line = reshape(store_spectral_intens(ix_idx, iy_idx, :, plane_idx), 1, []);
end

function [db_surface, run_warn_state] = build_partially_masked_normalized_db_surface_local( ...
        surface_in, surface_label, warn_key, warn_id, eps_safe, run_warn_state)
% Normalize a dB map from the finite positive support only, leaving contaminated bins local.

    db_surface = NaN(size(surface_in), 'like', real(surface_in));
    finite_nonnegative_mask = isfinite(surface_in) & (surface_in >= 0);
    positive_mask = finite_nonnegative_mask & (surface_in > 0);
    if ~any(positive_mask(:))
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            sprintf('%s_no_positive_support', warn_key), ...
            warn_id, ...
            '%s has no finite positive support. Leaving the normalized dB surface NaN.', ...
            surface_label);
        return;
    end
    if any(~finite_nonnegative_mask(:))
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            warn_key, ...
            warn_id, ...
            ['%s contains non-finite or negative bins. Keeping those bins local and deriving the ', ...
             '0 dB reference from the finite positive subset only.'], ...
            surface_label);
    end
    den_surface = max(surface_in(positive_mask));
    db_surface(finite_nonnegative_mask) = 10*log10(surface_in(finite_nonnegative_mask) ./ den_surface + eps_safe);
end

function run_warn_state = emit_z_lambda_db_products_local( ...
        z_store, lambda_nm_sorted, spectral_db, title_prefix, save_stems, ...
        display_floor_note, plot_session, run_warn_state)
% Emit the paired 60 dB / 120 dB z-lambda spectral plots from one shared surface.

    clip_limits = [60, 120];
    for ii = 1:numel(clip_limits)
        clip_limit = clip_limits(ii);
        spectral_db_clip = max(min(spectral_db, 0), -clip_limit);
        title_text = sprintf([ ...
            '%s : [dB, clipped [-%d,0]; %s], 0 dB = this map max(z,lambda)'], ...
            title_prefix, clip_limit, display_floor_note);
        cbar_label = sprintf([ ...
            'independently normalized level [dB] (clipped [-%d,0]; %s)'], ...
            clip_limit, display_floor_note);
        [~, ~, ~, run_warn_state] = plot_utils.make_plot( ...
            z_store, lambda_nm_sorted, spectral_db_clip.', [], ...
            title_text, ...
            'z [m]', 'Vacuum wavelength [nm]', save_stems{ii}, ...
            plot_session, ...
            'cbar_label', cbar_label, ...
            'run_warn_state', run_warn_state);
    end
end

function run_warn_state = emit_z_lambda_db_mask_support_products_local( ...
        z_store, lambda_nm_sorted, spectral_db, mask_f_w_sorted, ...
        title_prefix, save_stems, display_floor_note, plot_session, ...
        run_warn_state)
% Emit the paired z-lambda spectral plots with omega-guard overlay lines.

    overlay_lines = build_lambda_mask_support_overlay_lines_local( ...
        z_store, lambda_nm_sorted, mask_f_w_sorted, 'filtered mask edge');
    clip_limits = [60, 120];
    for ii = 1:numel(clip_limits)
        clip_limit = clip_limits(ii);
        spectral_db_clip = max(min(spectral_db, 0), -clip_limit);
        title_text = sprintf([ ...
            '%s : [dB, clipped [-%d,0]; %s], 0 dB = this map max(z,lambda)'], ...
            title_prefix, clip_limit, display_floor_note);
        cbar_label = sprintf([ ...
            'independently normalized level [dB] (clipped [-%d,0]; %s)'], ...
            clip_limit, display_floor_note);
        run_warn_state = emit_surface_mask_support_plot_local( ...
            z_store, lambda_nm_sorted, spectral_db_clip.', title_text, ...
            'z [m]', 'Vacuum wavelength [nm]', save_stems{ii}, ...
            cbar_label, overlay_lines, plot_session, run_warn_state);
    end
end

function run_warn_state = emit_surface_mask_support_plot_local( ...
        x_plot, y_plot, z_plot, title_text, x_label, y_label, save_name, ...
        cbar_label, overlay_lines, plot_session, run_warn_state)
% Emit one heatmap companion with mask-edge overlay lines.
% These companions are the main visual masking debug surface because the
% runtime path does not yet carry a separate numeric "too much masking"
% detector.

    fig_handle = [];
    warn_key = sprintf('mask_support_plot_failed_%s', save_name);
    try
        if isempty(overlay_lines)
            run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
                run_warn_state, 'end', ...
                sprintf('mask_support_overlay_unavailable_%s', save_name), ...
                'CerUPP:Plot:MaskSupportOverlayUnavailable', ...
                'Skipping mask-support plot "%s" because no support-edge overlay could be resolved.', ...
                save_name);
            return;
        end

        [fig_handle, figure_session, run_warn_state, ok_session] = ...
            plot_support_utils.begin_figure_session( ...
                plot_session.outdir, save_name, run_warn_state, ...
                plot_session, 'create_figure', true);
        if ~ok_session
            return;
        end

        ax_handle = axes('Parent', fig_handle);
        surf(ax_handle, x_plot, y_plot, z_plot, 'EdgeColor', 'none');
        shading(ax_handle, get_plot_surface_shading_mode_local(plot_session));
        view(ax_handle, 0, 90);
        set(ax_handle, 'YDir', 'normal');
        axis(ax_handle, 'tight');
        set(ax_handle, 'DataAspectRatioMode', 'auto');
        x_limits = xlim(ax_handle);
        y_limits = ylim(ax_handle);
        colormap(ax_handle, parula);
        cb = colorbar(ax_handle);
        if ~isempty(strtrim(cbar_label))
            ylabel(cb, cbar_label, 'Interpreter', 'none');
        end

        hold(ax_handle, 'on');
        legend_handles = [];
        legend_labels = {};
        for ii = 1:numel(overlay_lines)
            x_line = overlay_lines(ii).x;
            y_line = overlay_lines(ii).y;
            if isempty(x_line) || isempty(y_line)
                continue;
            end
            line_spec = 'r-';
            if ~isempty(overlay_lines(ii).line_spec)
                line_spec = overlay_lines(ii).line_spec;
            end
            line_width = 1.5;
            if ~isempty(overlay_lines(ii).line_width)
                line_width = overlay_lines(ii).line_width;
            end
            h_line = plot(ax_handle, x_line, y_line, line_spec, ...
                'LineWidth', line_width);
            if overlay_lines(ii).show_in_legend
                legend_handles = [legend_handles, h_line]; %#ok<AGROW>
                legend_labels{end+1} = overlay_lines(ii).label; %#ok<AGROW>
            else
                set(h_line, 'HandleVisibility', 'off');
            end
        end
        hold(ax_handle, 'off');
        xlim(ax_handle, x_limits);
        ylim(ax_handle, y_limits);

        if ~isempty(legend_handles)
            legend(ax_handle, legend_handles, legend_labels, ...
                'Interpreter', 'none', 'Location', 'best');
        end
        xlabel(ax_handle, x_label, 'Interpreter', 'none');
        ylabel(ax_handle, y_label, 'Interpreter', 'none');
        title(ax_handle, title_text, 'Interpreter', 'none');

        run_warn_state = plot_support_utils.finalize_figure_session( ...
            fig_handle, figure_session, run_warn_state);
        fig_handle = [];
    catch me
        plot_support_utils.close_figure_if_valid(fig_handle);
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', warn_key, ...
            'CerUPP:Plot:MaskSupportPlotFailed', ...
            'Mask-support plot "%s" failed: %s', save_name, me.message);
    end
end

function overlay_lines = build_kx_lambda_mask_support_overlay_lines_local( ...
        lambda_nm_sorted, kx_support_abs_sorted, legend_label)
% Build the +/-k_x edge-shell overlay pair for the kx-lambda map.

    overlay_lines = empty_mask_support_overlay_lines_local();
    if isempty(lambda_nm_sorted) || isempty(kx_support_abs_sorted)
        return;
    end
    lambda_line = reshape(double(lambda_nm_sorted), 1, []);
    kx_edge = reshape(double(kx_support_abs_sorted), 1, []);
    finite_edge = isfinite(lambda_line) & isfinite(kx_edge);
    if ~any(finite_edge)
        return;
    end
    overlay_lines(1) = struct( ...
        'x', kx_edge, ...
        'y', lambda_line, ...
        'label', legend_label, ...
        'show_in_legend', true, ...
        'line_spec', 'r-', ...
        'line_width', 1.5);
    overlay_lines(2) = struct( ...
        'x', -kx_edge, ...
        'y', lambda_line, ...
        'label', legend_label, ...
        'show_in_legend', false, ...
        'line_spec', 'r-', ...
        'line_width', 1.5);
end

function overlay_lines = build_kx_lambda_exact_forward_cone_overlay_lines_local( ...
        lambda_nm_sorted, kx_cone_abs_sorted, legend_label)
% Build the +/- exact forward-cone pair |k_x| = n(omega)*omega/c.

    overlay_lines = empty_mask_support_overlay_lines_local();
    if isempty(lambda_nm_sorted) || isempty(kx_cone_abs_sorted)
        return;
    end
    lambda_line = reshape(double(lambda_nm_sorted), 1, []);
    kx_edge = reshape(double(kx_cone_abs_sorted), 1, []);
    finite_edge = isfinite(lambda_line) & isfinite(kx_edge);
    if ~any(finite_edge)
        return;
    end
    overlay_lines(1) = struct( ...
        'x', kx_edge, ...
        'y', lambda_line, ...
        'label', legend_label, ...
        'show_in_legend', true, ...
        'line_spec', 'm--', ...
        'line_width', 1.5);
    overlay_lines(2) = struct( ...
        'x', -kx_edge, ...
        'y', lambda_line, ...
        'label', legend_label, ...
        'show_in_legend', false, ...
        'line_spec', 'm--', ...
        'line_width', 1.5);
end

function overlay_lines = build_lambda_mask_support_overlay_lines_local( ...
        z_store, lambda_nm_sorted, mask_f_w_sorted, legend_label)
% Build horizontal lambda-edge overlays from the admitted omega guard band.

    overlay_lines = empty_mask_support_overlay_lines_local();
    if isempty(z_store) || isempty(lambda_nm_sorted) || isempty(mask_f_w_sorted)
        return;
    end
    support_mask = isfinite(mask_f_w_sorted(:)) & (mask_f_w_sorted(:) > 0);
    if ~any(support_mask)
        return;
    end
    [seg_start_idx, seg_stop_idx] = find_true_segments_local(support_mask);
    if isempty(seg_start_idx)
        return;
    end
    lambda_edges = [];
    for ii = 1:numel(seg_start_idx)
        lambda_edges(end+1) = double(lambda_nm_sorted(seg_start_idx(ii))); %#ok<AGROW>
        if seg_stop_idx(ii) ~= seg_start_idx(ii)
            lambda_edges(end+1) = double(lambda_nm_sorted(seg_stop_idx(ii))); %#ok<AGROW>
        end
    end
    overlay_lines = build_horizontal_mask_support_lines_local( ...
        z_store, lambda_edges, legend_label);
end

function overlay_lines = build_ycut_mask_support_overlay_lines_local( ...
        z_store, x_axis, mask_xy, y_idx, legend_label)
% Build horizontal x-edge overlays from the real-space absorber strip on
% the chosen y cut.

    overlay_lines = empty_mask_support_overlay_lines_local();
    if isempty(z_store) || isempty(x_axis) || isempty(mask_xy)
        return;
    end
    if (y_idx < 1) || (y_idx > size(mask_xy, 2)) || ...
            (size(mask_xy, 1) ~= numel(x_axis))
        return;
    end
    support_mask = isfinite(mask_xy(:, y_idx)) & ...
        (double(mask_xy(:, y_idx)) > 0);
    if ~any(support_mask)
        return;
    end
    x_support = double(x_axis(support_mask));
    overlay_lines = build_horizontal_mask_support_lines_local( ...
        z_store, [min(x_support), max(x_support)], legend_label);
end

function overlay_lines = build_horizontal_mask_support_lines_local( ...
        x_axis, y_edges, legend_label)
% Build one or more horizontal mask-edge lines across the plotted x axis.

    overlay_lines = empty_mask_support_overlay_lines_local();
    if isempty(x_axis) || isempty(y_edges)
        return;
    end
    x_axis = double(x_axis(:));
    finite_x = x_axis(isfinite(x_axis));
    if isempty(finite_x)
        return;
    end
    x_span = [min(finite_x), max(finite_x)];
    y_edges = unique(double(y_edges(:).'), 'stable');
    line_count = 0;
    for ii = 1:numel(y_edges)
        if ~isfinite(y_edges(ii))
            continue;
        end
        line_count = line_count + 1;
        overlay_lines(line_count) = struct( ...
            'x', x_span, ...
            'y', [y_edges(ii), y_edges(ii)], ...
            'label', legend_label, ...
            'show_in_legend', line_count == 1, ...
            'line_spec', 'r-', ...
            'line_width', 1.5);
    end
    if line_count == 0
        overlay_lines = empty_mask_support_overlay_lines_local();
    end
end

function kx_support_abs_sorted = compute_kx_mask_support_abs_sorted_local( ...
        kx, mask_f, mask_f_w, idx_lam)
% Resolve the max |k_x| kept by the live transverse-k mask on each lambda slice.

    kx_support_abs_sorted = NaN(numel(idx_lam), 1);
    if isempty(kx) || isempty(mask_f) || isempty(mask_f_w) || isempty(idx_lam)
        return;
    end
    if size(mask_f, 1) ~= numel(kx)
        return;
    end
    mask_f_w_vec = reshape(double(mask_f_w), [], 1);
    if size(mask_f, 3) ~= numel(mask_f_w_vec)
        return;
    end
    kx_vec = double(kx(:));
    for ilam = 1:numel(idx_lam)
        iw = idx_lam(ilam);
        if (iw < 1) || (iw > size(mask_f, 3)) || ...
                ~isfinite(mask_f_w_vec(iw)) || (mask_f_w_vec(iw) <= 0)
            continue;
        end
        support_rows = any(double(mask_f(:, :, iw)) > 0, 2);
        if any(support_rows)
            kx_support_abs_sorted(ilam) = max(abs(kx_vec(support_rows)));
        end
    end
end

function kx_cone_abs_sorted = compute_kx_exact_forward_cone_abs_sorted_local( ...
        n_sell, omega_window, idx_lam, c)
% Resolve the exact forward-cone magnitude |k_x| = n(omega)*omega/c.

    kx_cone_abs_sorted = NaN(numel(idx_lam), 1);
    if isempty(n_sell) || isempty(omega_window) || isempty(idx_lam) || ...
            isempty(c) || ~isscalar(c) || ~isfinite(c) || (double(c) == 0)
        return;
    end
    n_sell_vec = reshape(real(double(n_sell)), [], 1);
    omega_vec = reshape(double(omega_window), [], 1);
    if numel(n_sell_vec) ~= numel(omega_vec)
        return;
    end
    k_band_abs = abs((n_sell_vec .* omega_vec) ./ double(c));
    for ilam = 1:numel(idx_lam)
        iw = idx_lam(ilam);
        if (iw < 1) || (iw > numel(k_band_abs))
            continue;
        end
        if isfinite(k_band_abs(iw))
            kx_cone_abs_sorted(ilam) = k_band_abs(iw);
        end
    end
end

function [seg_start_idx, seg_stop_idx] = find_true_segments_local(mask_in)
% Return the start/stop indices of each contiguous true segment.

    seg_start_idx = [];
    seg_stop_idx = [];
    if isempty(mask_in)
        return;
    end
    mask_row = logical(mask_in(:).');
    padded_mask = [false, mask_row, false];
    seg_start_idx = find(diff(padded_mask) == 1);
    seg_stop_idx = find(diff(padded_mask) == -1) - 1;
end

function overlay_lines = empty_mask_support_overlay_lines_local()
% Return one empty overlay-line struct array for mask-support helpers.

    overlay_lines = struct( ...
        'x', {}, ...
        'y', {}, ...
        'label', {}, ...
        'show_in_legend', {}, ...
        'line_spec', {}, ...
        'line_width', {});
end

function [history_real, run_warn_state] = sanitize_stored_spectral_history_real_local( ...
        history_in, history_label, warn_key, warn_id, run_warn_state)
% Accept roundoff-sized complex leakage but blank materially complex stored spectral bins before plotting.

    history_real = real(history_in);
    if isempty(history_in)
        return;
    end
    finite_mask = isfinite(history_in);
    if ~any(finite_mask(:))
        return;
    end
    finite_real = real(history_in(finite_mask));
    tol_imag = 1e-12 * max(max(abs(finite_real(:))), 1);
    bad_complex_mask = finite_mask & (abs(imag(history_in)) > tol_imag);
    if any(bad_complex_mask(:))
        run_warn_state = run_warn_state_utils.emit_warn_once_with_phase( ...
            run_warn_state, 'end', ...
            warn_key, ...
            warn_id, ...
            ['%s contains materially complex stored spectral samples. Leaving only those bins NaN ', ...
             'before plotting (max|imag|=%.3e, tol=%.3e).'], ...
            history_label, max(abs(imag(history_in(bad_complex_mask)))), tol_imag);
        history_real(bad_complex_mask) = NaN;
    end
end

function idx_segment = extract_longest_true_segment_local(mask_in)
% Return the longest contiguous true segment as absolute indices into mask_in.

    idx_segment = [];
    if isempty(mask_in)
        return;
    end
    mask_row = logical(mask_in(:).');
    true_idx = find(mask_row);
    if isempty(true_idx)
        return;
    end
    break_idx = [0, find(diff(true_idx) > 1), numel(true_idx)];
    best_len = -1;
    best_start = 1;
    best_stop = 1;
    for kk = 1:(numel(break_idx) - 1)
        seg_start = break_idx(kk) + 1;
        seg_stop = break_idx(kk + 1);
        seg_len = seg_stop - seg_start + 1;
        if seg_len > best_len
            best_len = seg_len;
            best_start = seg_start;
            best_stop = seg_stop;
        end
    end
    idx_segment = true_idx(best_start:best_stop);
end

function txt = runtime_control_value_repr_local(v)
% Best-effort short formatter for invalid runtime-control error messages.

    try
        if ischar(v)
            txt = v;
            return;
        end
        if isa(v, 'string') && isscalar(v)
            txt = char(v);
            return;
        end
        txt = mat2str(v);
    catch
        txt = sprintf('<%s>', class(v));
    end
end

function surface_shading_mode = get_plot_surface_shading_mode_local(plot_session)
% Resolve the shared display-only surface shading mode for direct surf plots.

    surface_shading_mode = 'interp';
    if ~(isstruct(plot_session) && isscalar(plot_session) && ...
            isfield(plot_session, 'surface_shading_mode'))
        return;
    end
    [ok_parse, surface_shading_mode_candidate] = ...
        plot_support_utils.parse_surface_shading_mode(plot_session.surface_shading_mode);
    if ok_parse
        surface_shading_mode = surface_shading_mode_candidate;
    end
end

function postprocess_band_support = require_postprocess_band_contract_local(medium_state)
% Require Section 6A to receive one complete diagnostic-band contract in
% medium_state instead of backfilling missing fields from saved setup data.

    required_field_names = { ...
        'lambda_visible_band_min', 'lambda_visible_band_max', ...
        'chromatic_onset_bin_width', 'lambda_blue_band_min', ...
        'lambda_blue_band_max', 'lambda_green_band_min', ...
        'lambda_green_band_max', 'lambda_red_band_min', ...
        'lambda_red_band_max', 'lambda_fund_nm', ...
        'fundamental_band_half_width'};
    visible_field_names = {'lambda_visible_band_min', 'lambda_visible_band_max'};
    fundamental_field_names = {'lambda_fund_nm', 'fundamental_band_half_width'};
    chromatic_field_names = {'lambda_visible_band_min', 'lambda_visible_band_max', ...
        'chromatic_onset_bin_width'};
    postprocess_band_support = struct( ...
        'has_full_contract', true, ...
        'missing_fields', {{}}, ...
        'has_visible_band_contract', true, ...
        'has_fundamental_band_contract', true, ...
        'has_chromatic_contract', true, ...
        'chromatic_missing_fields', {{}});
    missing_fields = required_field_names(~isfield(medium_state, required_field_names));
    if ~isempty(missing_fields)
        error('CerUPP:PostprocessMissingMediumBandContract', ...
            ['Section 6A requires medium_state to carry the full diagnostic-band ', ...
             'contract before postprocessing starts. Missing field(s): %s. ', ...
             'Build and pass that contract in the driver instead of repopulating ', ...
             'it from saved setup metadata.'], ...
            strjoin(missing_fields, ', '));
    end
end
